  (1, 'Job Title Match', 'job_title', 'contains', 'VP', 10, 1),
  (2, 'Company Size 500+', 'employee_count', 'greater_than', '500', 8, 1),
  (3, 'High Revenue Company', 'annual_revenue', 'greater_than', '10000000', 12, 1),
  (4, 'Email Opened', 'email_opened', 'equals', 'true', 5, 1),
