  (7, 'Demo Requested', 'form_submitted', 'equals', 'demo', 25, 1),
  (8, 'LinkedIn Connection', 'source', 'equals', 'linkedin', 5, 1),
  (9, 'Referral Lead', 'source', 'equals', 'referral', 18, 1),
  (10, 'Cold Rating', 'rating', 'equals', 'cold', -5, 1);
