INSERT INTO `data_quality_rules` (`rule_id`, `rule_name`, `table_name`, `column_name`, `rule_type`, `condition`, `severity`, `is_active`) VALUES
  (1, 'Employee email not null', 'employees', 'email', 'not_null', 'IS NOT NULL', 'error', 1),
