  (4, 'Order date valid', 'sales_orders', 'order_date', 'range', 'order_date <= CURDATE()', 'warning', 1),
  (5, 'Employee code unique', 'employees', 'employee_code', 'unique', 'UNIQUE', 'error', 1),
