CREATE TABLE `countries` (`country_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `country_code` CHAR(2) NOT NULL UNIQUE, `country_name` VARCHAR(100) NOT NULL, `phone_code` VARCHAR(10), `region` VARCHAR(60), `is_active` TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
