CREATE TABLE `bank_names` (`bank_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `bank_name` VARCHAR(150) NOT NULL, `swift_code` VARCHAR(20), `country_id` SMALLINT UNSIGNED, FOREIGN KEY(`country_id`) REFERENCES `countries`(`country_id`)) ENGINE=InnoDB;
