CREATE TABLE `email_logs` (`log_id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `template_id` INT UNSIGNED, `recipient_email` VARCHAR(150) NOT NULL, `subject` VARCHAR(200), `status` ENUM('queued','sent','failed','bounced') DEFAULT 'queued', `sent_at` DATETIME, `opened_at` DATETIME, `error_message` TEXT, FOREIGN KEY(`template_id`) REFERENCES `notification_templates`(`template_id`)) ENGINE=InnoDB;
