CREATE TABLE `employee_notes` (`note_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `note_type` ENUM('general','warning','commendation','hr','disciplinary') DEFAULT 'general', `note` TEXT NOT NULL, `is_private` TINYINT(1) DEFAULT 0, `created_by` INT UNSIGNED, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `probation_reviews` (`pr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `reviewer_id` INT UNSIGNED NOT NULL, `review_date` DATE, `overall_rating` ENUM('exceeds','meets','below') DEFAULT 'meets', `recommendation` ENUM('confirm','extend','terminate') DEFAULT 'confirm', `feedback` TEXT, `status` ENUM('pending','completed') DEFAULT 'pending', FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`reviewer_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `promotions` (`promo_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `from_title_id` SMALLINT UNSIGNED, `to_title_id` SMALLINT UNSIGNED, `from_grade_id` SMALLINT UNSIGNED, `to_grade_id` SMALLINT UNSIGNED, `from_department_id` SMALLINT UNSIGNED, `to_department_id` SMALLINT UNSIGNED, `effective_date` DATE, `salary_increment` DECIMAL(12,2), `reason` TEXT, `approved_by` INT UNSIGNED, `status` ENUM('proposed','approved','rejected','cancelled') DEFAULT 'proposed', FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `transfers` (`transfer_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `from_department_id` SMALLINT UNSIGNED, `to_department_id` SMALLINT UNSIGNED, `from_location_id` SMALLINT UNSIGNED, `to_location_id` SMALLINT UNSIGNED, `from_manager_id` INT UNSIGNED, `to_manager_id` INT UNSIGNED, `effective_date` DATE, `reason` TEXT, `approved_by` INT UNSIGNED, `status` ENUM('pending','approved','rejected','completed') DEFAULT 'pending', FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `designations` (`desig_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `designation` VARCHAR(100) NOT NULL, `effective_from` DATE, `effective_to` DATE, `is_current` TINYINT(1) DEFAULT 1, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `attendance` (`attendance_id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `work_date` DATE NOT NULL, `shift_id` SMALLINT UNSIGNED, `check_in` DATETIME, `check_out` DATETIME, `check_in_location` VARCHAR(100), `check_out_location` VARCHAR(100), `check_in_method` ENUM('biometric','rfid','mobile','manual','face') DEFAULT 'manual', `status` ENUM('present','absent','half_day','wfh','holiday','leave','late') DEFAULT 'present', `working_hours` DECIMAL(4,2), `overtime_hours` DECIMAL(4,2) DEFAULT 0, `regularized` TINYINT(1) DEFAULT 0, `regularized_by` INT UNSIGNED, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`shift_id`) REFERENCES `shift_types`(`shift_id`)) ENGINE=InnoDB;
CREATE TABLE `attendance_regularizations` (`reg_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `attendance_id` BIGINT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `reason` TEXT, `requested_at` DATETIME, `approved_by` INT UNSIGNED, `status` ENUM('pending','approved','rejected') DEFAULT 'pending', FOREIGN KEY(`attendance_id`) REFERENCES `attendance`(`attendance_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `biometric_devices` (`device_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `location_id` SMALLINT UNSIGNED, `device_name` VARCHAR(80), `device_type` ENUM('fingerprint','rfid','face','iris','pin') DEFAULT 'fingerprint', `serial_no` VARCHAR(60), `ip_address` VARCHAR(45), `is_active` TINYINT(1) DEFAULT 1, `last_sync` DATETIME, FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `biometric_logs` (`bio_log_id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `device_id` SMALLINT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `punch_time` DATETIME NOT NULL, `punch_type` ENUM('in','out','break_out','break_in') DEFAULT 'in', `verification_status` ENUM('success','fail','unknown') DEFAULT 'success', FOREIGN KEY(`device_id`) REFERENCES `biometric_devices`(`device_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `leave_types` (`leave_type_id` TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `type_name` VARCHAR(60) NOT NULL, `max_days_per_year` TINYINT UNSIGNED DEFAULT 0, `carry_forward` TINYINT(1) DEFAULT 0, `max_carry_days` TINYINT UNSIGNED DEFAULT 0, `is_paid` TINYINT(1) DEFAULT 1, `gender_specific` ENUM('all','male','female') DEFAULT 'all', `requires_document` TINYINT(1) DEFAULT 0, `notice_days_required` TINYINT DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE `leave_balances` (`balance_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `leave_type_id` TINYINT UNSIGNED NOT NULL, `year` YEAR NOT NULL, `entitled_days` DECIMAL(5,1), `used_days` DECIMAL(5,1) DEFAULT 0, `pending_days` DECIMAL(5,1) DEFAULT 0, `remaining_days` DECIMAL(5,1), `carried_forward` DECIMAL(5,1) DEFAULT 0, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`leave_type_id`) REFERENCES `leave_types`(`leave_type_id`)) ENGINE=InnoDB;
CREATE TABLE `leave_requests` (`leave_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `leave_type_id` TINYINT UNSIGNED NOT NULL, `start_date` DATE NOT NULL, `end_date` DATE NOT NULL, `total_days` DECIMAL(4,1), `half_day` TINYINT(1) DEFAULT 0, `half_day_period` ENUM('morning','afternoon'), `reason` TEXT, `status` ENUM('pending','approved','rejected','cancelled','recalled') DEFAULT 'pending', `approved_by` INT UNSIGNED, `approved_at` DATETIME, `applied_on` DATETIME, `doc_url` VARCHAR(300), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`leave_type_id`) REFERENCES `leave_types`(`leave_type_id`), FOREIGN KEY(`approved_by`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `compensatory_offs` (`comp_off_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `worked_date` DATE NOT NULL, `comp_off_date` DATE, `hours_worked` DECIMAL(4,2), `reason` TEXT, `approved_by` INT UNSIGNED, `status` ENUM('pending','approved','availed','expired') DEFAULT 'pending', FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `performance_cycles` (`cycle_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `cycle_name` VARCHAR(80) NOT NULL, `period_type` ENUM('annual','semi_annual','quarterly') DEFAULT 'annual', `start_date` DATE, `end_date` DATE, `status` ENUM('planned','active','completed') DEFAULT 'planned', FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `performance_reviews` (`review_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `cycle_id` SMALLINT UNSIGNED, `employee_id` INT UNSIGNED NOT NULL, `reviewer_id` INT UNSIGNED NOT NULL, `review_type` ENUM('self','manager','peer','360') DEFAULT 'manager', `review_date` DATE, `rating` DECIMAL(3,1), `goals_score` DECIMAL(3,1), `competency_score` DECIMAL(3,1), `behavior_score` DECIMAL(3,1), `overall_score` DECIMAL(3,1), `comments` TEXT, `strengths` TEXT, `improvements` TEXT, `status` ENUM('draft','submitted','acknowledged','calibrated') DEFAULT 'draft', FOREIGN KEY(`cycle_id`) REFERENCES `performance_cycles`(`cycle_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`reviewer_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `goals` (`goal_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `cycle_id` SMALLINT UNSIGNED, `goal_title` VARCHAR(200) NOT NULL, `description` TEXT, `target_value` DECIMAL(12,2), `current_value` DECIMAL(12,2), `unit` VARCHAR(30), `weight` TINYINT UNSIGNED DEFAULT 0, `start_date` DATE, `due_date` DATE, `status` ENUM('draft','active','completed','missed','cancelled') DEFAULT 'active', `achievement_pct` DECIMAL(5,2), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`cycle_id`) REFERENCES `performance_cycles`(`cycle_id`)) ENGINE=InnoDB;
CREATE TABLE `kras` (`kra_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `goal_id` INT UNSIGNED NOT NULL, `kra_name` VARCHAR(150) NOT NULL, `kpi` VARCHAR(200), `target` DECIMAL(12,2), `achieved` DECIMAL(12,2), `weight` TINYINT UNSIGNED DEFAULT 0, FOREIGN KEY(`goal_id`) REFERENCES `goals`(`goal_id`)) ENGINE=InnoDB;
CREATE TABLE `idps` (`idp_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `goal_area` VARCHAR(150) NOT NULL, `action_items` TEXT, `resources_needed` TEXT, `target_date` DATE, `mentor_id` INT UNSIGNED, `status` ENUM('active','completed','discontinued') DEFAULT 'active', FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `disciplinary_actions` (`da_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `action_type` ENUM('verbal_warning','written_warning','pip','suspension','termination','demotion') NOT NULL, `incident_date` DATE, `action_date` DATE, `description` TEXT, `issued_by` INT UNSIGNED, `acknowledged_by_employee` TINYINT(1) DEFAULT 0, `status` ENUM('open','closed') DEFAULT 'open', FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `grievances` (`grievance_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `category` ENUM('harassment','discrimination','compensation','workload','safety','manager','policy','other') NOT NULL, `description` TEXT NOT NULL, `is_anonymous` TINYINT(1) DEFAULT 0, `status` ENUM('open','under_review','resolved','closed','escalated') DEFAULT 'open', `assigned_to` INT UNSIGNED, `resolution` TEXT, `submitted_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `resolved_at` DATETIME, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `training_programs` (`program_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `program_name` VARCHAR(150) NOT NULL, `category` VARCHAR(80), `delivery_mode` ENUM('online','classroom','blended','on_the_job') DEFAULT 'online', `duration_hours` SMALLINT UNSIGNED, `provider` VARCHAR(100), `cost` DECIMAL(10,2), `currency_id` SMALLINT UNSIGNED, `is_mandatory` TINYINT(1) DEFAULT 0, `requires_certification` TINYINT(1) DEFAULT 0, `max_participants` INT UNSIGNED, FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `training_batches` (`batch_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `program_id` SMALLINT UNSIGNED NOT NULL, `batch_name` VARCHAR(100), `start_date` DATE, `end_date` DATE, `location_id` SMALLINT UNSIGNED, `trainer_name` VARCHAR(100), `max_seats` SMALLINT UNSIGNED, `enrolled_count` SMALLINT UNSIGNED DEFAULT 0, `status` ENUM('scheduled','ongoing','completed','cancelled') DEFAULT 'scheduled', FOREIGN KEY(`program_id`) REFERENCES `training_programs`(`program_id`), FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `employee_trainings` (`et_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `program_id` SMALLINT UNSIGNED NOT NULL, `batch_id` INT UNSIGNED, `start_date` DATE, `end_date` DATE, `status` ENUM('enrolled','in_progress','completed','dropped','failed') DEFAULT 'enrolled', `score` DECIMAL(5,2), `certificate_no` VARCHAR(60), `cert_expiry` DATE, `feedback` TEXT, `rating` TINYINT UNSIGNED, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`program_id`) REFERENCES `training_programs`(`program_id`), FOREIGN KEY(`batch_id`) REFERENCES `training_batches`(`batch_id`)) ENGINE=InnoDB;
CREATE TABLE `awards_recognition` (`award_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `award_name` VARCHAR(150) NOT NULL, `category` VARCHAR(80), `awarded_by` INT UNSIGNED, `awarded_date` DATE, `description` TEXT, `monetary_value` DECIMAL(10,2), `currency_id` SMALLINT UNSIGNED, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `employee_benefits` (`benefit_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `benefit_type` ENUM('health_insurance','life_insurance','dental','vision','gym','transport','meal','housing','stock_options','car') NOT NULL, `provider` VARCHAR(100), `plan_name` VARCHAR(80), `start_date` DATE, `end_date` DATE, `employer_contribution` DECIMAL(10,2), `employee_contribution` DECIMAL(10,2), `coverage_amount` DECIMAL(12,2), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `insurance_claims` (`claim_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `benefit_id` INT UNSIGNED, `claim_date` DATE, `claim_type` VARCHAR(80), `amount_claimed` DECIMAL(10,2), `amount_approved` DECIMAL(10,2), `status` ENUM('submitted','under_review','approved','rejected','paid') DEFAULT 'submitted', `hospital_name` VARCHAR(150), `diagnosis` VARCHAR(200), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`benefit_id`) REFERENCES `employee_benefits`(`benefit_id`)) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 4: PAYROLL (25 tables)
-- ============================================================
CREATE TABLE `salary_structures` (`structure_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `structure_name` VARCHAR(100) NOT NULL, `company_id` SMALLINT UNSIGNED NOT NULL, `currency_id` SMALLINT UNSIGNED NOT NULL, `effective_from` DATE, `is_active` TINYINT(1) DEFAULT 1, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `salary_components` (`component_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `component_name` VARCHAR(80) NOT NULL, `component_code` VARCHAR(20), `component_type` ENUM('earning','deduction','benefit','reimbursement') NOT NULL, `calculation_type` ENUM('fixed','percentage','formula') DEFAULT 'fixed', `is_taxable` TINYINT(1) DEFAULT 1, `is_statutory` TINYINT(1) DEFAULT 0, `depends_on_component_id` SMALLINT UNSIGNED, `percentage_value` DECIMAL(6,4)) ENGINE=InnoDB;
CREATE TABLE `structure_components` (`sc_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `structure_id` SMALLINT UNSIGNED NOT NULL, `component_id` SMALLINT UNSIGNED NOT NULL, `amount` DECIMAL(12,2), `percentage` DECIMAL(6,4), FOREIGN KEY(`structure_id`) REFERENCES `salary_structures`(`structure_id`), FOREIGN KEY(`component_id`) REFERENCES `salary_components`(`component_id`)) ENGINE=InnoDB;
CREATE TABLE `employee_salaries` (`salary_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `structure_id` SMALLINT UNSIGNED NOT NULL, `base_salary` DECIMAL(12,2) NOT NULL, `ctc` DECIMAL(12,2), `effective_from` DATE NOT NULL, `effective_to` DATE, `currency_id` SMALLINT UNSIGNED NOT NULL, `created_by` INT UNSIGNED, `revision_reason` VARCHAR(200), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`structure_id`) REFERENCES `salary_structures`(`structure_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `salary_revisions` (`revision_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `old_salary` DECIMAL(12,2), `new_salary` DECIMAL(12,2), `increment_amount` DECIMAL(12,2), `increment_pct` DECIMAL(5,2), `effective_date` DATE, `revision_type` ENUM('annual','promotion','correction','joining','contract_renewal') DEFAULT 'annual', `approved_by` INT UNSIGNED, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `payroll_periods` (`period_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `period_name` VARCHAR(30) NOT NULL, `period_type` ENUM('monthly','bi_weekly','weekly') DEFAULT 'monthly', `start_date` DATE NOT NULL, `end_date` DATE NOT NULL, `pay_date` DATE, `status` ENUM('open','locked','processed','paid') DEFAULT 'open', FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `payroll_runs` (`payroll_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `period_id` SMALLINT UNSIGNED NOT NULL, `company_id` SMALLINT UNSIGNED NOT NULL, `run_date` DATE NOT NULL, `status` ENUM('draft','processing','completed','cancelled') DEFAULT 'draft', `total_gross` DECIMAL(16,2), `total_net` DECIMAL(16,2), `total_deductions` DECIMAL(16,2), `total_tax` DECIMAL(16,2), `employee_count` INT UNSIGNED, `processed_by` INT UNSIGNED, `approved_by` INT UNSIGNED, FOREIGN KEY(`period_id`) REFERENCES `payroll_periods`(`period_id`), FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `payslips` (`payslip_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `payroll_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `period_id` SMALLINT UNSIGNED NOT NULL, `gross_salary` DECIMAL(12,2), `basic_salary` DECIMAL(12,2), `hra` DECIMAL(12,2), `allowances` DECIMAL(12,2), `bonuses` DECIMAL(12,2), `total_deductions` DECIMAL(12,2), `pf_employee` DECIMAL(12,2), `pf_employer` DECIMAL(12,2), `esic` DECIMAL(12,2), `professional_tax` DECIMAL(12,2), `tds` DECIMAL(12,2), `net_salary` DECIMAL(12,2), `payment_date` DATE, `payment_mode` ENUM('bank_transfer','cheque','cash') DEFAULT 'bank_transfer', `bank_acc_id` INT UNSIGNED, `status` ENUM('generated','approved','paid','reversed') DEFAULT 'generated', `payslip_url` VARCHAR(300), FOREIGN KEY(`payroll_id`) REFERENCES `payroll_runs`(`payroll_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`period_id`) REFERENCES `payroll_periods`(`period_id`), FOREIGN KEY(`bank_acc_id`) REFERENCES `employee_bank_accounts`(`bank_acc_id`)) ENGINE=InnoDB;
CREATE TABLE `payslip_components` (`pc_id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `payslip_id` INT UNSIGNED NOT NULL, `component_id` SMALLINT UNSIGNED NOT NULL, `amount` DECIMAL(12,2) NOT NULL, FOREIGN KEY(`payslip_id`) REFERENCES `payslips`(`payslip_id`), FOREIGN KEY(`component_id`) REFERENCES `salary_components`(`component_id`)) ENGINE=InnoDB;
CREATE TABLE `expense_categories` (`cat_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `category_name` VARCHAR(80) NOT NULL, `max_limit` DECIMAL(10,2), `requires_receipt` TINYINT(1) DEFAULT 1, `gl_account` VARCHAR(30)) ENGINE=InnoDB;
CREATE TABLE `expense_claims` (`claim_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `claim_date` DATE NOT NULL, `category_id` SMALLINT UNSIGNED, `amount` DECIMAL(10,2) NOT NULL, `currency_id` SMALLINT UNSIGNED NOT NULL, `description` TEXT, `receipt_url` VARCHAR(300), `project_id` INT UNSIGNED, `cost_center_id` SMALLINT UNSIGNED, `status` ENUM('draft','submitted','approved','rejected','reimbursed') DEFAULT 'draft', `approved_by` INT UNSIGNED, `approved_on` DATE, `reimbursed_on` DATE, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`category_id`) REFERENCES `expense_categories`(`cat_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `travel_requests` (`travel_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `travel_type` ENUM('domestic','international') DEFAULT 'domestic', `purpose` VARCHAR(200), `from_city` VARCHAR(80), `to_city` VARCHAR(80), `departure_date` DATE, `return_date` DATE, `estimated_cost` DECIMAL(10,2), `currency_id` SMALLINT UNSIGNED, `status` ENUM('pending','approved','rejected','cancelled','completed') DEFAULT 'pending', `approved_by` INT UNSIGNED, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `travel_bookings` (`booking_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `travel_id` INT UNSIGNED NOT NULL, `booking_type` ENUM('flight','hotel','train','bus','cab','visa') NOT NULL, `vendor` VARCHAR(100), `booking_ref` VARCHAR(60), `amount` DECIMAL(10,2), `currency_id` SMALLINT UNSIGNED, `check_in` DATETIME, `check_out` DATETIME, `status` ENUM('confirmed','cancelled','modified') DEFAULT 'confirmed', FOREIGN KEY(`travel_id`) REFERENCES `travel_requests`(`travel_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `overtime_requests` (`ot_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `ot_date` DATE NOT NULL, `planned_hours` DECIMAL(4,2), `actual_hours` DECIMAL(4,2), `reason` TEXT, `approved_by` INT UNSIGNED, `status` ENUM('pending','approved','rejected') DEFAULT 'pending', `rate_multiplier` DECIMAL(3,1) DEFAULT 1.5, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `loan_types` (`loan_type_id` TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `loan_name` VARCHAR(60) NOT NULL, `max_amount` DECIMAL(12,2), `max_tenure_months` TINYINT UNSIGNED, `interest_rate` DECIMAL(5,2) DEFAULT 0, `is_active` TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE `employee_loans` (`loan_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `loan_type_id` TINYINT UNSIGNED NOT NULL, `amount` DECIMAL(12,2) NOT NULL, `tenure_months` TINYINT UNSIGNED, `emi_amount` DECIMAL(10,2), `disbursement_date` DATE, `status` ENUM('pending','approved','active','closed','rejected') DEFAULT 'pending', `approved_by` INT UNSIGNED, `balance_amount` DECIMAL(12,2), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`loan_type_id`) REFERENCES `loan_types`(`loan_type_id`)) ENGINE=InnoDB;
CREATE TABLE `loan_repayments` (`repayment_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `loan_id` INT UNSIGNED NOT NULL, `emi_no` TINYINT UNSIGNED, `due_date` DATE, `amount` DECIMAL(10,2), `principal` DECIMAL(10,2), `interest` DECIMAL(10,2), `paid_date` DATE, `status` ENUM('pending','paid','overdue') DEFAULT 'pending', FOREIGN KEY(`loan_id`) REFERENCES `employee_loans`(`loan_id`)) ENGINE=InnoDB;
CREATE TABLE `bonus_types` (`bonus_type_id` TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `bonus_name` VARCHAR(60) NOT NULL, `is_taxable` TINYINT(1) DEFAULT 1, `frequency` ENUM('annual','quarterly','one_time','on_target') DEFAULT 'annual') ENGINE=InnoDB;
CREATE TABLE `employee_bonuses` (`bonus_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `bonus_type_id` TINYINT UNSIGNED, `amount` DECIMAL(12,2) NOT NULL, `currency_id` SMALLINT UNSIGNED, `performance_year` YEAR, `payment_date` DATE, `reason` TEXT, `tax_amount` DECIMAL(10,2), `approved_by` INT UNSIGNED, `status` ENUM('pending','approved','paid') DEFAULT 'pending', FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `tax_declarations` (`td_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `financial_year` VARCHAR(10) NOT NULL, `declaration_type` ENUM('provisional','final') DEFAULT 'provisional', `total_investment` DECIMAL(12,2), `submitted_at` DATETIME, `status` ENUM('draft','submitted','verified','rejected') DEFAULT 'draft', FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `tax_declaration_items` (`tdi_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `td_id` INT UNSIGNED NOT NULL, `section` VARCHAR(20), `description` VARCHAR(150), `declared_amount` DECIMAL(10,2), `proof_url` VARCHAR(300), `verified_amount` DECIMAL(10,2), FOREIGN KEY(`td_id`) REFERENCES `tax_declarations`(`td_id`)) ENGINE=InnoDB;
CREATE TABLE `form16_records` (`f16_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `financial_year` VARCHAR(10) NOT NULL, `gross_salary` DECIMAL(12,2), `total_deductions` DECIMAL(12,2), `taxable_income` DECIMAL(12,2), `total_tax` DECIMAL(12,2), `tds_deducted` DECIMAL(12,2), `generated_at` DATETIME, `file_url` VARCHAR(300), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `pf_accounts` (`pf_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL UNIQUE, `uan_no` VARCHAR(20), `pf_account_no` VARCHAR(30), `member_since` DATE, `employee_contribution` DECIMAL(12,2) DEFAULT 0, `employer_contribution` DECIMAL(12,2) DEFAULT 0, `total_balance` DECIMAL(12,2) DEFAULT 0, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `pf_transactions` (`pft_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `pf_id` INT UNSIGNED NOT NULL, `payslip_id` INT UNSIGNED, `employee_contribution` DECIMAL(10,2), `employer_contribution` DECIMAL(10,2), `transaction_date` DATE, `period` VARCHAR(20), FOREIGN KEY(`pf_id`) REFERENCES `pf_accounts`(`pf_id`), FOREIGN KEY(`payslip_id`) REFERENCES `payslips`(`payslip_id`)) ENGINE=InnoDB;
CREATE TABLE `gratuity_records` (`gr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL UNIQUE, `eligible_from` DATE, `years_of_service` DECIMAL(5,2), `last_drawn_salary` DECIMAL(12,2), `calculated_gratuity` DECIMAL(12,2), `paid_amount` DECIMAL(12,2), `payment_date` DATE, `status` ENUM('accruing','eligible','paid') DEFAULT 'accruing', FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 5: RECRUITMENT (20 tables)
-- ============================================================
CREATE TABLE `job_postings` (`posting_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `department_id` SMALLINT UNSIGNED NOT NULL, `job_title_id` SMALLINT UNSIGNED, `title` VARCHAR(150) NOT NULL, `description` TEXT, `requirements` TEXT, `location_id` SMALLINT UNSIGNED, `is_remote` TINYINT(1) DEFAULT 0, `employment_type` ENUM('full_time','part_time','contract','intern') DEFAULT 'full_time', `experience_min` TINYINT UNSIGNED, `experience_max` TINYINT UNSIGNED, `salary_min` DECIMAL(12,2), `salary_max` DECIMAL(12,2), `currency_id` SMALLINT UNSIGNED, `no_of_openings` TINYINT UNSIGNED DEFAULT 1, `status` ENUM('draft','open','paused','closed','cancelled') DEFAULT 'draft', `posted_date` DATE, `closing_date` DATE, `posted_by` INT UNSIGNED, `priority` ENUM('low','medium','high','urgent') DEFAULT 'medium', FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`department_id`) REFERENCES `departments`(`department_id`), FOREIGN KEY(`job_title_id`) REFERENCES `job_titles`(`job_title_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `job_posting_channels` (`channel_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `posting_id` INT UNSIGNED NOT NULL, `channel_name` ENUM('website','linkedin','naukri','indeed','monster','campus','referral','agency') NOT NULL, `posted_on` DATE, `cost` DECIMAL(10,2), `status` ENUM('active','expired') DEFAULT 'active', FOREIGN KEY(`posting_id`) REFERENCES `job_postings`(`posting_id`)) ENGINE=InnoDB;
CREATE TABLE `talent_pools` (`pool_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `pool_name` VARCHAR(100) NOT NULL, `description` TEXT, `job_title_id` SMALLINT UNSIGNED, `created_by` INT UNSIGNED, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`job_title_id`) REFERENCES `job_titles`(`job_title_id`)) ENGINE=InnoDB;
CREATE TABLE `candidates` (`candidate_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `first_name` VARCHAR(60) NOT NULL, `last_name` VARCHAR(60) NOT NULL, `email` VARCHAR(150) NOT NULL UNIQUE, `phone` VARCHAR(30), `linkedin_url` VARCHAR(200), `resume_url` VARCHAR(300), `source` ENUM('job_portal','referral','linkedin','campus','agency','direct','talent_pool') DEFAULT 'direct', `current_company` VARCHAR(100), `current_title` VARCHAR(100), `total_experience` DECIMAL(4,1), `expected_salary` DECIMAL(12,2), `currency_id` SMALLINT UNSIGNED, `country_id` SMALLINT UNSIGNED, `pool_id` SMALLINT UNSIGNED, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`), FOREIGN KEY(`country_id`) REFERENCES `countries`(`country_id`), FOREIGN KEY(`pool_id`) REFERENCES `talent_pools`(`pool_id`)) ENGINE=InnoDB;
CREATE TABLE `candidate_skills` (`cs_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `candidate_id` INT UNSIGNED NOT NULL, `skill_name` VARCHAR(80), `proficiency` ENUM('beginner','intermediate','advanced','expert') DEFAULT 'intermediate', FOREIGN KEY(`candidate_id`) REFERENCES `candidates`(`candidate_id`)) ENGINE=InnoDB;
CREATE TABLE `candidate_education` (`ce_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `candidate_id` INT UNSIGNED NOT NULL, `institution` VARCHAR(150), `degree` VARCHAR(100), `field_of_study` VARCHAR(100), `graduation_year` YEAR, FOREIGN KEY(`candidate_id`) REFERENCES `candidates`(`candidate_id`)) ENGINE=InnoDB;
CREATE TABLE `job_applications` (`application_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `posting_id` INT UNSIGNED NOT NULL, `candidate_id` INT UNSIGNED NOT NULL, `applied_date` DATE NOT NULL, `status` ENUM('applied','screening','shortlisted','interview','assessment','offer','hired','rejected','withdrawn','on_hold') DEFAULT 'applied', `rejection_reason` VARCHAR(200), `assigned_to` INT UNSIGNED, `referral_employee_id` INT UNSIGNED, `notes` TEXT, `source` VARCHAR(60), `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(`posting_id`) REFERENCES `job_postings`(`posting_id`), FOREIGN KEY(`candidate_id`) REFERENCES `candidates`(`candidate_id`), FOREIGN KEY(`assigned_to`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `application_status_history` (`history_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `application_id` INT UNSIGNED NOT NULL, `old_status` VARCHAR(30), `new_status` VARCHAR(30), `changed_by` INT UNSIGNED, `changed_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `remarks` VARCHAR(200), FOREIGN KEY(`application_id`) REFERENCES `job_applications`(`application_id`)) ENGINE=InnoDB;
CREATE TABLE `interview_rounds` (`round_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `posting_id` INT UNSIGNED NOT NULL, `round_no` TINYINT UNSIGNED, `round_name` VARCHAR(60) NOT NULL, `round_type` ENUM('screening','technical','hr','cultural','case_study','panel','final') NOT NULL, `duration_mins` SMALLINT UNSIGNED, `is_mandatory` TINYINT(1) DEFAULT 1, FOREIGN KEY(`posting_id`) REFERENCES `job_postings`(`posting_id`)) ENGINE=InnoDB;
CREATE TABLE `interviews` (`interview_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `application_id` INT UNSIGNED NOT NULL, `round_id` SMALLINT UNSIGNED, `interviewer_id` INT UNSIGNED NOT NULL, `interview_type` ENUM('phone','video','in_person','panel') NOT NULL, `scheduled_at` DATETIME NOT NULL, `duration_mins` SMALLINT UNSIGNED, `location` VARCHAR(100), `meeting_link` VARCHAR(300), `status` ENUM('scheduled','completed','rescheduled','no_show','cancelled') DEFAULT 'scheduled', `rating` TINYINT UNSIGNED, `recommendation` ENUM('strong_yes','yes','neutral','no','strong_no'), `feedback` TEXT, `scorecard` JSON, FOREIGN KEY(`application_id`) REFERENCES `job_applications`(`application_id`), FOREIGN KEY(`round_id`) REFERENCES `interview_rounds`(`round_id`), FOREIGN KEY(`interviewer_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `interview_scorecards` (`scorecard_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `interview_id` INT UNSIGNED NOT NULL, `criterion` VARCHAR(100), `score` TINYINT UNSIGNED, `max_score` TINYINT UNSIGNED DEFAULT 10, `comments` TEXT, FOREIGN KEY(`interview_id`) REFERENCES `interviews`(`interview_id`)) ENGINE=InnoDB;
CREATE TABLE `assessments` (`assessment_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `application_id` INT UNSIGNED NOT NULL, `assessment_type` ENUM('aptitude','coding','case_study','psychometric','language','domain') NOT NULL, `platform` VARCHAR(80), `test_link` VARCHAR(300), `scheduled_at` DATETIME, `completed_at` DATETIME, `score` DECIMAL(5,2), `max_score` DECIMAL(5,2), `result` ENUM('pass','fail','pending') DEFAULT 'pending', FOREIGN KEY(`application_id`) REFERENCES `job_applications`(`application_id`)) ENGINE=InnoDB;
CREATE TABLE `offer_letters` (`offer_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `application_id` INT UNSIGNED NOT NULL, `candidate_id` INT UNSIGNED NOT NULL, `posting_id` INT UNSIGNED NOT NULL, `offered_salary` DECIMAL(12,2), `offered_ctc` DECIMAL(12,2), `currency_id` SMALLINT UNSIGNED, `joining_date` DATE, `offer_date` DATE, `expiry_date` DATE, `offer_url` VARCHAR(300), `status` ENUM('draft','sent','accepted','rejected','withdrawn','expired') DEFAULT 'draft', `rejection_reason` VARCHAR(200), `approved_by` INT UNSIGNED, FOREIGN KEY(`application_id`) REFERENCES `job_applications`(`application_id`), FOREIGN KEY(`candidate_id`) REFERENCES `candidates`(`candidate_id`)) ENGINE=InnoDB;
CREATE TABLE `background_checks` (`check_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `candidate_id` INT UNSIGNED NOT NULL, `application_id` INT UNSIGNED, `check_type` ENUM('criminal','employment','education','reference','credit','drug') NOT NULL, `vendor` VARCHAR(100), `initiated_on` DATE, `completed_on` DATE, `status` ENUM('pending','in_progress','completed','failed') DEFAULT 'pending', `result` ENUM('clear','flagged','incomplete'), `report_url` VARCHAR(300), FOREIGN KEY(`candidate_id`) REFERENCES `candidates`(`candidate_id`)) ENGINE=InnoDB;
CREATE TABLE `onboarding_tasks` (`task_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `task_name` VARCHAR(150) NOT NULL, `category` ENUM('it_setup','hr_docs','training','benefits','equipment','access') NOT NULL, `due_days_after_joining` TINYINT UNSIGNED, `assigned_to_role` VARCHAR(60), `is_mandatory` TINYINT(1) DEFAULT 1, `instructions` TEXT) ENGINE=InnoDB;
CREATE TABLE `employee_onboarding` (`ob_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL UNIQUE, `offer_id` INT UNSIGNED, `buddy_id` INT UNSIGNED, `it_setup_date` DATE, `hr_induction_date` DATE, `orientation_date` DATE, `probation_start` DATE, `onboarding_status` ENUM('not_started','in_progress','completed') DEFAULT 'not_started', FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`offer_id`) REFERENCES `offer_letters`(`offer_id`)) ENGINE=InnoDB;
CREATE TABLE `onboarding_checklist` (`checklist_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `ob_id` INT UNSIGNED NOT NULL, `task_id` SMALLINT UNSIGNED NOT NULL, `assigned_to` INT UNSIGNED, `due_date` DATE, `completed_at` DATETIME, `status` ENUM('pending','in_progress','completed','skipped') DEFAULT 'pending', `remarks` VARCHAR(200), FOREIGN KEY(`ob_id`) REFERENCES `employee_onboarding`(`ob_id`), FOREIGN KEY(`task_id`) REFERENCES `onboarding_tasks`(`task_id`)) ENGINE=InnoDB;
CREATE TABLE `referral_programs` (`program_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `program_name` VARCHAR(100) NOT NULL, `bonus_amount` DECIMAL(10,2), `currency_id` SMALLINT UNSIGNED, `start_date` DATE, `end_date` DATE, `is_active` TINYINT(1) DEFAULT 1, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `referrals` (`referral_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `program_id` SMALLINT UNSIGNED, `referrer_employee_id` INT UNSIGNED NOT NULL, `candidate_id` INT UNSIGNED NOT NULL, `application_id` INT UNSIGNED, `referral_date` DATE, `bonus_status` ENUM('pending','eligible','paid','not_eligible') DEFAULT 'pending', `bonus_paid_date` DATE, FOREIGN KEY(`referrer_employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`candidate_id`) REFERENCES `candidates`(`candidate_id`)) ENGINE=InnoDB;
CREATE TABLE `agency_contracts` (`contract_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `agency_name` VARCHAR(150) NOT NULL, `contact_person` VARCHAR(100), `email` VARCHAR(150), `phone` VARCHAR(30), `fee_pct` DECIMAL(5,2), `replacement_guarantee_days` TINYINT UNSIGNED, `start_date` DATE, `end_date` DATE, `status` ENUM('active','expired','terminated') DEFAULT 'active') ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 6: OFFBOARDING & RESIGNATIONS (15 tables)
-- ============================================================
CREATE TABLE `resignation_requests` (`resignation_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `resignation_date` DATE NOT NULL, `last_working_date` DATE, `notice_period_days` SMALLINT UNSIGNED, `reason_type` ENUM('personal','better_opportunity','relocation','higher_studies','health','retirement','involuntary','contract_end','other') NOT NULL, `reason_details` TEXT, `status` ENUM('submitted','acknowledged','approved','retracted','completed') DEFAULT 'submitted', `approved_by` INT UNSIGNED, `approved_at` DATETIME, `submitted_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `notice_period_waivers` (`waiver_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `resignation_id` INT UNSIGNED NOT NULL, `waiver_type` ENUM('full','partial') NOT NULL, `waiver_days` SMALLINT UNSIGNED, `reason` TEXT, `approved_by` INT UNSIGNED, `status` ENUM('requested','approved','rejected') DEFAULT 'requested', `notice_buyout_amount` DECIMAL(10,2), FOREIGN KEY(`resignation_id`) REFERENCES `resignation_requests`(`resignation_id`)) ENGINE=InnoDB;
CREATE TABLE `exit_interviews` (`exit_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `resignation_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `interviewer_id` INT UNSIGNED, `interview_date` DATE, `reasons_for_leaving` TEXT, `satisfaction_score` TINYINT UNSIGNED, `would_recommend` TINYINT(1), `feedback_on_manager` TEXT, `feedback_on_company` TEXT, `feedback_on_culture` TEXT, `return_interest` TINYINT(1), `status` ENUM('scheduled','completed','skipped') DEFAULT 'scheduled', FOREIGN KEY(`resignation_id`) REFERENCES `resignation_requests`(`resignation_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `exit_checklist_items` (`item_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `item_name` VARCHAR(150) NOT NULL, `category` ENUM('it','hr','finance','admin','security','project') NOT NULL, `responsible_dept` VARCHAR(60), `due_days_before_last_day` TINYINT, `is_mandatory` TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE `employee_exit_checklist` (`ec_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `resignation_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `item_id` SMALLINT UNSIGNED NOT NULL, `assigned_to` INT UNSIGNED, `due_date` DATE, `completed_at` DATETIME, `status` ENUM('pending','completed','waived') DEFAULT 'pending', `remarks` VARCHAR(200), FOREIGN KEY(`resignation_id`) REFERENCES `resignation_requests`(`resignation_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`item_id`) REFERENCES `exit_checklist_items`(`item_id`)) ENGINE=InnoDB;
CREATE TABLE `asset_returns` (`return_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `resignation_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `asset_id` INT UNSIGNED, `asset_description` VARCHAR(150), `return_date` DATE, `condition` ENUM('good','damaged','missing') DEFAULT 'good', `deduction_amount` DECIMAL(10,2) DEFAULT 0, `received_by` INT UNSIGNED, `remarks` VARCHAR(200), FOREIGN KEY(`resignation_id`) REFERENCES `resignation_requests`(`resignation_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `fnf_settlements` (`fnf_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `resignation_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `last_working_date` DATE, `leave_encashment` DECIMAL(12,2) DEFAULT 0, `bonus_payable` DECIMAL(12,2) DEFAULT 0, `gratuity` DECIMAL(12,2) DEFAULT 0, `notice_recovery` DECIMAL(12,2) DEFAULT 0, `loan_recovery` DECIMAL(12,2) DEFAULT 0, `other_deductions` DECIMAL(12,2) DEFAULT 0, `net_payable` DECIMAL(12,2), `payment_date` DATE, `status` ENUM('pending','in_progress','approved','paid') DEFAULT 'pending', `approved_by` INT UNSIGNED, FOREIGN KEY(`resignation_id`) REFERENCES `resignation_requests`(`resignation_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `rehire_eligibility` (`rh_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `is_eligible` TINYINT(1) DEFAULT 1, `reason_if_ineligible` VARCHAR(200), `eligible_after_date` DATE, `assessed_by` INT UNSIGNED, `assessed_at` DATETIME, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `alumni_records` (`alumni_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL UNIQUE, `last_company_id` SMALLINT UNSIGNED, `last_designation` VARCHAR(100), `years_of_service` DECIMAL(5,2), `exit_type` ENUM('voluntary','involuntary','retirement','contract_end') NOT NULL, `current_employer` VARCHAR(150), `current_role` VARCHAR(100), `linkedin_url` VARCHAR(200), `alumni_email` VARCHAR(150), `enrolled_in_alumni_program` TINYINT(1) DEFAULT 0, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `terminations` (`termination_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `termination_type` ENUM('layoff','performance','misconduct','contract_end','retirement','death','resignation') NOT NULL, `effective_date` DATE NOT NULL, `initiated_by` INT UNSIGNED, `approved_by` INT UNSIGNED, `reason` TEXT, `severance_amount` DECIMAL(12,2), `pip_reference_id` INT UNSIGNED, `da_reference_id` INT UNSIGNED, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `severance_packages` (`sp_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `termination_id` INT UNSIGNED NOT NULL, `base_weeks_per_year` DECIMAL(4,2), `total_weeks` DECIMAL(6,2), `weekly_salary` DECIMAL(10,2), `total_amount` DECIMAL(12,2), `currency_id` SMALLINT UNSIGNED, `payment_schedule` ENUM('lump_sum','installments') DEFAULT 'lump_sum', `nda_signed` TINYINT(1) DEFAULT 0, FOREIGN KEY(`termination_id`) REFERENCES `terminations`(`termination_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `pips` (`pip_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `manager_id` INT UNSIGNED NOT NULL, `start_date` DATE, `end_date` DATE, `goals` TEXT, `metrics` TEXT, `support_provided` TEXT, `status` ENUM('active','completed','extended','failed','withdrawn') DEFAULT 'active', `outcome` ENUM('improved','terminated','resigned','extended'), `review_meetings_count` TINYINT UNSIGNED DEFAULT 0, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`manager_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `retirement_records` (`ret_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL UNIQUE, `retirement_date` DATE, `retirement_type` ENUM('voluntary','mandatory','early') DEFAULT 'mandatory', `superannuation_amount` DECIMAL(12,2), `pension_eligible` TINYINT(1) DEFAULT 0, `pension_amount` DECIMAL(10,2), `farewell_arranged` TINYINT(1) DEFAULT 0, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `knowledge_transfer_plans` (`ktp_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `resignation_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `successor_id` INT UNSIGNED, `tasks_documented` TINYINT(1) DEFAULT 0, `handover_doc_url` VARCHAR(300), `start_date` DATE, `end_date` DATE, `status` ENUM('not_started','in_progress','completed') DEFAULT 'not_started', FOREIGN KEY(`resignation_id`) REFERENCES `resignation_requests`(`resignation_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `hr_clearance_forms` (`clearance_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `resignation_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `hr_cleared` TINYINT(1) DEFAULT 0, `finance_cleared` TINYINT(1) DEFAULT 0, `it_cleared` TINYINT(1) DEFAULT 0, `admin_cleared` TINYINT(1) DEFAULT 0, `projects_cleared` TINYINT(1) DEFAULT 0, `overall_cleared` TINYINT(1) DEFAULT 0, `cleared_date` DATE, `cleared_by` INT UNSIGNED, FOREIGN KEY(`resignation_id`) REFERENCES `resignation_requests`(`resignation_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;

