-- ============================================================
--  DOMAIN 7: CRM (35 tables)
-- ============================================================
CREATE TABLE `crm_accounts` (`account_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `account_name` VARCHAR(150) NOT NULL, `account_type` ENUM('prospect','customer','partner','vendor','competitor','reseller') DEFAULT 'prospect', `industry_id` SMALLINT UNSIGNED, `website` VARCHAR(200), `phone` VARCHAR(30), `email` VARCHAR(150), `annual_revenue` DECIMAL(16,2), `employee_count` INT UNSIGNED, `country_id` SMALLINT UNSIGNED, `city` VARCHAR(80), `address` VARCHAR(200), `linkedin_url` VARCHAR(200), `assigned_to` INT UNSIGNED, `parent_account_id` INT UNSIGNED, `status` ENUM('active','inactive','churned','dormant') DEFAULT 'active', `tier` ENUM('platinum','gold','silver','bronze') DEFAULT 'bronze', `nps_score` TINYINT, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(`industry_id`) REFERENCES `industries`(`industry_id`), FOREIGN KEY(`country_id`) REFERENCES `countries`(`country_id`), FOREIGN KEY(`assigned_to`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`parent_account_id`) REFERENCES `crm_accounts`(`account_id`)) ENGINE=InnoDB;
CREATE TABLE `crm_contacts` (`contact_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `account_id` INT UNSIGNED, `first_name` VARCHAR(60) NOT NULL, `last_name` VARCHAR(60) NOT NULL, `email` VARCHAR(150), `phone` VARCHAR(30), `mobile` VARCHAR(30), `job_title` VARCHAR(100), `department` VARCHAR(80), `is_primary` TINYINT(1) DEFAULT 0, `is_decision_maker` TINYINT(1) DEFAULT 0, `linkedin_url` VARCHAR(200), `source` ENUM('website','referral','event','cold_call','social','other') DEFAULT 'website', `assigned_to` INT UNSIGNED, `do_not_call` TINYINT(1) DEFAULT 0, `do_not_email` TINYINT(1) DEFAULT 0, `subscribed_to_newsletter` TINYINT(1) DEFAULT 1, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`assigned_to`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `crm_leads` (`lead_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `first_name` VARCHAR(60) NOT NULL, `last_name` VARCHAR(60) NOT NULL, `email` VARCHAR(150), `phone` VARCHAR(30), `company_name` VARCHAR(150), `job_title` VARCHAR(100), `source` ENUM('website','referral','event','cold_call','social','ad_campaign','other') DEFAULT 'website', `status` ENUM('new','contacted','qualified','unqualified','converted','recycled') DEFAULT 'new', `rating` ENUM('hot','warm','cold') DEFAULT 'cold', `industry_id` SMALLINT UNSIGNED, `country_id` SMALLINT UNSIGNED, `annual_revenue` DECIMAL(16,2), `assigned_to` INT UNSIGNED, `converted_to_contact_id` INT UNSIGNED, `converted_to_account_id` INT UNSIGNED, `converted_date` DATE, `campaign_id` INT UNSIGNED, `score` TINYINT UNSIGNED DEFAULT 0, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`industry_id`) REFERENCES `industries`(`industry_id`), FOREIGN KEY(`country_id`) REFERENCES `countries`(`country_id`), FOREIGN KEY(`assigned_to`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`converted_to_contact_id`) REFERENCES `crm_contacts`(`contact_id`), FOREIGN KEY(`converted_to_account_id`) REFERENCES `crm_accounts`(`account_id`)) ENGINE=InnoDB;
CREATE TABLE `lead_scoring_rules` (`rule_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `rule_name` VARCHAR(100) NOT NULL, `criteria_field` VARCHAR(60), `criteria_operator` ENUM('equals','contains','greater_than','less_than','is_set') DEFAULT 'equals', `criteria_value` VARCHAR(100), `score_change` TINYINT, `is_active` TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE `lead_score_history` (`score_id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `lead_id` INT UNSIGNED NOT NULL, `old_score` TINYINT, `new_score` TINYINT, `rule_id` SMALLINT UNSIGNED, `changed_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`lead_id`) REFERENCES `crm_leads`(`lead_id`)) ENGINE=InnoDB;
CREATE TABLE `crm_campaigns` (`campaign_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `campaign_name` VARCHAR(150) NOT NULL, `campaign_type` ENUM('email','social','webinar','event','ppc','seo','referral','print','tv') NOT NULL, `status` ENUM('planned','active','paused','completed','cancelled') DEFAULT 'planned', `start_date` DATE, `end_date` DATE, `budget` DECIMAL(12,2), `actual_spend` DECIMAL(12,2), `currency_id` SMALLINT UNSIGNED, `target_leads` INT UNSIGNED, `actual_leads` INT UNSIGNED DEFAULT 0, `impressions` INT UNSIGNED DEFAULT 0, `clicks` INT UNSIGNED DEFAULT 0, `conversions` INT UNSIGNED DEFAULT 0, `owner_id` INT UNSIGNED, `description` TEXT, FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`), FOREIGN KEY(`owner_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `campaign_email_lists` (`list_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `campaign_id` INT UNSIGNED NOT NULL, `contact_id` INT UNSIGNED, `email` VARCHAR(150), `status` ENUM('queued','sent','opened','clicked','bounced','unsubscribed') DEFAULT 'queued', `sent_at` DATETIME, FOREIGN KEY(`campaign_id`) REFERENCES `crm_campaigns`(`campaign_id`), FOREIGN KEY(`contact_id`) REFERENCES `crm_contacts`(`contact_id`)) ENGINE=InnoDB;
CREATE TABLE `crm_opportunities` (`opportunity_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `account_id` INT UNSIGNED NOT NULL, `contact_id` INT UNSIGNED, `opportunity_name` VARCHAR(200) NOT NULL, `stage` ENUM('prospecting','qualification','proposal','demo','negotiation','closed_won','closed_lost','on_hold') DEFAULT 'prospecting', `amount` DECIMAL(14,2), `currency_id` SMALLINT UNSIGNED, `probability` TINYINT UNSIGNED DEFAULT 0, `expected_close_date` DATE, `actual_close_date` DATE, `lead_source` ENUM('website','referral','event','cold_call','social','other'), `assigned_to` INT UNSIGNED, `campaign_id` INT UNSIGNED, `competitor` VARCHAR(100), `description` TEXT, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`contact_id`) REFERENCES `crm_contacts`(`contact_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`), FOREIGN KEY(`assigned_to`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`campaign_id`) REFERENCES `crm_campaigns`(`campaign_id`)) ENGINE=InnoDB;
CREATE TABLE `opportunity_stages_history` (`stage_history_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `opportunity_id` INT UNSIGNED NOT NULL, `old_stage` VARCHAR(30), `new_stage` VARCHAR(30), `changed_by` INT UNSIGNED, `changed_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `days_in_old_stage` SMALLINT, FOREIGN KEY(`opportunity_id`) REFERENCES `crm_opportunities`(`opportunity_id`)) ENGINE=InnoDB;
CREATE TABLE `crm_activities` (`activity_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `activity_type` ENUM('call','email','meeting','demo','follow_up','task','note','whatsapp') NOT NULL, `subject` VARCHAR(200) NOT NULL, `account_id` INT UNSIGNED, `contact_id` INT UNSIGNED, `opportunity_id` INT UNSIGNED, `lead_id` INT UNSIGNED, `assigned_to` INT UNSIGNED NOT NULL, `due_date` DATETIME, `completed_at` DATETIME, `status` ENUM('pending','in_progress','completed','cancelled') DEFAULT 'pending', `priority` ENUM('low','medium','high') DEFAULT 'medium', `description` TEXT, `duration_mins` SMALLINT UNSIGNED, `outcome` VARCHAR(200), `next_action` VARCHAR(200), `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`contact_id`) REFERENCES `crm_contacts`(`contact_id`), FOREIGN KEY(`opportunity_id`) REFERENCES `crm_opportunities`(`opportunity_id`), FOREIGN KEY(`lead_id`) REFERENCES `crm_leads`(`lead_id`), FOREIGN KEY(`assigned_to`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `call_logs` (`call_log_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `activity_id` INT UNSIGNED, `caller_id` INT UNSIGNED NOT NULL, `callee_phone` VARCHAR(30), `callee_contact_id` INT UNSIGNED, `direction` ENUM('inbound','outbound') DEFAULT 'outbound', `duration_secs` INT UNSIGNED, `call_result` ENUM('connected','voicemail','no_answer','busy','wrong_number') DEFAULT 'connected', `recording_url` VARCHAR(300), `called_at` DATETIME, FOREIGN KEY(`activity_id`) REFERENCES `crm_activities`(`activity_id`), FOREIGN KEY(`caller_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `crm_tasks` (`task_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `title` VARCHAR(200) NOT NULL, `description` TEXT, `assigned_to` INT UNSIGNED NOT NULL, `related_entity` ENUM('account','contact','opportunity','lead'), `related_id` INT UNSIGNED, `due_date` DATE, `priority` ENUM('low','medium','high','urgent') DEFAULT 'medium', `status` ENUM('pending','in_progress','completed','cancelled') DEFAULT 'pending', `completed_at` DATETIME, `reminder_at` DATETIME, FOREIGN KEY(`assigned_to`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `crm_quotes` (`quote_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `opportunity_id` INT UNSIGNED NOT NULL, `quote_number` VARCHAR(30) UNIQUE NOT NULL, `account_id` INT UNSIGNED NOT NULL, `contact_id` INT UNSIGNED, `issue_date` DATE, `expiry_date` DATE, `subtotal` DECIMAL(14,2), `discount_pct` DECIMAL(5,2) DEFAULT 0, `discount_amount` DECIMAL(12,2), `tax_amount` DECIMAL(12,2), `total_amount` DECIMAL(14,2), `currency_id` SMALLINT UNSIGNED, `status` ENUM('draft','sent','viewed','accepted','rejected','expired','revised') DEFAULT 'draft', `notes` TEXT, `terms` TEXT, `created_by` INT UNSIGNED, FOREIGN KEY(`opportunity_id`) REFERENCES `crm_opportunities`(`opportunity_id`), FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`contact_id`) REFERENCES `crm_contacts`(`contact_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`), FOREIGN KEY(`created_by`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `quote_line_items` (`qli_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `quote_id` INT UNSIGNED NOT NULL, `product_id` INT UNSIGNED, `description` VARCHAR(200), `quantity` INT UNSIGNED DEFAULT 1, `unit_price` DECIMAL(12,2) NOT NULL, `discount_pct` DECIMAL(5,2) DEFAULT 0, `line_total` DECIMAL(14,2), FOREIGN KEY(`quote_id`) REFERENCES `crm_quotes`(`quote_id`)) ENGINE=InnoDB;
CREATE TABLE `contracts` (`contract_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `account_id` INT UNSIGNED NOT NULL, `opportunity_id` INT UNSIGNED, `contract_number` VARCHAR(30) UNIQUE NOT NULL, `contract_name` VARCHAR(200), `contract_type` ENUM('msa','sow','nda','purchase','service','maintenance','partnership') NOT NULL, `start_date` DATE, `end_date` DATE, `auto_renewal` TINYINT(1) DEFAULT 0, `renewal_notice_days` TINYINT UNSIGNED DEFAULT 30, `total_value` DECIMAL(16,2), `currency_id` SMALLINT UNSIGNED, `status` ENUM('draft','pending_review','active','expired','terminated','renewed') DEFAULT 'draft', `owner_id` INT UNSIGNED, `signed_date` DATE, `file_url` VARCHAR(300), FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`opportunity_id`) REFERENCES `crm_opportunities`(`opportunity_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`), FOREIGN KEY(`owner_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `contract_clauses` (`clause_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `contract_id` INT UNSIGNED NOT NULL, `clause_type` VARCHAR(60), `clause_text` TEXT, `is_standard` TINYINT(1) DEFAULT 1, `added_by` INT UNSIGNED, FOREIGN KEY(`contract_id`) REFERENCES `contracts`(`contract_id`)) ENGINE=InnoDB;
CREATE TABLE `contract_amendments` (`amendment_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `contract_id` INT UNSIGNED NOT NULL, `amendment_date` DATE, `description` TEXT, `value_change` DECIMAL(12,2), `new_end_date` DATE, `status` ENUM('draft','approved','rejected') DEFAULT 'draft', `approved_by` INT UNSIGNED, FOREIGN KEY(`contract_id`) REFERENCES `contracts`(`contract_id`)) ENGINE=InnoDB;
CREATE TABLE customer_health_scores (
    health_id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    account_id INT UNSIGNED NOT NULL,
    health_score TINYINT UNSIGNED,
    engagement_score TINYINT UNSIGNED,
    support_score TINYINT UNSIGNED,
    product_usage_score TINYINT UNSIGNED,
    nps_score TINYINT,
    churn_risk ENUM('low','medium','high','critical') DEFAULT 'low',
    last_calculated DATETIME,
    FOREIGN KEY (account_id) REFERENCES crm_accounts(account_id)
) ENGINE=InnoDB;
CREATE TABLE `customer_segments` (`segment_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `segment_name` VARCHAR(100) NOT NULL, `criteria` JSON, `color` VARCHAR(10), `description` TEXT, `auto_assign` TINYINT(1) DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE `account_segments` (`as_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `account_id` INT UNSIGNED NOT NULL, `segment_id` SMALLINT UNSIGNED NOT NULL, `assigned_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`segment_id`) REFERENCES `customer_segments`(`segment_id`)) ENGINE=InnoDB;
CREATE TABLE `nps_surveys` (`survey_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `account_id` INT UNSIGNED NOT NULL, `contact_id` INT UNSIGNED, `sent_at` DATETIME, `responded_at` DATETIME, `score` TINYINT, `category` ENUM('promoter','passive','detractor'), `feedback` TEXT, `campaign_id` INT UNSIGNED, FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`contact_id`) REFERENCES `crm_contacts`(`contact_id`)) ENGINE=InnoDB;
CREATE TABLE `subscription_plans` (`plan_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `plan_name` VARCHAR(80) NOT NULL, `plan_type` ENUM('free','starter','professional','enterprise','custom') NOT NULL, `billing_cycle` ENUM('monthly','quarterly','annual') DEFAULT 'monthly', `price` DECIMAL(10,2), `currency_id` SMALLINT UNSIGNED, `max_users` SMALLINT UNSIGNED, `features` JSON, `is_active` TINYINT(1) DEFAULT 1, FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `account_subscriptions` (`subscription_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `account_id` INT UNSIGNED NOT NULL, `plan_id` SMALLINT UNSIGNED NOT NULL, `start_date` DATE NOT NULL, `end_date` DATE, `renewal_date` DATE, `mrr` DECIMAL(10,2), `arr` DECIMAL(12,2), `status` ENUM('trial','active','suspended','cancelled','expired') DEFAULT 'trial', `cancelled_at` DATE, `cancel_reason` VARCHAR(200), FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`plan_id`) REFERENCES `subscription_plans`(`plan_id`)) ENGINE=InnoDB;
CREATE TABLE `upsell_opportunities` (`upsell_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `account_id` INT UNSIGNED NOT NULL, `subscription_id` INT UNSIGNED, `upsell_type` ENUM('upsell','cross_sell','expansion','renewal') NOT NULL, `current_arr` DECIMAL(12,2), `potential_arr` DECIMAL(12,2), `probability` TINYINT UNSIGNED, `owner_id` INT UNSIGNED, `status` ENUM('identified','pursuing','won','lost') DEFAULT 'identified', FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`owner_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `competitor_analysis` (`comp_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `competitor_name` VARCHAR(150) NOT NULL, `website` VARCHAR(200), `industry_id` SMALLINT UNSIGNED, `strengths` TEXT, `weaknesses` TEXT, `pricing_info` TEXT, `market_share_pct` DECIMAL(5,2), `last_updated` DATE, FOREIGN KEY(`industry_id`) REFERENCES `industries`(`industry_id`)) ENGINE=InnoDB;
CREATE TABLE `opportunity_competitors` (`oc_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `opportunity_id` INT UNSIGNED NOT NULL, `comp_id` INT UNSIGNED NOT NULL, `threat_level` ENUM('low','medium','high') DEFAULT 'medium', `win_over_strategy` TEXT, FOREIGN KEY(`opportunity_id`) REFERENCES `crm_opportunities`(`opportunity_id`), FOREIGN KEY(`comp_id`) REFERENCES `competitor_analysis`(`comp_id`)) ENGINE=InnoDB;
CREATE TABLE `crm_pipelines` (`pipeline_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `pipeline_name` VARCHAR(100) NOT NULL, `company_id` SMALLINT UNSIGNED, `is_default` TINYINT(1) DEFAULT 0, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `pipeline_stages` (`stage_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `pipeline_id` SMALLINT UNSIGNED NOT NULL, `stage_name` VARCHAR(60) NOT NULL, `order_no` TINYINT UNSIGNED, `win_probability` TINYINT UNSIGNED DEFAULT 0, `is_closed_won` TINYINT(1) DEFAULT 0, `is_closed_lost` TINYINT(1) DEFAULT 0, FOREIGN KEY(`pipeline_id`) REFERENCES `crm_pipelines`(`pipeline_id`)) ENGINE=InnoDB;
CREATE TABLE `price_books` (`book_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `book_name` VARCHAR(100) NOT NULL, `currency_id` SMALLINT UNSIGNED, `is_default` TINYINT(1) DEFAULT 0, `effective_from` DATE, `effective_to` DATE, FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `price_book_entries` (`entry_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `book_id` SMALLINT UNSIGNED NOT NULL, `product_id` INT UNSIGNED NOT NULL, `list_price` DECIMAL(12,2), `discount_max_pct` DECIMAL(5,2) DEFAULT 0, FOREIGN KEY(`book_id`) REFERENCES `price_books`(`book_id`)) ENGINE=InnoDB;
CREATE TABLE `customer_journeys` (`journey_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `account_id` INT UNSIGNED NOT NULL, `stage` ENUM('awareness','consideration','purchase','onboarding','adoption','retention','expansion','advocacy') NOT NULL, `entered_at` DATETIME, `exited_at` DATETIME, `days_in_stage` SMALLINT UNSIGNED, FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`)) ENGINE=InnoDB;
CREATE TABLE `email_sequences` (`sequence_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `sequence_name` VARCHAR(150) NOT NULL, `trigger_event` VARCHAR(80), `delay_days` TINYINT UNSIGNED DEFAULT 0, `email_count` TINYINT UNSIGNED, `is_active` TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE `sequence_enrollments` (`enrollment_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `sequence_id` SMALLINT UNSIGNED NOT NULL, `contact_id` INT UNSIGNED NOT NULL, `enrolled_at` DATETIME, `current_step` TINYINT UNSIGNED DEFAULT 1, `status` ENUM('active','completed','paused','unsubscribed') DEFAULT 'active', FOREIGN KEY(`sequence_id`) REFERENCES `email_sequences`(`sequence_id`), FOREIGN KEY(`contact_id`) REFERENCES `crm_contacts`(`contact_id`)) ENGINE=InnoDB;
CREATE TABLE `partner_accounts` (`partner_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `account_id` INT UNSIGNED NOT NULL, `partner_type` ENUM('reseller','implementation','referral','technology','distributor') NOT NULL, `tier` ENUM('platinum','gold','silver','bronze') DEFAULT 'bronze', `commission_pct` DECIMAL(5,2), `start_date` DATE, `end_date` DATE, FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`)) ENGINE=InnoDB;
CREATE TABLE `partner_deals` (`pd_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `partner_id` INT UNSIGNED NOT NULL, `opportunity_id` INT UNSIGNED NOT NULL, `deal_type` ENUM('co_sell','referral','resell') DEFAULT 'co_sell', `partner_revenue` DECIMAL(12,2), `commission_amount` DECIMAL(10,2), `status` ENUM('registered','approved','won','lost') DEFAULT 'registered', FOREIGN KEY(`partner_id`) REFERENCES `partner_accounts`(`partner_id`), FOREIGN KEY(`opportunity_id`) REFERENCES `crm_opportunities`(`opportunity_id`)) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 8: SALES & PRODUCTS (30 tables)
-- ============================================================
CREATE TABLE `product_categories` (`category_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `category_name` VARCHAR(100) NOT NULL, `parent_cat_id` SMALLINT UNSIGNED, `description` TEXT, `display_order` TINYINT UNSIGNED DEFAULT 0, FOREIGN KEY(`parent_cat_id`) REFERENCES `product_categories`(`category_id`)) ENGINE=InnoDB;
CREATE TABLE `brands` (`brand_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `brand_name` VARCHAR(100) NOT NULL, `country_of_origin` SMALLINT UNSIGNED, `logo_url` VARCHAR(300), FOREIGN KEY(`country_of_origin`) REFERENCES `countries`(`country_id`)) ENGINE=InnoDB;
CREATE TABLE `units_of_measure` (`uom_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `uom_name` VARCHAR(40) NOT NULL, `uom_code` VARCHAR(10) NOT NULL UNIQUE, `uom_type` ENUM('quantity','weight','volume','length','time','area') DEFAULT 'quantity') ENGINE=InnoDB;
CREATE TABLE `products` (`product_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `category_id` SMALLINT UNSIGNED, `brand_id` SMALLINT UNSIGNED, `product_name` VARCHAR(200) NOT NULL, `product_code` VARCHAR(60) UNIQUE, `sku` VARCHAR(60) UNIQUE, `barcode` VARCHAR(60), `description` TEXT, `unit_price` DECIMAL(12,2) NOT NULL, `cost_price` DECIMAL(12,2), `currency_id` SMALLINT UNSIGNED, `uom_id` SMALLINT UNSIGNED, `weight_kg` DECIMAL(8,3), `dimensions` VARCHAR(60), `stock_qty` INT DEFAULT 0, `reorder_level` INT DEFAULT 0, `lead_time_days` TINYINT UNSIGNED, `is_active` TINYINT(1) DEFAULT 1, `is_serialized` TINYINT(1) DEFAULT 0, `tax_type_id` SMALLINT UNSIGNED, `product_type` ENUM('physical','digital','service','subscription') DEFAULT 'physical', `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`category_id`) REFERENCES `product_categories`(`category_id`), FOREIGN KEY(`brand_id`) REFERENCES `brands`(`brand_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`), FOREIGN KEY(`uom_id`) REFERENCES `units_of_measure`(`uom_id`), FOREIGN KEY(`tax_type_id`) REFERENCES `tax_types`(`tax_type_id`)) ENGINE=InnoDB;
CREATE TABLE `product_variants` (`variant_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `product_id` INT UNSIGNED NOT NULL, `variant_name` VARCHAR(80), `attribute1` VARCHAR(60), `value1` VARCHAR(60), `attribute2` VARCHAR(60), `value2` VARCHAR(60), `sku_variant` VARCHAR(80) UNIQUE, `price_adjustment` DECIMAL(10,2) DEFAULT 0, `stock_qty` INT DEFAULT 0, FOREIGN KEY(`product_id`) REFERENCES `products`(`product_id`)) ENGINE=InnoDB;
CREATE TABLE `product_images` (`image_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `product_id` INT UNSIGNED NOT NULL, `image_url` VARCHAR(300) NOT NULL, `alt_text` VARCHAR(150), `is_primary` TINYINT(1) DEFAULT 0, `display_order` TINYINT UNSIGNED, FOREIGN KEY(`product_id`) REFERENCES `products`(`product_id`)) ENGINE=InnoDB;
CREATE TABLE `sales_orders` (`order_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `order_number` VARCHAR(30) UNIQUE NOT NULL, `account_id` INT UNSIGNED NOT NULL, `contact_id` INT UNSIGNED, `opportunity_id` INT UNSIGNED, `quote_id` INT UNSIGNED, `order_date` DATE NOT NULL, `required_date` DATE, `shipped_date` DATE, `delivery_date` DATE, `status` ENUM('draft','pending_approval','confirmed','processing','ready_to_ship','shipped','delivered','cancelled','refunded','return_requested') DEFAULT 'draft', `payment_status` ENUM('unpaid','partial','paid','refunded','overdue') DEFAULT 'unpaid', `subtotal` DECIMAL(14,2), `discount_pct` DECIMAL(5,2) DEFAULT 0, `discount_amount` DECIMAL(12,2), `tax_amount` DECIMAL(12,2), `shipping_cost` DECIMAL(10,2) DEFAULT 0, `total_amount` DECIMAL(14,2), `currency_id` SMALLINT UNSIGNED, `assigned_to` INT UNSIGNED, `billing_address` VARCHAR(300), `shipping_address` VARCHAR(300), `notes` TEXT, `po_number` VARCHAR(60), `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`contact_id`) REFERENCES `crm_contacts`(`contact_id`), FOREIGN KEY(`opportunity_id`) REFERENCES `crm_opportunities`(`opportunity_id`), FOREIGN KEY(`quote_id`) REFERENCES `crm_quotes`(`quote_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`), FOREIGN KEY(`assigned_to`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `order_items` (`item_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `order_id` INT UNSIGNED NOT NULL, `product_id` INT UNSIGNED NOT NULL, `variant_id` INT UNSIGNED, `quantity` INT UNSIGNED NOT NULL DEFAULT 1, `unit_price` DECIMAL(12,2) NOT NULL, `discount_pct` DECIMAL(5,2) DEFAULT 0, `tax_pct` DECIMAL(5,2) DEFAULT 0, `line_total` DECIMAL(14,2), `delivered_qty` INT UNSIGNED DEFAULT 0, FOREIGN KEY(`order_id`) REFERENCES `sales_orders`(`order_id`), FOREIGN KEY(`product_id`) REFERENCES `products`(`product_id`), FOREIGN KEY(`variant_id`) REFERENCES `product_variants`(`variant_id`)) ENGINE=InnoDB;
CREATE TABLE `invoices` (`invoice_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `invoice_number` VARCHAR(30) UNIQUE NOT NULL, `order_id` INT UNSIGNED NOT NULL, `account_id` INT UNSIGNED NOT NULL, `issue_date` DATE NOT NULL, `due_date` DATE, `subtotal` DECIMAL(14,2), `tax_amount` DECIMAL(12,2), `discount_amount` DECIMAL(12,2), `total_amount` DECIMAL(14,2), `amount_paid` DECIMAL(14,2) DEFAULT 0, `balance_due` DECIMAL(14,2), `currency_id` SMALLINT UNSIGNED, `status` ENUM('draft','sent','partial','paid','overdue','cancelled','written_off') DEFAULT 'draft', `notes` TEXT, `terms` TEXT, `created_by` INT UNSIGNED, FOREIGN KEY(`order_id`) REFERENCES `sales_orders`(`order_id`), FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`), FOREIGN KEY(`created_by`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `payments` (`payment_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `invoice_id` INT UNSIGNED NOT NULL, `account_id` INT UNSIGNED NOT NULL, `payment_date` DATE NOT NULL, `amount` DECIMAL(14,2) NOT NULL, `currency_id` SMALLINT UNSIGNED, `payment_method` ENUM('bank_transfer','credit_card','debit_card','cheque','cash','upi','paypal','stripe','razorpay') NOT NULL, `transaction_id` VARCHAR(100), `reference_no` VARCHAR(100), `bank_charges` DECIMAL(8,2) DEFAULT 0, `status` ENUM('pending','completed','failed','refunded','chargeback') DEFAULT 'pending', `notes` TEXT, FOREIGN KEY(`invoice_id`) REFERENCES `invoices`(`invoice_id`), FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `credit_notes` (`cn_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `cn_number` VARCHAR(30) UNIQUE NOT NULL, `invoice_id` INT UNSIGNED NOT NULL, `account_id` INT UNSIGNED NOT NULL, `issue_date` DATE, `amount` DECIMAL(12,2) NOT NULL, `reason` VARCHAR(200), `status` ENUM('draft','issued','applied','cancelled') DEFAULT 'draft', `applied_to_invoice_id` INT UNSIGNED, FOREIGN KEY(`invoice_id`) REFERENCES `invoices`(`invoice_id`), FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`)) ENGINE=InnoDB;
CREATE TABLE `debit_notes` (`dn_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `dn_number` VARCHAR(30) UNIQUE NOT NULL, `account_id` INT UNSIGNED NOT NULL, `issue_date` DATE, `amount` DECIMAL(12,2), `reason` VARCHAR(200), `status` ENUM('draft','issued','settled') DEFAULT 'draft', FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`)) ENGINE=InnoDB;
CREATE TABLE `return_orders` (`return_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `order_id` INT UNSIGNED NOT NULL, `account_id` INT UNSIGNED NOT NULL, `return_date` DATE, `reason` ENUM('defective','wrong_item','not_needed','damaged_in_transit','other') NOT NULL, `status` ENUM('requested','approved','received','refunded','rejected') DEFAULT 'requested', `refund_amount` DECIMAL(12,2), `restocking_fee` DECIMAL(10,2) DEFAULT 0, `approved_by` INT UNSIGNED, FOREIGN KEY(`order_id`) REFERENCES `sales_orders`(`order_id`), FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`)) ENGINE=InnoDB;
CREATE TABLE `return_items` (`ri_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `return_id` INT UNSIGNED NOT NULL, `order_item_id` INT UNSIGNED NOT NULL, `quantity` INT UNSIGNED NOT NULL, `reason` VARCHAR(200), `condition` ENUM('unopened','opened','damaged','defective') DEFAULT 'opened', FOREIGN KEY(`return_id`) REFERENCES `return_orders`(`return_id`), FOREIGN KEY(`order_item_id`) REFERENCES `order_items`(`item_id`)) ENGINE=InnoDB;
CREATE TABLE `delivery_notes` (`dn_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `order_id` INT UNSIGNED NOT NULL, `dn_number` VARCHAR(30) UNIQUE NOT NULL, `delivery_date` DATE, `delivered_to` VARCHAR(120), `carrier` VARCHAR(80), `tracking_number` VARCHAR(100), `delivery_status` ENUM('pending','in_transit','delivered','failed','returned') DEFAULT 'pending', `signed_by` VARCHAR(80), `notes` TEXT, FOREIGN KEY(`order_id`) REFERENCES `sales_orders`(`order_id`)) ENGINE=InnoDB;
CREATE TABLE `shipments` (`shipment_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `order_id` INT UNSIGNED NOT NULL, `carrier` VARCHAR(80), `tracking_no` VARCHAR(100), `ship_date` DATE, `expected_delivery` DATE, `actual_delivery` DATE, `status` ENUM('packed','shipped','in_transit','delivered','failed') DEFAULT 'packed', `weight_kg` DECIMAL(8,3), `shipping_cost` DECIMAL(10,2), FOREIGN KEY(`order_id`) REFERENCES `sales_orders`(`order_id`)) ENGINE=InnoDB;
CREATE TABLE `sales_targets` (`target_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `department_id` SMALLINT UNSIGNED, `period` VARCHAR(20) NOT NULL, `target_amount` DECIMAL(14,2) NOT NULL, `achieved_amount` DECIMAL(14,2) DEFAULT 0, `currency_id` SMALLINT UNSIGNED, `target_deals` INT UNSIGNED, `achieved_deals` INT UNSIGNED DEFAULT 0, `notes` TEXT, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`department_id`) REFERENCES `departments`(`department_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `commissions` (`commission_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `order_id` INT UNSIGNED, `period` VARCHAR(20), `revenue` DECIMAL(14,2), `commission_rate` DECIMAL(5,4), `commission_amount` DECIMAL(12,2), `accelerator` DECIMAL(5,4) DEFAULT 1.0, `final_commission` DECIMAL(12,2), `status` ENUM('calculated','approved','paid') DEFAULT 'calculated', `paid_date` DATE, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`order_id`) REFERENCES `sales_orders`(`order_id`)) ENGINE=InnoDB;
CREATE TABLE `purchase_orders` (`po_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `po_number` VARCHAR(30) UNIQUE NOT NULL, `vendor_account_id` INT UNSIGNED, `po_date` DATE NOT NULL, `delivery_date` DATE, `subtotal` DECIMAL(14,2), `tax_amount` DECIMAL(12,2), `total_amount` DECIMAL(14,2), `currency_id` SMALLINT UNSIGNED, `status` ENUM('draft','sent','acknowledged','partially_received','received','cancelled') DEFAULT 'draft', `created_by` INT UNSIGNED, `approved_by` INT UNSIGNED, FOREIGN KEY(`vendor_account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`), FOREIGN KEY(`created_by`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `po_items` (`po_item_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `po_id` INT UNSIGNED NOT NULL, `product_id` INT UNSIGNED NOT NULL, `quantity` INT UNSIGNED NOT NULL, `unit_price` DECIMAL(12,2), `received_qty` INT UNSIGNED DEFAULT 0, `line_total` DECIMAL(14,2), FOREIGN KEY(`po_id`) REFERENCES `purchase_orders`(`po_id`), FOREIGN KEY(`product_id`) REFERENCES `products`(`product_id`)) ENGINE=InnoDB;
CREATE TABLE `discount_rules` (`rule_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `rule_name` VARCHAR(100) NOT NULL, `discount_type` ENUM('percentage','flat','buy_x_get_y','tiered') NOT NULL, `discount_value` DECIMAL(8,4), `min_order_value` DECIMAL(12,2), `max_discount_cap` DECIMAL(12,2), `applicable_to` ENUM('all','specific_product','specific_category','specific_customer') DEFAULT 'all', `start_date` DATE, `end_date` DATE, `is_active` TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE `coupon_codes` (`coupon_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `code` VARCHAR(30) UNIQUE NOT NULL, `rule_id` SMALLINT UNSIGNED, `max_uses` INT UNSIGNED, `used_count` INT UNSIGNED DEFAULT 0, `per_customer_limit` TINYINT UNSIGNED DEFAULT 1, `start_date` DATE, `end_date` DATE, `is_active` TINYINT(1) DEFAULT 1, FOREIGN KEY(`rule_id`) REFERENCES `discount_rules`(`rule_id`)) ENGINE=InnoDB;
CREATE TABLE `tax_invoices` (`tax_invoice_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `invoice_id` INT UNSIGNED NOT NULL, `gstin` VARCHAR(20), `place_of_supply` VARCHAR(60), `cgst_amount` DECIMAL(12,2), `sgst_amount` DECIMAL(12,2), `igst_amount` DECIMAL(12,2), `cess_amount` DECIMAL(12,2), `total_tax` DECIMAL(12,2), FOREIGN KEY(`invoice_id`) REFERENCES `invoices`(`invoice_id`)) ENGINE=InnoDB;
CREATE TABLE `e_invoices` (`einv_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `invoice_id` INT UNSIGNED NOT NULL, `irn` VARCHAR(100), `ack_no` VARCHAR(60), `ack_date` DATETIME, `qr_code_url` VARCHAR(300), `status` ENUM('generated','cancelled') DEFAULT 'generated', FOREIGN KEY(`invoice_id`) REFERENCES `invoices`(`invoice_id`)) ENGINE=InnoDB;
CREATE TABLE `sales_forecasts` (`forecast_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED, `department_id` SMALLINT UNSIGNED, `period` VARCHAR(20) NOT NULL, `forecast_type` ENUM('commit','best_case','pipeline') DEFAULT 'commit', `forecast_amount` DECIMAL(14,2), `weighted_amount` DECIMAL(14,2), `currency_id` SMALLINT UNSIGNED, `submitted_at` DATETIME, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`department_id`) REFERENCES `departments`(`department_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `deal_registrations` (`dr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `opportunity_id` INT UNSIGNED NOT NULL, `partner_id` INT UNSIGNED, `registered_by` INT UNSIGNED, `registration_date` DATE, `expiry_date` DATE, `status` ENUM('pending','approved','rejected','expired') DEFAULT 'pending', `discount_pct` DECIMAL(5,2), FOREIGN KEY(`opportunity_id`) REFERENCES `crm_opportunities`(`opportunity_id`)) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 9: FINANCE & ACCOUNTING (40 tables)
-- ============================================================
CREATE TABLE `chart_of_accounts` (`account_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `account_code` VARCHAR(20) NOT NULL, `account_name` VARCHAR(150) NOT NULL, `account_type` ENUM('asset','liability','equity','revenue','expense','contra') NOT NULL, `account_subtype` VARCHAR(60), `parent_account_id` INT UNSIGNED, `currency_id` SMALLINT UNSIGNED, `is_active` TINYINT(1) DEFAULT 1, `description` TEXT, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`), FOREIGN KEY(`parent_account_id`) REFERENCES `chart_of_accounts`(`account_id`)) ENGINE=InnoDB;
CREATE TABLE `fiscal_years` (`fy_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `fy_name` VARCHAR(20) NOT NULL, `start_date` DATE NOT NULL, `end_date` DATE NOT NULL, `status` ENUM('planned','active','closed') DEFAULT 'planned', `closed_at` DATETIME, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `accounting_periods` (`period_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `fy_id` SMALLINT UNSIGNED NOT NULL, `period_name` VARCHAR(20) NOT NULL, `start_date` DATE NOT NULL, `end_date` DATE NOT NULL, `status` ENUM('open','closed') DEFAULT 'open', FOREIGN KEY(`fy_id`) REFERENCES `fiscal_years`(`fy_id`)) ENGINE=InnoDB;
CREATE TABLE `journals` (`journal_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `journal_name` VARCHAR(80) NOT NULL, `journal_type` ENUM('general','sales','purchase','cash','bank','payroll','asset') DEFAULT 'general', `is_active` TINYINT(1) DEFAULT 1, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `journal_entries` (`je_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `journal_id` SMALLINT UNSIGNED NOT NULL, `period_id` SMALLINT UNSIGNED NOT NULL, `entry_date` DATE NOT NULL, `reference_no` VARCHAR(60), `narration` TEXT, `total_debit` DECIMAL(16,2), `total_credit` DECIMAL(16,2), `status` ENUM('draft','posted','reversed') DEFAULT 'draft', `created_by` INT UNSIGNED, `posted_by` INT UNSIGNED, `posted_at` DATETIME, FOREIGN KEY(`journal_id`) REFERENCES `journals`(`journal_id`), FOREIGN KEY(`period_id`) REFERENCES `accounting_periods`(`period_id`), FOREIGN KEY(`created_by`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `journal_entry_lines` (`line_id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `je_id` INT UNSIGNED NOT NULL, `account_id` INT UNSIGNED NOT NULL, `debit` DECIMAL(16,2) DEFAULT 0, `credit` DECIMAL(16,2) DEFAULT 0, `narration` VARCHAR(200), `cost_center_id` SMALLINT UNSIGNED, `project_id` INT UNSIGNED, FOREIGN KEY(`je_id`) REFERENCES `journal_entries`(`je_id`), FOREIGN KEY(`account_id`) REFERENCES `chart_of_accounts`(`account_id`)) ENGINE=InnoDB;
CREATE TABLE `budgets` (`budget_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `fy_id` SMALLINT UNSIGNED NOT NULL, `budget_name` VARCHAR(100) NOT NULL, `budget_type` ENUM('operational','capital','project') DEFAULT 'operational', `total_amount` DECIMAL(16,2), `currency_id` SMALLINT UNSIGNED, `status` ENUM('draft','approved','active','closed') DEFAULT 'draft', `approved_by` INT UNSIGNED, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`fy_id`) REFERENCES `fiscal_years`(`fy_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `budget_lines` (`bl_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `budget_id` INT UNSIGNED NOT NULL, `account_id` INT UNSIGNED NOT NULL, `cost_center_id` SMALLINT UNSIGNED, `department_id` SMALLINT UNSIGNED, `period_id` SMALLINT UNSIGNED, `planned_amount` DECIMAL(14,2), `actual_amount` DECIMAL(14,2) DEFAULT 0, `variance` DECIMAL(14,2), FOREIGN KEY(`budget_id`) REFERENCES `budgets`(`budget_id`), FOREIGN KEY(`account_id`) REFERENCES `chart_of_accounts`(`account_id`)) ENGINE=InnoDB;
CREATE TABLE `bank_accounts_company` (`bank_acc_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `bank_id` SMALLINT UNSIGNED, `account_number` VARCHAR(30) NOT NULL, `account_name` VARCHAR(100), `account_type` ENUM('current','savings','overdraft','fixed_deposit') DEFAULT 'current', `currency_id` SMALLINT UNSIGNED, `current_balance` DECIMAL(16,2), `gl_account_id` INT UNSIGNED, `is_active` TINYINT(1) DEFAULT 1, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`bank_id`) REFERENCES `bank_names`(`bank_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `bank_transactions` (`txn_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `bank_acc_id` INT UNSIGNED NOT NULL, `txn_date` DATE NOT NULL, `txn_type` ENUM('debit','credit') NOT NULL, `amount` DECIMAL(16,2) NOT NULL, `balance_after` DECIMAL(16,2), `description` VARCHAR(200), `reference_no` VARCHAR(100), `is_reconciled` TINYINT(1) DEFAULT 0, `je_id` INT UNSIGNED, FOREIGN KEY(`bank_acc_id`) REFERENCES `bank_accounts_company`(`bank_acc_id`)) ENGINE=InnoDB;
CREATE TABLE `bank_reconciliations` (`reconcile_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `bank_acc_id` INT UNSIGNED NOT NULL, `period_id` SMALLINT UNSIGNED NOT NULL, `statement_date` DATE, `book_balance` DECIMAL(16,2), `bank_balance` DECIMAL(16,2), `adjusted_balance` DECIMAL(16,2), `status` ENUM('in_progress','completed') DEFAULT 'in_progress', `completed_by` INT UNSIGNED, `completed_at` DATETIME, FOREIGN KEY(`bank_acc_id`) REFERENCES `bank_accounts_company`(`bank_acc_id`)) ENGINE=InnoDB;
CREATE TABLE `accounts_payable` (`ap_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `vendor_account_id` INT UNSIGNED NOT NULL, `invoice_number` VARCHAR(60), `invoice_date` DATE, `due_date` DATE, `amount` DECIMAL(14,2) NOT NULL, `paid_amount` DECIMAL(14,2) DEFAULT 0, `balance` DECIMAL(14,2), `currency_id` SMALLINT UNSIGNED, `status` ENUM('open','partial','paid','overdue','disputed') DEFAULT 'open', `po_id` INT UNSIGNED, FOREIGN KEY(`vendor_account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `accounts_receivable` (`ar_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `customer_account_id` INT UNSIGNED NOT NULL, `invoice_id` INT UNSIGNED NOT NULL, `invoice_date` DATE, `due_date` DATE, `amount` DECIMAL(14,2) NOT NULL, `collected_amount` DECIMAL(14,2) DEFAULT 0, `balance` DECIMAL(14,2), `currency_id` SMALLINT UNSIGNED, `status` ENUM('open','partial','collected','overdue','written_off') DEFAULT 'open', FOREIGN KEY(`customer_account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`invoice_id`) REFERENCES `invoices`(`invoice_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `collection_activities` (`col_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `ar_id` INT UNSIGNED NOT NULL, `activity_type` ENUM('call','email','letter','legal_notice','payment_arrangement') NOT NULL, `activity_date` DATE, `amount_promised` DECIMAL(12,2), `promise_date` DATE, `outcome` VARCHAR(200), `done_by` INT UNSIGNED, FOREIGN KEY(`ar_id`) REFERENCES `accounts_receivable`(`ar_id`), FOREIGN KEY(`done_by`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `asset_register` (`asset_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `asset_code` VARCHAR(30) UNIQUE, `asset_name` VARCHAR(150) NOT NULL, `asset_category` ENUM('it_equipment','furniture','vehicle','machinery','building','land','intangible','other') NOT NULL, `purchase_date` DATE, `purchase_cost` DECIMAL(14,2), `currency_id` SMALLINT UNSIGNED, `useful_life_months` SMALLINT UNSIGNED, `depreciation_method` ENUM('straight_line','declining_balance','sum_of_years','units_of_production') DEFAULT 'straight_line', `salvage_value` DECIMAL(12,2) DEFAULT 0, `current_book_value` DECIMAL(14,2), `location_id` SMALLINT UNSIGNED, `assigned_to` INT UNSIGNED, `serial_no` VARCHAR(60), `status` ENUM('active','disposed','scrapped','stolen','under_repair') DEFAULT 'active', FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`), FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `asset_depreciations` (`dep_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `asset_id` INT UNSIGNED NOT NULL, `period_id` SMALLINT UNSIGNED NOT NULL, `depreciation_amount` DECIMAL(12,2), `accumulated_depreciation` DECIMAL(14,2), `net_book_value` DECIMAL(14,2), `je_id` INT UNSIGNED, FOREIGN KEY(`asset_id`) REFERENCES `asset_register`(`asset_id`), FOREIGN KEY(`period_id`) REFERENCES `accounting_periods`(`period_id`)) ENGINE=InnoDB;
CREATE TABLE `asset_disposals` (`disposal_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `asset_id` INT UNSIGNED NOT NULL, `disposal_date` DATE, `disposal_type` ENUM('sold','scrapped','donated','stolen','written_off') NOT NULL, `sale_price` DECIMAL(12,2), `gain_loss` DECIMAL(12,2), `approved_by` INT UNSIGNED, `notes` TEXT, FOREIGN KEY(`asset_id`) REFERENCES `asset_register`(`asset_id`)) ENGINE=InnoDB;
CREATE TABLE `financial_statements` (`fs_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `period_id` SMALLINT UNSIGNED NOT NULL, `statement_type` ENUM('balance_sheet','income_statement','cash_flow','trial_balance') NOT NULL, `generated_at` DATETIME, `generated_by` INT UNSIGNED, `file_url` VARCHAR(300), FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`period_id`) REFERENCES `accounting_periods`(`period_id`)) ENGINE=InnoDB;
CREATE TABLE `tax_filings` (`filing_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `tax_type_id` SMALLINT UNSIGNED, `period` VARCHAR(20), `due_date` DATE, `filed_date` DATE, `taxable_amount` DECIMAL(16,2), `tax_amount` DECIMAL(14,2), `penalty` DECIMAL(10,2) DEFAULT 0, `status` ENUM('pending','filed','paid','overdue') DEFAULT 'pending', `reference_no` VARCHAR(60), FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`tax_type_id`) REFERENCES `tax_types`(`tax_type_id`)) ENGINE=InnoDB;
CREATE TABLE `gst_returns` (`gst_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `return_type` ENUM('GSTR1','GSTR3B','GSTR9','GSTR2A') NOT NULL, `period` VARCHAR(20), `total_taxable` DECIMAL(16,2), `total_igst` DECIMAL(14,2), `total_cgst` DECIMAL(14,2), `total_sgst` DECIMAL(14,2), `filed_at` DATETIME, `status` ENUM('draft','filed','accepted') DEFAULT 'draft', FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `payment_terms` (`term_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `term_name` VARCHAR(60) NOT NULL, `days` TINYINT UNSIGNED NOT NULL, `discount_pct` DECIMAL(5,2) DEFAULT 0, `discount_days` TINYINT UNSIGNED DEFAULT 0, `description` VARCHAR(200)) ENGINE=InnoDB;
CREATE TABLE `recurring_invoices` (`ri_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `account_id` INT UNSIGNED NOT NULL, `subscription_id` INT UNSIGNED, `frequency` ENUM('weekly','monthly','quarterly','annual') DEFAULT 'monthly', `next_date` DATE, `amount` DECIMAL(14,2), `currency_id` SMALLINT UNSIGNED, `is_active` TINYINT(1) DEFAULT 1, `last_generated_at` DATETIME, FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `inter_company_transactions` (`ict_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `from_company_id` SMALLINT UNSIGNED NOT NULL, `to_company_id` SMALLINT UNSIGNED NOT NULL, `txn_date` DATE, `amount` DECIMAL(16,2), `currency_id` SMALLINT UNSIGNED, `txn_type` ENUM('loan','service','product','dividend','management_fee') NOT NULL, `description` TEXT, `status` ENUM('pending','settled') DEFAULT 'pending', FOREIGN KEY(`from_company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`to_company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `currency_exchange_rates` (`rate_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `from_currency_id` SMALLINT UNSIGNED NOT NULL, `to_currency_id` SMALLINT UNSIGNED NOT NULL, `rate` DECIMAL(12,6) NOT NULL, `rate_date` DATE NOT NULL, `source` VARCHAR(60), FOREIGN KEY(`from_currency_id`) REFERENCES `currencies`(`currency_id`), FOREIGN KEY(`to_currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `financial_reports` (`report_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `report_name` VARCHAR(150), `report_type` VARCHAR(60), `period` VARCHAR(20), `generated_at` DATETIME, `generated_by` INT UNSIGNED, `file_url` VARCHAR(300), `parameters` JSON, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `vendor_payments` (`vp_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `ap_id` INT UNSIGNED NOT NULL, `payment_date` DATE NOT NULL, `amount` DECIMAL(14,2) NOT NULL, `payment_method` ENUM('bank_transfer','cheque','cash','upi') NOT NULL, `reference_no` VARCHAR(100), `bank_acc_id` INT UNSIGNED, `status` ENUM('pending','processed','failed') DEFAULT 'pending', FOREIGN KEY(`ap_id`) REFERENCES `accounts_payable`(`ap_id`)) ENGINE=InnoDB;
CREATE TABLE `dunning_notices` (`dn_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `ar_id` INT UNSIGNED NOT NULL, `notice_level` TINYINT UNSIGNED, `sent_at` DATETIME, `amount_due` DECIMAL(14,2), `due_date` DATE, `response_received` TINYINT(1) DEFAULT 0, `response_date` DATE, FOREIGN KEY(`ar_id`) REFERENCES `accounts_receivable`(`ar_id`)) ENGINE=InnoDB;
CREATE TABLE `cashflow_forecasts` (`cf_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `period_id` SMALLINT UNSIGNED NOT NULL, `inflow_forecast` DECIMAL(16,2), `outflow_forecast` DECIMAL(16,2), `net_forecast` DECIMAL(16,2), `inflow_actual` DECIMAL(16,2), `outflow_actual` DECIMAL(16,2), FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `credit_limits` (`cl_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `account_id` INT UNSIGNED NOT NULL UNIQUE, `credit_limit` DECIMAL(14,2), `current_exposure` DECIMAL(14,2) DEFAULT 0, `currency_id` SMALLINT UNSIGNED, `approved_by` INT UNSIGNED, `review_date` DATE, FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`currency_id`) REFERENCES `currencies`(`currency_id`)) ENGINE=InnoDB;
CREATE TABLE `internal_audits` (`audit_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `audit_type` VARCHAR(80), `audit_period` VARCHAR(20), `start_date` DATE, `end_date` DATE, `auditor_id` INT UNSIGNED, `status` ENUM('planned','in_progress','completed','reported') DEFAULT 'planned', `findings` TEXT, `report_url` VARCHAR(300), FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `audit_findings` (`finding_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `audit_id` INT UNSIGNED NOT NULL, `area` VARCHAR(80), `risk_level` ENUM('low','medium','high','critical') DEFAULT 'medium', `finding` TEXT, `recommendation` TEXT, `status` ENUM('open','in_progress','resolved','accepted_risk') DEFAULT 'open', `due_date` DATE, `responsible_id` INT UNSIGNED, FOREIGN KEY(`audit_id`) REFERENCES `internal_audits`(`audit_id`)) ENGINE=InnoDB;
CREATE TABLE `provisions` (`provision_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `provision_type` VARCHAR(80), `period_id` SMALLINT UNSIGNED, `amount` DECIMAL(14,2), `gl_account_id` INT UNSIGNED, `description` TEXT, `created_at` DATE, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `prepayments` (`pp_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `vendor_account_id` INT UNSIGNED, `payment_date` DATE, `amount` DECIMAL(14,2), `currency_id` SMALLINT UNSIGNED, `description` TEXT, `reconciled` TINYINT(1) DEFAULT 0, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `withholding_tax` (`wt_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `invoice_id` INT UNSIGNED, `taxable_amount` DECIMAL(14,2), `wt_rate` DECIMAL(6,4), `wt_amount` DECIMAL(12,2), `deducted_by_company_id` SMALLINT UNSIGNED, `period` VARCHAR(20), `filed` TINYINT(1) DEFAULT 0, FOREIGN KEY(`invoice_id`) REFERENCES `invoices`(`invoice_id`)) ENGINE=InnoDB;
CREATE TABLE `capex_requests` (`capex_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `project_name` VARCHAR(150), `requested_by` INT UNSIGNED, `department_id` SMALLINT UNSIGNED, `estimated_cost` DECIMAL(14,2), `currency_id` SMALLINT UNSIGNED, `justification` TEXT, `roi_estimate` DECIMAL(6,2), `status` ENUM('draft','submitted','approved','rejected','in_progress','completed') DEFAULT 'draft', `approved_by` INT UNSIGNED, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `treasury_transactions` (`tt_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `txn_type` ENUM('investment','loan_received','loan_given','fx_purchase','fx_sale','bond') NOT NULL, `txn_date` DATE, `amount` DECIMAL(16,2), `currency_id` SMALLINT UNSIGNED, `maturity_date` DATE, `interest_rate` DECIMAL(6,4), `counterparty` VARCHAR(150), FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 10: WORKSHOP / PITSHOP / ASSET MANAGEMENT (25 tables)
-- ============================================================
CREATE TABLE `vehicle_categories` (`vc_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `category_name` VARCHAR(80) NOT NULL, `description` TEXT) ENGINE=InnoDB;
CREATE TABLE `vehicles` (`vehicle_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `vehicle_category_id` SMALLINT UNSIGNED, `registration_no` VARCHAR(30) UNIQUE NOT NULL, `make` VARCHAR(60), `model` VARCHAR(60), `year` YEAR, `color` VARCHAR(30), `vin` VARCHAR(30), `fuel_type` ENUM('petrol','diesel','cng','electric','hybrid'), `seating_capacity` TINYINT UNSIGNED, `purchase_date` DATE, `purchase_cost` DECIMAL(12,2), `current_value` DECIMAL(12,2), `insurance_policy_no` VARCHAR(60), `insurance_expiry` DATE, `road_tax_expiry` DATE, `puc_expiry` DATE, `assigned_to` INT UNSIGNED, `location_id` SMALLINT UNSIGNED, `status` ENUM('active','in_repair','disposed','scrapped','on_loan') DEFAULT 'active', FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`vehicle_category_id`) REFERENCES `vehicle_categories`(`vc_id`), FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `vehicle_assignments` (`va_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `vehicle_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `assigned_from` DATE, `assigned_to` DATE, `purpose` VARCHAR(200), `approved_by` INT UNSIGNED, FOREIGN KEY(`vehicle_id`) REFERENCES `vehicles`(`vehicle_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `fuel_logs` (`fuel_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `vehicle_id` INT UNSIGNED NOT NULL, `driver_id` INT UNSIGNED, `fill_date` DATE NOT NULL, `odometer_reading` INT UNSIGNED, `fuel_quantity` DECIMAL(6,2), `fuel_cost` DECIMAL(10,2), `currency_id` SMALLINT UNSIGNED, `fuel_station` VARCHAR(100), `fuel_type` ENUM('petrol','diesel','cng'), FOREIGN KEY(`vehicle_id`) REFERENCES `vehicles`(`vehicle_id`)) ENGINE=InnoDB;
CREATE TABLE `trip_logs` (`trip_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `vehicle_id` INT UNSIGNED NOT NULL, `driver_id` INT UNSIGNED, `passenger_id` INT UNSIGNED, `start_date` DATETIME, `end_date` DATETIME, `start_location` VARCHAR(150), `end_location` VARCHAR(150), `start_odometer` INT UNSIGNED, `end_odometer` INT UNSIGNED, `distance_km` DECIMAL(8,2), `purpose` VARCHAR(200), `approved_by` INT UNSIGNED, FOREIGN KEY(`vehicle_id`) REFERENCES `vehicles`(`vehicle_id`)) ENGINE=InnoDB;
CREATE TABLE `workshop_job_cards` (`job_card_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `vehicle_id` INT UNSIGNED NOT NULL, `opened_date` DATE NOT NULL, `closed_date` DATE, `complaint` TEXT, `diagnosis` TEXT, `job_type` ENUM('preventive','corrective','accident','insurance','inspection') DEFAULT 'corrective', `priority` ENUM('low','normal','urgent','breakdown') DEFAULT 'normal', `assigned_mechanic_id` INT UNSIGNED, `supervisor_id` INT UNSIGNED, `status` ENUM('open','in_progress','waiting_parts','completed','cancelled') DEFAULT 'open', `odometer_in` INT UNSIGNED, `odometer_out` INT UNSIGNED, FOREIGN KEY(`vehicle_id`) REFERENCES `vehicles`(`vehicle_id`)) ENGINE=InnoDB;
CREATE TABLE `job_card_parts` (`jcp_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `job_card_id` INT UNSIGNED NOT NULL, `part_name` VARCHAR(150) NOT NULL, `part_number` VARCHAR(60), `quantity` INT UNSIGNED NOT NULL DEFAULT 1, `unit_cost` DECIMAL(10,2), `total_cost` DECIMAL(12,2), `from_stock` TINYINT(1) DEFAULT 0, FOREIGN KEY(`job_card_id`) REFERENCES `workshop_job_cards`(`job_card_id`)) ENGINE=InnoDB;
CREATE TABLE `job_card_labour` (`jcl_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `job_card_id` INT UNSIGNED NOT NULL, `mechanic_id` INT UNSIGNED, `work_description` VARCHAR(200), `hours_worked` DECIMAL(4,2), `hourly_rate` DECIMAL(8,2), `labour_cost` DECIMAL(10,2), FOREIGN KEY(`job_card_id`) REFERENCES `workshop_job_cards`(`job_card_id`)) ENGINE=InnoDB;
CREATE TABLE `service_schedules` (`ss_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `vehicle_id` INT UNSIGNED NOT NULL, `service_type` ENUM('minor','major','oil_change','tyre_rotation','ac_service','battery','annual') NOT NULL, `due_date` DATE, `due_odometer` INT UNSIGNED, `last_service_date` DATE, `last_service_odometer` INT UNSIGNED, `status` ENUM('upcoming','overdue','completed') DEFAULT 'upcoming', FOREIGN KEY(`vehicle_id`) REFERENCES `vehicles`(`vehicle_id`)) ENGINE=InnoDB;
CREATE TABLE `vehicle_incidents` (`incident_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `vehicle_id` INT UNSIGNED NOT NULL, `driver_id` INT UNSIGNED, `incident_date` DATETIME NOT NULL, `incident_type` ENUM('accident','theft','vandalism','breakdown','traffic_violation') NOT NULL, `description` TEXT, `location` VARCHAR(150), `police_report_no` VARCHAR(60), `injury_occurred` TINYINT(1) DEFAULT 0, `insurance_claimed` TINYINT(1) DEFAULT 0, `repair_cost` DECIMAL(10,2), FOREIGN KEY(`vehicle_id`) REFERENCES `vehicles`(`vehicle_id`)) ENGINE=InnoDB;
CREATE TABLE `spare_parts_inventory` (`part_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `part_name` VARCHAR(150) NOT NULL, `part_number` VARCHAR(60) UNIQUE, `category` VARCHAR(60), `brand` VARCHAR(60), `unit_cost` DECIMAL(10,2), `stock_qty` INT UNSIGNED DEFAULT 0, `reorder_level` INT UNSIGNED DEFAULT 5, `location` VARCHAR(80), `compatible_models` TEXT) ENGINE=InnoDB;
CREATE TABLE `parts_procurement` (`proc_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `part_id` INT UNSIGNED NOT NULL, `vendor` VARCHAR(100), `order_date` DATE, `quantity` INT UNSIGNED, `unit_cost` DECIMAL(10,2), `total_cost` DECIMAL(12,2), `received_date` DATE, `status` ENUM('ordered','received','cancelled') DEFAULT 'ordered', FOREIGN KEY(`part_id`) REFERENCES `spare_parts_inventory`(`part_id`)) ENGINE=InnoDB;
CREATE TABLE `equipment_register` (`equip_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `equipment_name` VARCHAR(150) NOT NULL, `equipment_type` VARCHAR(80), `serial_no` VARCHAR(60), `purchase_date` DATE, `purchase_cost` DECIMAL(12,2), `location_id` SMALLINT UNSIGNED, `assigned_to` INT UNSIGNED, `warranty_expiry` DATE, `status` ENUM('active','under_maintenance','disposed','scrapped') DEFAULT 'active', FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `equipment_maintenance` (`maint_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `equip_id` INT UNSIGNED NOT NULL, `maintenance_type` ENUM('preventive','corrective','calibration','inspection') DEFAULT 'preventive', `scheduled_date` DATE, `completed_date` DATE, `performed_by` VARCHAR(100), `cost` DECIMAL(10,2), `findings` TEXT, `next_due_date` DATE, `status` ENUM('scheduled','completed','overdue') DEFAULT 'scheduled', FOREIGN KEY(`equip_id`) REFERENCES `equipment_register`(`equip_id`)) ENGINE=InnoDB;
CREATE TABLE `asset_movements` (`movement_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `asset_id` INT UNSIGNED, `vehicle_id` INT UNSIGNED, `equip_id` INT UNSIGNED, `from_location_id` SMALLINT UNSIGNED, `to_location_id` SMALLINT UNSIGNED, `moved_date` DATE, `moved_by` INT UNSIGNED, `reason` VARCHAR(200), `approved_by` INT UNSIGNED, FOREIGN KEY(`from_location_id`) REFERENCES `locations`(`location_id`), FOREIGN KEY(`to_location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `it_assets` (`it_asset_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `asset_type` ENUM('laptop','desktop','server','mobile','tablet','printer','scanner','network_device','projector','monitor','other') NOT NULL, `brand` VARCHAR(60), `model` VARCHAR(80), `serial_no` VARCHAR(60) UNIQUE, `asset_tag` VARCHAR(30) UNIQUE, `purchase_date` DATE, `purchase_cost` DECIMAL(10,2), `warranty_expiry` DATE, `os` VARCHAR(60), `ram_gb` TINYINT UNSIGNED, `storage_gb` SMALLINT UNSIGNED, `assigned_to` INT UNSIGNED, `location_id` SMALLINT UNSIGNED, `status` ENUM('available','assigned','in_repair','disposed','lost') DEFAULT 'available', FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `it_asset_assignments` (`iaa_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `it_asset_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `assigned_from` DATE, `assigned_to` DATE, `assigned_by` INT UNSIGNED, `return_condition` ENUM('good','damaged','lost'), FOREIGN KEY(`it_asset_id`) REFERENCES `it_assets`(`it_asset_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `software_licenses` (`lic_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `software_name` VARCHAR(150) NOT NULL, `vendor` VARCHAR(100), `license_type` ENUM('perpetual','subscription','concurrent','named_user','site') DEFAULT 'subscription', `total_seats` INT UNSIGNED, `used_seats` INT UNSIGNED DEFAULT 0, `purchase_date` DATE, `expiry_date` DATE, `cost` DECIMAL(12,2), `support_contract_expiry` DATE, `status` ENUM('active','expired','cancelled') DEFAULT 'active') ENGINE=InnoDB;
CREATE TABLE `license_allocations` (`la_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `lic_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `it_asset_id` INT UNSIGNED, `allocated_at` DATE, `deallocated_at` DATE, `is_active` TINYINT(1) DEFAULT 1, FOREIGN KEY(`lic_id`) REFERENCES `software_licenses`(`lic_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `insurance_policies_company` (`policy_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `policy_type` ENUM('vehicle','property','liability','health','fire','marine','cyber','directors') NOT NULL, `insurer` VARCHAR(100), `policy_no` VARCHAR(60) UNIQUE, `start_date` DATE, `end_date` DATE, `sum_insured` DECIMAL(16,2), `premium` DECIMAL(12,2), `currency_id` SMALLINT UNSIGNED, `status` ENUM('active','expired','lapsed') DEFAULT 'active', FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `insurance_claims_company` (`claim_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `policy_id` INT UNSIGNED NOT NULL, `claim_date` DATE, `incident_date` DATE, `claim_type` VARCHAR(80), `claim_amount` DECIMAL(12,2), `approved_amount` DECIMAL(12,2), `status` ENUM('filed','under_review','approved','rejected','paid') DEFAULT 'filed', `description` TEXT, FOREIGN KEY(`policy_id`) REFERENCES `insurance_policies_company`(`policy_id`)) ENGINE=InnoDB;
CREATE TABLE `pitshop_services` (`service_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `service_name` VARCHAR(100) NOT NULL, `service_category` VARCHAR(60), `standard_time_hours` DECIMAL(4,2), `base_cost` DECIMAL(10,2), `requires_parts` TINYINT(1) DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE `pitshop_service_history` (`psh_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `job_card_id` INT UNSIGNED NOT NULL, `service_id` SMALLINT UNSIGNED NOT NULL, `performed_date` DATE, `mechanic_id` INT UNSIGNED, `time_taken_hours` DECIMAL(4,2), `status` ENUM('pending','in_progress','completed') DEFAULT 'pending', FOREIGN KEY(`job_card_id`) REFERENCES `workshop_job_cards`(`job_card_id`), FOREIGN KEY(`service_id`) REFERENCES `pitshop_services`(`service_id`)) ENGINE=InnoDB;
CREATE TABLE `tyre_management` (`tyre_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `vehicle_id` INT UNSIGNED NOT NULL, `tyre_brand` VARCHAR(60), `tyre_size` VARCHAR(30), `position` ENUM('FL','FR','RL','RR','spare') NOT NULL, `installed_date` DATE, `tread_depth_mm` DECIMAL(4,2), `mileage_km` INT UNSIGNED DEFAULT 0, `status` ENUM('active','worn','replaced','spare') DEFAULT 'active', FOREIGN KEY(`vehicle_id`) REFERENCES `vehicles`(`vehicle_id`)) ENGINE=InnoDB;
CREATE TABLE `vehicle_documents` (`vd_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `vehicle_id` INT UNSIGNED NOT NULL, `doc_type` ENUM('rc','insurance','puc','road_tax','permit','fitness') NOT NULL, `doc_number` VARCHAR(60), `issue_date` DATE, `expiry_date` DATE, `file_url` VARCHAR(300), FOREIGN KEY(`vehicle_id`) REFERENCES `vehicles`(`vehicle_id`)) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 11: IT INFRASTRUCTURE & BACKUP (20 tables)
-- ============================================================
CREATE TABLE `servers` (`server_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `server_name` VARCHAR(80) NOT NULL, `server_type` ENUM('physical','virtual','container','cloud') DEFAULT 'physical', `os` VARCHAR(60), `ip_address` VARCHAR(45), `cpu_cores` TINYINT UNSIGNED, `ram_gb` SMALLINT UNSIGNED, `storage_tb` DECIMAL(6,2), `location_id` SMALLINT UNSIGNED, `environment` ENUM('production','staging','development','dr','backup') DEFAULT 'production', `status` ENUM('online','offline','maintenance','decommissioned') DEFAULT 'online', `last_patched` DATE, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `network_devices` (`nd_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `device_name` VARCHAR(80) NOT NULL, `device_type` ENUM('router','switch','firewall','load_balancer','access_point','vpn_gateway') NOT NULL, `brand` VARCHAR(60), `model` VARCHAR(80), `ip_address` VARCHAR(45), `location_id` SMALLINT UNSIGNED, `firmware_version` VARCHAR(30), `status` ENUM('active','inactive','maintenance') DEFAULT 'active', FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `backup_policies` (`bp_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `policy_name` VARCHAR(100) NOT NULL, `backup_type` ENUM('full','incremental','differential','snapshot') DEFAULT 'full', `frequency` ENUM('hourly','daily','weekly','monthly') DEFAULT 'daily', `retention_days` SMALLINT UNSIGNED, `destination` ENUM('local','remote','cloud','tape') DEFAULT 'cloud', `encryption_enabled` TINYINT(1) DEFAULT 1, `compression_enabled` TINYINT(1) DEFAULT 1, `is_active` TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE `backup_jobs` (`job_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `policy_id` SMALLINT UNSIGNED NOT NULL, `server_id` SMALLINT UNSIGNED, `job_name` VARCHAR(100), `scheduled_at` DATETIME, `started_at` DATETIME, `completed_at` DATETIME, `status` ENUM('scheduled','running','completed','failed','skipped') DEFAULT 'scheduled', `data_size_gb` DECIMAL(10,2), `backup_location` VARCHAR(300), `error_message` TEXT, FOREIGN KEY(`policy_id`) REFERENCES `backup_policies`(`bp_id`), FOREIGN KEY(`server_id`) REFERENCES `servers`(`server_id`)) ENGINE=InnoDB;
CREATE TABLE `restore_requests` (`restore_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `backup_job_id` INT UNSIGNED NOT NULL, `requested_by` INT UNSIGNED NOT NULL, `request_date` DATETIME, `restore_point` DATETIME, `target_server_id` SMALLINT UNSIGNED, `restore_path` VARCHAR(300), `status` ENUM('pending','in_progress','completed','failed') DEFAULT 'pending', `completed_at` DATETIME, FOREIGN KEY(`backup_job_id`) REFERENCES `backup_jobs`(`job_id`), FOREIGN KEY(`requested_by`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `disaster_recovery_plans` (`drp_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `plan_name` VARCHAR(100) NOT NULL, `rto_hours` TINYINT UNSIGNED, `rpo_hours` TINYINT UNSIGNED, `last_tested` DATE, `next_test_date` DATE, `status` ENUM('draft','approved','active') DEFAULT 'draft', `plan_url` VARCHAR(300), FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `dr_drills` (`drill_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `drp_id` SMALLINT UNSIGNED NOT NULL, `drill_date` DATE, `duration_hours` DECIMAL(4,2), `rto_achieved_hours` DECIMAL(4,2), `rpo_achieved_hours` DECIMAL(4,2), `passed` TINYINT(1), `findings` TEXT, `conducted_by` INT UNSIGNED, FOREIGN KEY(`drp_id`) REFERENCES `disaster_recovery_plans`(`drp_id`)) ENGINE=InnoDB;
CREATE TABLE `it_helpdesk_tickets` (`ticket_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `ticket_number` VARCHAR(20) UNIQUE, `category` ENUM('hardware','software','network','access','email','phone','printer','other') NOT NULL, `priority` ENUM('low','medium','high','critical') DEFAULT 'medium', `subject` VARCHAR(200) NOT NULL, `description` TEXT, `assigned_to` INT UNSIGNED, `status` ENUM('open','in_progress','pending_user','resolved','closed') DEFAULT 'open', `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `resolved_at` DATETIME, `sla_due_at` DATETIME, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `it_ticket_comments` (`comment_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `ticket_id` INT UNSIGNED NOT NULL, `commenter_id` INT UNSIGNED, `comment` TEXT NOT NULL, `is_internal` TINYINT(1) DEFAULT 0, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`ticket_id`) REFERENCES `it_helpdesk_tickets`(`ticket_id`)) ENGINE=InnoDB;
CREATE TABLE `system_monitoring` (`monitor_id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `server_id` SMALLINT UNSIGNED NOT NULL, `recorded_at` DATETIME NOT NULL, `cpu_usage_pct` DECIMAL(5,2), `memory_usage_pct` DECIMAL(5,2), `disk_usage_pct` DECIMAL(5,2), `network_in_mbps` DECIMAL(8,2), `network_out_mbps` DECIMAL(8,2), `response_time_ms` INT UNSIGNED, `is_alert` TINYINT(1) DEFAULT 0, FOREIGN KEY(`server_id`) REFERENCES `servers`(`server_id`)) ENGINE=InnoDB;
CREATE TABLE `ssl_certificates` (`ssl_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `domain` VARCHAR(200) NOT NULL, `issuer` VARCHAR(100), `issued_date` DATE, `expiry_date` DATE, `cert_type` ENUM('domain','wildcard','ev','ov') DEFAULT 'domain', `server_id` SMALLINT UNSIGNED, `status` ENUM('active','expiring_soon','expired','revoked') DEFAULT 'active', FOREIGN KEY(`server_id`) REFERENCES `servers`(`server_id`)) ENGINE=InnoDB;
CREATE TABLE `domain_registrations` (`domain_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `domain_name` VARCHAR(200) NOT NULL UNIQUE, `registrar` VARCHAR(100), `registered_date` DATE, `expiry_date` DATE, `auto_renew` TINYINT(1) DEFAULT 1, `owner_company_id` SMALLINT UNSIGNED, `status` ENUM('active','expired','transferred','pending') DEFAULT 'active', FOREIGN KEY(`owner_company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `vpn_users` (`vpn_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL UNIQUE, `vpn_username` VARCHAR(60) UNIQUE NOT NULL, `protocol` ENUM('openvpn','wireguard','ipsec','ssl') DEFAULT 'openvpn', `created_at` DATE, `last_login` DATETIME, `is_active` TINYINT(1) DEFAULT 1, `mfa_enabled` TINYINT(1) DEFAULT 0, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `access_control_lists` (`acl_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `resource_name` VARCHAR(150) NOT NULL, `resource_type` ENUM('server','application','database','network','file_share') NOT NULL, `role_or_user` VARCHAR(80), `permission` SET('read','write','execute','admin') NOT NULL, `granted_by` INT UNSIGNED, `granted_at` DATE, `expires_at` DATE, `is_active` TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE `security_incidents` (`inc_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `incident_type` ENUM('phishing','malware','data_breach','unauthorized_access','ddos','ransomware','insider_threat') NOT NULL, `severity` ENUM('low','medium','high','critical') DEFAULT 'medium', `detected_at` DATETIME, `reported_by` INT UNSIGNED, `description` TEXT, `affected_systems` TEXT, `status` ENUM('open','investigating','contained','resolved','closed') DEFAULT 'open', `resolved_at` DATETIME, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `patch_management` (`patch_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `server_id` SMALLINT UNSIGNED, `it_asset_id` INT UNSIGNED, `patch_name` VARCHAR(150), `patch_version` VARCHAR(30), `severity` ENUM('critical','high','medium','low','informational') DEFAULT 'medium', `scheduled_date` DATE, `applied_date` DATE, `applied_by` INT UNSIGNED, `status` ENUM('pending','applied','failed','skipped') DEFAULT 'pending', `reboot_required` TINYINT(1) DEFAULT 0, FOREIGN KEY(`server_id`) REFERENCES `servers`(`server_id`)) ENGINE=InnoDB;
CREATE TABLE `cloud_resources` (`cloud_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `provider` ENUM('aws','azure','gcp','oracle','ibm','alibaba') NOT NULL, `resource_type` VARCHAR(60), `resource_id` VARCHAR(100), `region` VARCHAR(60), `monthly_cost` DECIMAL(10,2), `currency_id` SMALLINT UNSIGNED, `tags` JSON, `status` ENUM('running','stopped','terminated') DEFAULT 'running', FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `cloud_cost_reports` (`report_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `month` VARCHAR(10), `provider` ENUM('aws','azure','gcp','other'), `total_cost` DECIMAL(12,2), `currency_id` SMALLINT UNSIGNED, `cost_breakdown` JSON, `generated_at` DATETIME, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `change_requests` (`cr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `title` VARCHAR(200) NOT NULL, `description` TEXT, `change_type` ENUM('standard','emergency','normal') DEFAULT 'normal', `priority` ENUM('low','medium','high','critical') DEFAULT 'medium', `risk_level` ENUM('low','medium','high') DEFAULT 'low', `requested_by` INT UNSIGNED, `assigned_to` INT UNSIGNED, `scheduled_date` DATETIME, `implemented_date` DATETIME, `status` ENUM('draft','submitted','approved','scheduled','implemented','failed','closed') DEFAULT 'draft', `rollback_plan` TEXT, FOREIGN KEY(`requested_by`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `configuration_items` (`ci_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `ci_name` VARCHAR(100) NOT NULL, `ci_type` ENUM('server','network','application','database','service','process') NOT NULL, `ci_version` VARCHAR(30), `owner_id` INT UNSIGNED, `environment` ENUM('production','staging','development','dr') DEFAULT 'production', `dependencies` JSON, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `last_updated` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 12: COMPLIANCE & LEGAL (15 tables)
-- ============================================================
CREATE TABLE `compliance_frameworks` (`cf_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `framework_name` VARCHAR(100) NOT NULL, `framework_type` ENUM('iso','gdpr','soc2','hipaa','pci_dss','local_law','industry') NOT NULL, `description` TEXT, `version` VARCHAR(20), `effective_date` DATE) ENGINE=InnoDB;
CREATE TABLE `compliance_requirements` (`req_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `cf_id` SMALLINT UNSIGNED NOT NULL, `requirement_code` VARCHAR(30), `requirement_name` VARCHAR(150) NOT NULL, `description` TEXT, `category` VARCHAR(60), `is_mandatory` TINYINT(1) DEFAULT 1, FOREIGN KEY(`cf_id`) REFERENCES `compliance_frameworks`(`cf_id`)) ENGINE=InnoDB;
CREATE TABLE `compliance_assessments` (`assessment_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `cf_id` SMALLINT UNSIGNED NOT NULL, `assessment_date` DATE, `assessor_id` INT UNSIGNED, `overall_status` ENUM('compliant','partially_compliant','non_compliant','not_assessed') DEFAULT 'not_assessed', `score` DECIMAL(5,2), `next_review_date` DATE, `report_url` VARCHAR(300), FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`cf_id`) REFERENCES `compliance_frameworks`(`cf_id`)) ENGINE=InnoDB;
CREATE TABLE `compliance_controls` (`control_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `assessment_id` INT UNSIGNED NOT NULL, `req_id` INT UNSIGNED NOT NULL, `status` ENUM('implemented','partial','not_implemented','not_applicable') DEFAULT 'not_implemented', `evidence_url` VARCHAR(300), `owner_id` INT UNSIGNED, `due_date` DATE, `remarks` TEXT, FOREIGN KEY(`assessment_id`) REFERENCES `compliance_assessments`(`assessment_id`), FOREIGN KEY(`req_id`) REFERENCES `compliance_requirements`(`req_id`)) ENGINE=InnoDB;
CREATE TABLE `data_privacy_requests` (`dpr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `requester_type` ENUM('employee','customer','candidate','vendor') NOT NULL, `requester_id` INT UNSIGNED, `request_type` ENUM('access','deletion','correction','portability','restriction') NOT NULL, `received_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `due_date` DATE, `status` ENUM('pending','in_progress','completed','rejected') DEFAULT 'pending', `handled_by` INT UNSIGNED, `completed_at` DATETIME) ENGINE=InnoDB;
CREATE TABLE `data_breach_log` (`breach_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `incident_date` DATE, `detected_date` DATE, `data_types_affected` TEXT, `records_affected` INT UNSIGNED, `root_cause` TEXT, `notified_regulator` TINYINT(1) DEFAULT 0, `notification_date` DATE, `remediation_steps` TEXT, `status` ENUM('open','contained','resolved') DEFAULT 'open', FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `consent_records` (`consent_id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `entity_type` ENUM('employee','customer','candidate','contact') NOT NULL, `entity_id` INT UNSIGNED NOT NULL, `consent_type` VARCHAR(80) NOT NULL, `consented` TINYINT(1) DEFAULT 1, `ip_address` VARCHAR(45), `collected_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `revoked_at` DATETIME, `version` VARCHAR(10)) ENGINE=InnoDB;
CREATE TABLE `legal_entities` (`le_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `entity_name` VARCHAR(150) NOT NULL, `entity_type` ENUM('corporation','llp','partnership','branch','representative') NOT NULL, `jurisdiction` VARCHAR(80), `registration_no` VARCHAR(60), `incorporated_date` DATE, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `legal_cases` (`case_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `case_number` VARCHAR(60), `case_type` ENUM('labour','commercial','intellectual_property','regulatory','tax','criminal','civil') NOT NULL, `court` VARCHAR(150), `opposing_party` VARCHAR(150), `our_lawyer` VARCHAR(100), `filed_date` DATE, `next_hearing_date` DATE, `status` ENUM('active','settled','won','lost','withdrawn','appealed') DEFAULT 'active', `description` TEXT, `estimated_liability` DECIMAL(14,2), FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `legal_documents` (`ld_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `case_id` INT UNSIGNED, `contract_id` INT UNSIGNED, `doc_type` VARCHAR(80), `doc_name` VARCHAR(200), `filed_by` INT UNSIGNED, `filed_date` DATE, `file_url` VARCHAR(300), FOREIGN KEY(`case_id`) REFERENCES `legal_cases`(`case_id`), FOREIGN KEY(`contract_id`) REFERENCES `contracts`(`contract_id`)) ENGINE=InnoDB;
CREATE TABLE `policy_acknowledgements` (`pa_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `cp_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `acknowledged_at` DATETIME, `method` ENUM('digital','physical','email') DEFAULT 'digital', `ip_address` VARCHAR(45), FOREIGN KEY(`cp_id`) REFERENCES `company_policies`(`cp_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `whistleblower_reports` (`wb_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `category` ENUM('fraud','harassment','safety','financial_misconduct','discrimination','other') NOT NULL, `description` TEXT NOT NULL, `is_anonymous` TINYINT(1) DEFAULT 1, `reporter_employee_id` INT UNSIGNED, `status` ENUM('received','investigating','resolved','closed') DEFAULT 'received', `assigned_to` INT UNSIGNED, `submitted_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `resolved_at` DATETIME, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `regulatory_filings` (`rf_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `regulator` VARCHAR(100), `filing_type` VARCHAR(80), `period` VARCHAR(20), `due_date` DATE, `filed_date` DATE, `status` ENUM('pending','filed','accepted','rejected') DEFAULT 'pending', `reference_no` VARCHAR(60), `file_url` VARCHAR(300), FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `risk_register` (`risk_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `risk_title` VARCHAR(150) NOT NULL, `category` ENUM('operational','financial','compliance','strategic','reputational','it','hr') NOT NULL, `description` TEXT, `likelihood` TINYINT UNSIGNED, `impact` TINYINT UNSIGNED, `risk_score` TINYINT UNSIGNED, `status` ENUM('open','mitigated','accepted','transferred','closed') DEFAULT 'open', `owner_id` INT UNSIGNED, `mitigation_plan` TEXT, `review_date` DATE, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `risk_incidents` (`ri_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `risk_id` INT UNSIGNED NOT NULL, `incident_date` DATE, `description` TEXT, `financial_impact` DECIMAL(14,2), `resolved_at` DATE, `lessons_learned` TEXT, FOREIGN KEY(`risk_id`) REFERENCES `risk_register`(`risk_id`)) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 13: INVENTORY & WAREHOUSE (20 tables)
-- ============================================================
CREATE TABLE `warehouses` (`warehouse_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `warehouse_name` VARCHAR(100) NOT NULL, `warehouse_code` VARCHAR(20), `location_id` SMALLINT UNSIGNED, `capacity_sqft` DECIMAL(10,2), `manager_id` INT UNSIGNED, `is_active` TINYINT(1) DEFAULT 1, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `warehouse_zones` (`zone_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `warehouse_id` SMALLINT UNSIGNED NOT NULL, `zone_name` VARCHAR(60) NOT NULL, `zone_type` ENUM('receiving','storage','picking','packing','shipping','returns') DEFAULT 'storage', `capacity` DECIMAL(10,2), FOREIGN KEY(`warehouse_id`) REFERENCES `warehouses`(`warehouse_id`)) ENGINE=InnoDB;
CREATE TABLE `bin_locations` (`bin_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `zone_id` SMALLINT UNSIGNED NOT NULL, `bin_code` VARCHAR(20) NOT NULL, `row_no` VARCHAR(10), `shelf_no` VARCHAR(10), `level_no` VARCHAR(10), `max_weight_kg` DECIMAL(8,2), `is_occupied` TINYINT(1) DEFAULT 0, FOREIGN KEY(`zone_id`) REFERENCES `warehouse_zones`(`zone_id`)) ENGINE=InnoDB;
CREATE TABLE `inventory` (`inventory_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `product_id` INT UNSIGNED NOT NULL, `variant_id` INT UNSIGNED, `warehouse_id` SMALLINT UNSIGNED NOT NULL, `bin_id` INT UNSIGNED, `qty_on_hand` INT NOT NULL DEFAULT 0, `qty_reserved` INT DEFAULT 0, `qty_available` INT, `qty_in_transit` INT DEFAULT 0, `last_counted` DATE, FOREIGN KEY(`product_id`) REFERENCES `products`(`product_id`), FOREIGN KEY(`variant_id`) REFERENCES `product_variants`(`variant_id`), FOREIGN KEY(`warehouse_id`) REFERENCES `warehouses`(`warehouse_id`), FOREIGN KEY(`bin_id`) REFERENCES `bin_locations`(`bin_id`)) ENGINE=InnoDB;
CREATE TABLE `inventory_transactions` (`txn_id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `product_id` INT UNSIGNED NOT NULL, `warehouse_id` SMALLINT UNSIGNED NOT NULL, `txn_type` ENUM('receipt','issue','transfer','adjustment','return','scrap','write_off') NOT NULL, `qty` INT NOT NULL, `reference_type` VARCHAR(30), `reference_id` INT UNSIGNED, `txn_date` DATETIME DEFAULT CURRENT_TIMESTAMP, `performed_by` INT UNSIGNED, `notes` VARCHAR(200), FOREIGN KEY(`product_id`) REFERENCES `products`(`product_id`), FOREIGN KEY(`warehouse_id`) REFERENCES `warehouses`(`warehouse_id`)) ENGINE=InnoDB;
CREATE TABLE `stock_transfer_orders` (`sto_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `sto_number` VARCHAR(30) UNIQUE NOT NULL, `from_warehouse_id` SMALLINT UNSIGNED NOT NULL, `to_warehouse_id` SMALLINT UNSIGNED NOT NULL, `requested_by` INT UNSIGNED, `approved_by` INT UNSIGNED, `transfer_date` DATE, `status` ENUM('draft','approved','in_transit','received','cancelled') DEFAULT 'draft', FOREIGN KEY(`from_warehouse_id`) REFERENCES `warehouses`(`warehouse_id`), FOREIGN KEY(`to_warehouse_id`) REFERENCES `warehouses`(`warehouse_id`)) ENGINE=InnoDB;
CREATE TABLE `sto_items` (`si_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `sto_id` INT UNSIGNED NOT NULL, `product_id` INT UNSIGNED NOT NULL, `requested_qty` INT UNSIGNED, `approved_qty` INT UNSIGNED, `shipped_qty` INT UNSIGNED DEFAULT 0, `received_qty` INT UNSIGNED DEFAULT 0, FOREIGN KEY(`sto_id`) REFERENCES `stock_transfer_orders`(`sto_id`), FOREIGN KEY(`product_id`) REFERENCES `products`(`product_id`)) ENGINE=InnoDB;
CREATE TABLE `goods_receipts` (`grn_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `grn_number` VARCHAR(30) UNIQUE NOT NULL, `po_id` INT UNSIGNED NOT NULL, `warehouse_id` SMALLINT UNSIGNED NOT NULL, `receipt_date` DATE NOT NULL, `received_by` INT UNSIGNED, `status` ENUM('draft','partial','complete','returned') DEFAULT 'draft', `notes` TEXT, FOREIGN KEY(`po_id`) REFERENCES `purchase_orders`(`po_id`), FOREIGN KEY(`warehouse_id`) REFERENCES `warehouses`(`warehouse_id`)) ENGINE=InnoDB;
CREATE TABLE `grn_items` (`gi_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `grn_id` INT UNSIGNED NOT NULL, `po_item_id` INT UNSIGNED NOT NULL, `received_qty` INT UNSIGNED NOT NULL, `accepted_qty` INT UNSIGNED, `rejected_qty` INT UNSIGNED DEFAULT 0, `bin_id` INT UNSIGNED, `batch_no` VARCHAR(30), `expiry_date` DATE, FOREIGN KEY(`grn_id`) REFERENCES `goods_receipts`(`grn_id`), FOREIGN KEY(`po_item_id`) REFERENCES `po_items`(`po_item_id`)) ENGINE=InnoDB;
CREATE TABLE `cycle_count_schedules` (`ccs_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `warehouse_id` SMALLINT UNSIGNED NOT NULL, `zone_id` SMALLINT UNSIGNED, `schedule_date` DATE, `frequency` ENUM('daily','weekly','monthly','quarterly','annual') DEFAULT 'monthly', `assigned_to` INT UNSIGNED, `status` ENUM('scheduled','in_progress','completed') DEFAULT 'scheduled', FOREIGN KEY(`warehouse_id`) REFERENCES `warehouses`(`warehouse_id`)) ENGINE=InnoDB;
CREATE TABLE `cycle_count_results` (`ccr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `ccs_id` INT UNSIGNED NOT NULL, `product_id` INT UNSIGNED NOT NULL, `bin_id` INT UNSIGNED, `system_qty` INT, `counted_qty` INT, `variance` INT, `adjustment_made` TINYINT(1) DEFAULT 0, `counted_by` INT UNSIGNED, FOREIGN KEY(`ccs_id`) REFERENCES `cycle_count_schedules`(`ccs_id`), FOREIGN KEY(`product_id`) REFERENCES `products`(`product_id`)) ENGINE=InnoDB;
CREATE TABLE `reorder_suggestions` (`rs_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `product_id` INT UNSIGNED NOT NULL, `warehouse_id` SMALLINT UNSIGNED NOT NULL, `current_stock` INT, `reorder_level` INT, `suggested_qty` INT, `suggested_vendor_id` INT UNSIGNED, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `status` ENUM('pending','ordered','ignored') DEFAULT 'pending', FOREIGN KEY(`product_id`) REFERENCES `products`(`product_id`)) ENGINE=InnoDB;
CREATE TABLE `batch_lots` (`batch_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `product_id` INT UNSIGNED NOT NULL, `batch_number` VARCHAR(60) NOT NULL, `manufacture_date` DATE, `expiry_date` DATE, `qty_received` INT UNSIGNED, `qty_remaining` INT UNSIGNED, `warehouse_id` SMALLINT UNSIGNED, `status` ENUM('active','partially_used','exhausted','expired','quarantined') DEFAULT 'active', FOREIGN KEY(`product_id`) REFERENCES `products`(`product_id`)) ENGINE=InnoDB;
CREATE TABLE `quality_inspections` (`qi_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `grn_id` INT UNSIGNED, `product_id` INT UNSIGNED NOT NULL, `batch_id` INT UNSIGNED, `inspected_qty` INT UNSIGNED, `passed_qty` INT UNSIGNED, `failed_qty` INT UNSIGNED, `inspector_id` INT UNSIGNED, `inspection_date` DATE, `notes` TEXT, `status` ENUM('pending','passed','failed','partial') DEFAULT 'pending', FOREIGN KEY(`product_id`) REFERENCES `products`(`product_id`)) ENGINE=InnoDB;
CREATE TABLE `vendor_product_catalog` (`vpc_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `vendor_account_id` INT UNSIGNED NOT NULL, `product_id` INT UNSIGNED NOT NULL, `vendor_product_code` VARCHAR(60), `lead_time_days` TINYINT UNSIGNED, `min_order_qty` INT UNSIGNED DEFAULT 1, `unit_price` DECIMAL(12,2), `currency_id` SMALLINT UNSIGNED, `is_preferred` TINYINT(1) DEFAULT 0, FOREIGN KEY(`vendor_account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`product_id`) REFERENCES `products`(`product_id`)) ENGINE=InnoDB;
CREATE TABLE `packing_materials` (`pm_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `material_name` VARCHAR(80) NOT NULL, `dimensions` VARCHAR(60), `weight_kg` DECIMAL(6,3), `unit_cost` DECIMAL(8,2), `stock_qty` INT UNSIGNED DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE `picking_lists` (`pl_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `order_id` INT UNSIGNED NOT NULL, `warehouse_id` SMALLINT UNSIGNED NOT NULL, `picker_id` INT UNSIGNED, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `started_at` DATETIME, `completed_at` DATETIME, `status` ENUM('generated','in_progress','completed','cancelled') DEFAULT 'generated', FOREIGN KEY(`order_id`) REFERENCES `sales_orders`(`order_id`), FOREIGN KEY(`warehouse_id`) REFERENCES `warehouses`(`warehouse_id`)) ENGINE=InnoDB;
CREATE TABLE `packing_lists` (`packlist_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `picking_list_id` INT UNSIGNED NOT NULL, `packer_id` INT UNSIGNED, `packed_at` DATETIME, `total_weight_kg` DECIMAL(8,2), `package_count` TINYINT UNSIGNED DEFAULT 1, `status` ENUM('pending','in_progress','completed') DEFAULT 'pending', FOREIGN KEY(`picking_list_id`) REFERENCES `picking_lists`(`pl_id`)) ENGINE=InnoDB;
CREATE TABLE `inventory_valuation` (`val_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `product_id` INT UNSIGNED NOT NULL, `warehouse_id` SMALLINT UNSIGNED NOT NULL, `valuation_method` ENUM('fifo','lifo','weighted_avg','standard_cost') DEFAULT 'weighted_avg', `qty_on_hand` INT, `unit_cost` DECIMAL(12,4), `total_value` DECIMAL(16,2), `as_of_date` DATE, FOREIGN KEY(`product_id`) REFERENCES `products`(`product_id`), FOREIGN KEY(`warehouse_id`) REFERENCES `warehouses`(`warehouse_id`)) ENGINE=InnoDB;
CREATE TABLE `dead_stock_report` (`ds_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `product_id` INT UNSIGNED NOT NULL, `warehouse_id` SMALLINT UNSIGNED, `qty_on_hand` INT, `last_movement_date` DATE, `days_without_movement` SMALLINT UNSIGNED, `carrying_cost` DECIMAL(12,2), `recommended_action` ENUM('mark_down','write_off','return_to_vendor','donate','scrap') DEFAULT 'mark_down', FOREIGN KEY(`product_id`) REFERENCES `products`(`product_id`)) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 14: PROJECT MANAGEMENT (20 tables)
-- ============================================================
CREATE TABLE `project_types` (`pt_id` TINYINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `type_name` VARCHAR(60) NOT NULL, `description` TEXT) ENGINE=InnoDB;
CREATE TABLE `projects` (`project_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `project_type_id` TINYINT UNSIGNED, `project_name` VARCHAR(200) NOT NULL, `project_code` VARCHAR(30) UNIQUE, `client_account_id` INT UNSIGNED, `department_id` SMALLINT UNSIGNED, `manager_id` INT UNSIGNED, `start_date` DATE, `end_date` DATE, `actual_start` DATE, `actual_end` DATE, `budget` DECIMAL(16,2), `actual_cost` DECIMAL(16,2), `currency_id` SMALLINT UNSIGNED, `status` ENUM('planning','active','on_hold','completed','cancelled','overdue') DEFAULT 'planning', `priority` ENUM('low','medium','high','critical') DEFAULT 'medium', `description` TEXT, `completion_pct` DECIMAL(5,2) DEFAULT 0, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`project_type_id`) REFERENCES `project_types`(`pt_id`), FOREIGN KEY(`client_account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`manager_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `project_members` (`pm_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `project_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `role` VARCHAR(60), `allocation_pct` TINYINT UNSIGNED DEFAULT 100, `joined_date` DATE, `left_date` DATE, `is_active` TINYINT(1) DEFAULT 1, FOREIGN KEY(`project_id`) REFERENCES `projects`(`project_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `sprints` (`sprint_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `project_id` INT UNSIGNED NOT NULL, `sprint_name` VARCHAR(80) NOT NULL, `sprint_no` TINYINT UNSIGNED, `start_date` DATE, `end_date` DATE, `story_points_planned` SMALLINT UNSIGNED, `story_points_completed` SMALLINT UNSIGNED DEFAULT 0, `velocity` DECIMAL(6,2), `status` ENUM('planned','active','completed','cancelled') DEFAULT 'planned', FOREIGN KEY(`project_id`) REFERENCES `projects`(`project_id`)) ENGINE=InnoDB;
CREATE TABLE `milestones` (`milestone_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `project_id` INT UNSIGNED NOT NULL, `milestone_name` VARCHAR(150) NOT NULL, `due_date` DATE, `completed_date` DATE, `status` ENUM('pending','achieved','missed','deferred') DEFAULT 'pending', `dependencies` TEXT, `description` TEXT, FOREIGN KEY(`project_id`) REFERENCES `projects`(`project_id`)) ENGINE=InnoDB;
CREATE TABLE `tasks` (`task_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `project_id` INT UNSIGNED NOT NULL, `sprint_id` INT UNSIGNED, `milestone_id` INT UNSIGNED, `parent_task_id` INT UNSIGNED, `task_name` VARCHAR(200) NOT NULL, `description` TEXT, `task_type` ENUM('feature','bug','improvement','task','story','epic','sub_task') DEFAULT 'task', `assigned_to` INT UNSIGNED, `reporter_id` INT UNSIGNED, `start_date` DATE, `due_date` DATE, `completed_date` DATE, `estimated_hours` DECIMAL(6,2), `actual_hours` DECIMAL(6,2) DEFAULT 0, `story_points` TINYINT UNSIGNED, `priority` ENUM('low','medium','high','critical') DEFAULT 'medium', `status` ENUM('backlog','to_do','in_progress','in_review','testing','done','cancelled') DEFAULT 'to_do', `completion_pct` DECIMAL(5,2) DEFAULT 0, FOREIGN KEY(`project_id`) REFERENCES `projects`(`project_id`), FOREIGN KEY(`sprint_id`) REFERENCES `sprints`(`sprint_id`), FOREIGN KEY(`milestone_id`) REFERENCES `milestones`(`milestone_id`), FOREIGN KEY(`parent_task_id`) REFERENCES `tasks`(`task_id`), FOREIGN KEY(`assigned_to`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `task_comments` (`comment_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `task_id` INT UNSIGNED NOT NULL, `commented_by` INT UNSIGNED NOT NULL, `comment` TEXT NOT NULL, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `is_edited` TINYINT(1) DEFAULT 0, FOREIGN KEY(`task_id`) REFERENCES `tasks`(`task_id`), FOREIGN KEY(`commented_by`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `task_attachments` (`att_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `task_id` INT UNSIGNED NOT NULL, `file_name` VARCHAR(200), `file_url` VARCHAR(300), `file_size_kb` INT UNSIGNED, `uploaded_by` INT UNSIGNED, `uploaded_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`task_id`) REFERENCES `tasks`(`task_id`)) ENGINE=InnoDB;
CREATE TABLE `time_logs` (`log_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `task_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `log_date` DATE NOT NULL, `hours_logged` DECIMAL(5,2) NOT NULL, `description` VARCHAR(200), `is_billable` TINYINT(1) DEFAULT 0, `billing_rate` DECIMAL(10,2), `approved_by` INT UNSIGNED, `status` ENUM('draft','submitted','approved','rejected') DEFAULT 'draft', FOREIGN KEY(`task_id`) REFERENCES `tasks`(`task_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `project_risks` (`risk_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `project_id` INT UNSIGNED NOT NULL, `risk_title` VARCHAR(150), `description` TEXT, `likelihood` TINYINT UNSIGNED, `impact` TINYINT UNSIGNED, `risk_score` TINYINT UNSIGNED, `mitigation_plan` TEXT, `owner_id` INT UNSIGNED, `status` ENUM('open','mitigated','accepted','closed') DEFAULT 'open', FOREIGN KEY(`project_id`) REFERENCES `projects`(`project_id`)) ENGINE=InnoDB;
CREATE TABLE `project_issues` (`issue_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `project_id` INT UNSIGNED NOT NULL, `issue_title` VARCHAR(200) NOT NULL, `description` TEXT, `severity` ENUM('low','medium','high','critical') DEFAULT 'medium', `raised_by` INT UNSIGNED, `assigned_to` INT UNSIGNED, `raised_date` DATE, `resolved_date` DATE, `status` ENUM('open','in_progress','resolved','closed') DEFAULT 'open', FOREIGN KEY(`project_id`) REFERENCES `projects`(`project_id`)) ENGINE=InnoDB;
CREATE TABLE `project_documents` (`pd_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `project_id` INT UNSIGNED NOT NULL, `doc_type` ENUM('sow','prd','design','test_plan','meeting_notes','sign_off','other') NOT NULL, `doc_name` VARCHAR(200), `version` VARCHAR(10), `file_url` VARCHAR(300), `uploaded_by` INT UNSIGNED, `uploaded_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`project_id`) REFERENCES `projects`(`project_id`)) ENGINE=InnoDB;
CREATE TABLE `project_budgets` (`pb_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `project_id` INT UNSIGNED NOT NULL, `budget_category` ENUM('labor','software','hardware','travel','training','contingency','other') NOT NULL, `budgeted_amount` DECIMAL(14,2), `actual_amount` DECIMAL(14,2) DEFAULT 0, `currency_id` SMALLINT UNSIGNED, FOREIGN KEY(`project_id`) REFERENCES `projects`(`project_id`)) ENGINE=InnoDB;
CREATE TABLE `change_controls` (`cc_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `project_id` INT UNSIGNED NOT NULL, `change_title` VARCHAR(150) NOT NULL, `description` TEXT, `impact_assessment` TEXT, `effort_hours` DECIMAL(6,2), `cost_impact` DECIMAL(12,2), `schedule_impact_days` SMALLINT, `requested_by` INT UNSIGNED, `status` ENUM('draft','submitted','approved','rejected','implemented') DEFAULT 'draft', `approved_by` INT UNSIGNED, FOREIGN KEY(`project_id`) REFERENCES `projects`(`project_id`)) ENGINE=InnoDB;
CREATE TABLE `retrospectives` (`retro_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `project_id` INT UNSIGNED NOT NULL, `sprint_id` INT UNSIGNED, `retro_date` DATE, `what_went_well` TEXT, `what_to_improve` TEXT, `action_items` TEXT, `facilitator_id` INT UNSIGNED, FOREIGN KEY(`project_id`) REFERENCES `projects`(`project_id`), FOREIGN KEY(`sprint_id`) REFERENCES `sprints`(`sprint_id`)) ENGINE=InnoDB;
CREATE TABLE `project_dependencies` (`dep_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `project_id` INT UNSIGNED NOT NULL, `depends_on_project_id` INT UNSIGNED NOT NULL, `dependency_type` ENUM('finish_to_start','start_to_start','finish_to_finish','start_to_finish') DEFAULT 'finish_to_start', `lag_days` SMALLINT, FOREIGN KEY(`project_id`) REFERENCES `projects`(`project_id`), FOREIGN KEY(`depends_on_project_id`) REFERENCES `projects`(`project_id`)) ENGINE=InnoDB;
CREATE TABLE `stakeholders` (`sh_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `project_id` INT UNSIGNED NOT NULL, `contact_id` INT UNSIGNED, `employee_id` INT UNSIGNED, `stake_type` ENUM('sponsor','client','reviewer','approver','observer') NOT NULL, `interest_level` ENUM('low','medium','high') DEFAULT 'medium', `influence_level` ENUM('low','medium','high') DEFAULT 'medium', FOREIGN KEY(`project_id`) REFERENCES `projects`(`project_id`)) ENGINE=InnoDB;
CREATE TABLE `gantt_tasks` (`gt_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `project_id` INT UNSIGNED NOT NULL, `task_id` INT UNSIGNED NOT NULL, `planned_start` DATE, `planned_end` DATE, `actual_start` DATE, `actual_end` DATE, `baseline_start` DATE, `baseline_end` DATE, FOREIGN KEY(`project_id`) REFERENCES `projects`(`project_id`), FOREIGN KEY(`task_id`) REFERENCES `tasks`(`task_id`)) ENGINE=InnoDB;
CREATE TABLE `work_breakdown_structure` (`wbs_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `project_id` INT UNSIGNED NOT NULL, `wbs_code` VARCHAR(30) NOT NULL, `element_name` VARCHAR(150) NOT NULL, `parent_wbs_id` INT UNSIGNED, `level` TINYINT UNSIGNED, `deliverable` VARCHAR(200), `task_id` INT UNSIGNED, FOREIGN KEY(`project_id`) REFERENCES `projects`(`project_id`)) ENGINE=InnoDB;
CREATE TABLE `project_kpis` (`kpi_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `project_id` INT UNSIGNED NOT NULL, `kpi_name` VARCHAR(100) NOT NULL, `target_value` DECIMAL(12,2), `current_value` DECIMAL(12,2), `unit` VARCHAR(30), `status` ENUM('on_track','at_risk','off_track') DEFAULT 'on_track', `as_of_date` DATE, FOREIGN KEY(`project_id`) REFERENCES `projects`(`project_id`)) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 15: SUPPORT / HELPDESK (15 tables)
-- ============================================================
CREATE TABLE `support_categories` (`sc_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `category_name` VARCHAR(80) NOT NULL, `parent_cat_id` SMALLINT UNSIGNED, `sla_hours` TINYINT UNSIGNED, FOREIGN KEY(`parent_cat_id`) REFERENCES `support_categories`(`sc_id`)) ENGINE=InnoDB;
CREATE TABLE `sla_policies` (`sla_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `policy_name` VARCHAR(100) NOT NULL, `priority` ENUM('low','medium','high','critical') NOT NULL, `first_response_hours` TINYINT UNSIGNED, `resolution_hours` SMALLINT UNSIGNED, `is_business_hours_only` TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE `support_tickets` (`ticket_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `ticket_number` VARCHAR(20) UNIQUE NOT NULL, `account_id` INT UNSIGNED, `contact_id` INT UNSIGNED, `employee_reporter_id` INT UNSIGNED, `category_id` SMALLINT UNSIGNED, `sla_policy_id` SMALLINT UNSIGNED, `subject` VARCHAR(200) NOT NULL, `description` TEXT, `priority` ENUM('low','medium','high','critical') DEFAULT 'medium', `status` ENUM('new','open','in_progress','pending_customer','pending_internal','escalated','resolved','closed') DEFAULT 'new', `assigned_to` INT UNSIGNED, `assigned_team_id` INT UNSIGNED, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `first_response_at` DATETIME, `resolved_at` DATETIME, `closed_at` DATETIME, `sla_due_at` DATETIME, `sla_breached` TINYINT(1) DEFAULT 0, `satisfaction_rating` TINYINT UNSIGNED, FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`contact_id`) REFERENCES `crm_contacts`(`contact_id`), FOREIGN KEY(`category_id`) REFERENCES `support_categories`(`sc_id`), FOREIGN KEY(`sla_policy_id`) REFERENCES `sla_policies`(`sla_id`), FOREIGN KEY(`assigned_to`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `ticket_comments` (`comment_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `ticket_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED, `comment` TEXT NOT NULL, `is_internal` TINYINT(1) DEFAULT 0, `is_solution` TINYINT(1) DEFAULT 0, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`ticket_id`) REFERENCES `support_tickets`(`ticket_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `ticket_escalations` (`esc_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `ticket_id` INT UNSIGNED NOT NULL, `escalated_from` INT UNSIGNED, `escalated_to` INT UNSIGNED NOT NULL, `reason` TEXT, `escalated_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`ticket_id`) REFERENCES `support_tickets`(`ticket_id`)) ENGINE=InnoDB;
CREATE TABLE `ticket_attachments` (`att_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `ticket_id` INT UNSIGNED NOT NULL, `file_name` VARCHAR(200), `file_url` VARCHAR(300), `uploaded_by` INT UNSIGNED, `uploaded_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`ticket_id`) REFERENCES `support_tickets`(`ticket_id`)) ENGINE=InnoDB;
CREATE TABLE `knowledge_base_categories` (`kb_cat_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `cat_name` VARCHAR(80) NOT NULL, `parent_cat_id` SMALLINT UNSIGNED, `display_order` TINYINT UNSIGNED, FOREIGN KEY(`parent_cat_id`) REFERENCES `knowledge_base_categories`(`kb_cat_id`)) ENGINE=InnoDB;
CREATE TABLE `knowledge_base_articles` (`article_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `kb_cat_id` SMALLINT UNSIGNED, `title` VARCHAR(200) NOT NULL, `content` LONGTEXT, `author_id` INT UNSIGNED, `views` INT UNSIGNED DEFAULT 0, `helpful_votes` INT UNSIGNED DEFAULT 0, `unhelpful_votes` INT UNSIGNED DEFAULT 0, `status` ENUM('draft','review','published','archived') DEFAULT 'draft', `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(`kb_cat_id`) REFERENCES `knowledge_base_categories`(`kb_cat_id`), FOREIGN KEY(`author_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `ticket_kb_links` (`link_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `ticket_id` INT UNSIGNED NOT NULL, `article_id` INT UNSIGNED NOT NULL, `linked_by` INT UNSIGNED, `was_helpful` TINYINT(1), FOREIGN KEY(`ticket_id`) REFERENCES `support_tickets`(`ticket_id`), FOREIGN KEY(`article_id`) REFERENCES `knowledge_base_articles`(`article_id`)) ENGINE=InnoDB;
CREATE TABLE `csat_surveys` (`csat_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `ticket_id` INT UNSIGNED NOT NULL, `sent_at` DATETIME, `responded_at` DATETIME, `rating` TINYINT UNSIGNED, `feedback` TEXT, `would_recommend` TINYINT(1), FOREIGN KEY(`ticket_id`) REFERENCES `support_tickets`(`ticket_id`)) ENGINE=InnoDB;
CREATE TABLE `support_teams` (`team_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `team_name` VARCHAR(80) NOT NULL, `team_type` ENUM('tier1','tier2','tier3','specialized','management') DEFAULT 'tier1', `manager_id` INT UNSIGNED) ENGINE=InnoDB;
CREATE TABLE `support_team_members` (`stm_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `team_id` SMALLINT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `joined_date` DATE, `is_active` TINYINT(1) DEFAULT 1, FOREIGN KEY(`team_id`) REFERENCES `support_teams`(`team_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `ticket_merge_history` (`merge_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `primary_ticket_id` INT UNSIGNED NOT NULL, `merged_ticket_id` INT UNSIGNED NOT NULL, `merged_by` INT UNSIGNED, `merged_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`primary_ticket_id`) REFERENCES `support_tickets`(`ticket_id`)) ENGINE=InnoDB;
CREATE TABLE `support_reports` (`report_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `report_name` VARCHAR(100), `period` VARCHAR(20), `total_tickets` INT UNSIGNED, `resolved_tickets` INT UNSIGNED, `avg_resolution_hours` DECIMAL(8,2), `sla_compliance_pct` DECIMAL(5,2), `avg_csat` DECIMAL(4,2), `generated_at` DATETIME, `generated_by` INT UNSIGNED) ENGINE=InnoDB;
CREATE TABLE `chatbot_conversations` (`conv_id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `account_id` INT UNSIGNED, `contact_id` INT UNSIGNED, `session_id` VARCHAR(60), `started_at` DATETIME, `ended_at` DATETIME, `messages_count` SMALLINT UNSIGNED, `escalated_to_ticket_id` INT UNSIGNED, `resolved_by_bot` TINYINT(1) DEFAULT 0, `sentiment` ENUM('positive','neutral','negative'), FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`)) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 16: ANALYTICS & REPORTING (15 tables)
-- ============================================================
CREATE TABLE `analytics_events` (`event_id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `event_name` VARCHAR(100) NOT NULL, `event_category` VARCHAR(60), `account_id` INT UNSIGNED, `contact_id` INT UNSIGNED, `employee_id` INT UNSIGNED, `session_id` VARCHAR(60), `ip_address` VARCHAR(45), `page_url` VARCHAR(300), `referrer_url` VARCHAR(300), `country_id` SMALLINT UNSIGNED, `device_type` ENUM('desktop','mobile','tablet') DEFAULT 'desktop', `browser` VARCHAR(60), `properties` JSON, `occurred_at` DATETIME NOT NULL, FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`contact_id`) REFERENCES `crm_contacts`(`contact_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`country_id`) REFERENCES `countries`(`country_id`)) ENGINE=InnoDB;
CREATE TABLE `kpi_definitions` (`kpi_def_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `kpi_name` VARCHAR(100) NOT NULL, `kpi_category` ENUM('hr','sales','crm','finance','operations','it','support','projects') NOT NULL, `formula` TEXT, `unit` VARCHAR(30), `frequency` ENUM('daily','weekly','monthly','quarterly','annual') DEFAULT 'monthly', `owner_department_id` SMALLINT UNSIGNED, `target_direction` ENUM('higher_is_better','lower_is_better','within_range') DEFAULT 'higher_is_better', FOREIGN KEY(`owner_department_id`) REFERENCES `departments`(`department_id`)) ENGINE=InnoDB;
CREATE TABLE `kpi_metrics` (`metric_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `kpi_def_id` SMALLINT UNSIGNED NOT NULL, `period` VARCHAR(20), `value` DECIMAL(16,4), `target` DECIMAL(16,4), `variance` DECIMAL(16,4), `department_id` SMALLINT UNSIGNED, `employee_id` INT UNSIGNED, `recorded_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`kpi_def_id`) REFERENCES `kpi_definitions`(`kpi_def_id`), FOREIGN KEY(`department_id`) REFERENCES `departments`(`department_id`)) ENGINE=InnoDB;
CREATE TABLE `dashboards` (`dashboard_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `dashboard_name` VARCHAR(100) NOT NULL, `module` VARCHAR(40), `owner_id` INT UNSIGNED, `is_public` TINYINT(1) DEFAULT 0, `layout` JSON, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`owner_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `dashboard_widgets` (`widget_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `dashboard_id` SMALLINT UNSIGNED NOT NULL, `widget_type` ENUM('bar_chart','line_chart','pie_chart','donut','kpi_card','table','gauge','heatmap','funnel') NOT NULL, `widget_title` VARCHAR(100), `data_source` VARCHAR(100), `filters` JSON, `position_x` TINYINT UNSIGNED, `position_y` TINYINT UNSIGNED, `width` TINYINT UNSIGNED, `height` TINYINT UNSIGNED, FOREIGN KEY(`dashboard_id`) REFERENCES `dashboards`(`dashboard_id`)) ENGINE=InnoDB;
CREATE TABLE `reports` (`report_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `report_name` VARCHAR(150) NOT NULL, `module` VARCHAR(40), `report_type` ENUM('standard','custom','scheduled','ad_hoc') DEFAULT 'standard', `created_by` INT UNSIGNED, `query_definition` JSON, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`created_by`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `scheduled_reports` (`sr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `report_id` INT UNSIGNED NOT NULL, `frequency` ENUM('daily','weekly','monthly','quarterly') DEFAULT 'monthly', `recipients` JSON, `next_run` DATETIME, `last_run` DATETIME, `output_format` ENUM('pdf','excel','csv') DEFAULT 'pdf', `is_active` TINYINT(1) DEFAULT 1, FOREIGN KEY(`report_id`) REFERENCES `reports`(`report_id`)) ENGINE=InnoDB;
CREATE TABLE `data_exports` (`export_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `requested_by` INT UNSIGNED NOT NULL, `module` VARCHAR(40), `filters` JSON, `format` ENUM('csv','xlsx','json','pdf') DEFAULT 'csv', `status` ENUM('queued','processing','completed','failed') DEFAULT 'queued', `file_url` VARCHAR(300), `requested_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `completed_at` DATETIME, `row_count` INT UNSIGNED, FOREIGN KEY(`requested_by`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `funnel_analytics` (`funnel_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `funnel_name` VARCHAR(100) NOT NULL, `stage_name` VARCHAR(60) NOT NULL, `period` VARCHAR(20), `entries` INT UNSIGNED, `exits` INT UNSIGNED, `conversion_pct` DECIMAL(5,2), `avg_time_days` DECIMAL(6,2), `recorded_at` DATE) ENGINE=InnoDB;
CREATE TABLE `cohort_analysis` (`cohort_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `cohort_name` VARCHAR(80), `cohort_type` ENUM('acquisition','revenue','churn','engagement') DEFAULT 'acquisition', `cohort_month` VARCHAR(10), `cohort_size` INT UNSIGNED, `period_0` DECIMAL(8,2), `period_1` DECIMAL(8,2), `period_2` DECIMAL(8,2), `period_3` DECIMAL(8,2), `period_6` DECIMAL(8,2), `period_12` DECIMAL(8,2)) ENGINE=InnoDB;
CREATE TABLE `ab_tests` (`test_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `test_name` VARCHAR(150) NOT NULL, `hypothesis` TEXT, `module` VARCHAR(40), `start_date` DATE, `end_date` DATE, `sample_size` INT UNSIGNED, `control_group_pct` TINYINT UNSIGNED DEFAULT 50, `status` ENUM('draft','running','completed','stopped') DEFAULT 'draft', `winner` ENUM('control','variant_a','variant_b','inconclusive')) ENGINE=InnoDB;
CREATE TABLE `ab_test_results` (`result_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `test_id` SMALLINT UNSIGNED NOT NULL, `variant` ENUM('control','variant_a','variant_b') NOT NULL, `participants` INT UNSIGNED, `conversions` INT UNSIGNED, `conversion_rate` DECIMAL(5,4), `revenue` DECIMAL(14,2), `significance_pct` DECIMAL(5,2), FOREIGN KEY(`test_id`) REFERENCES `ab_tests`(`test_id`)) ENGINE=InnoDB;
CREATE TABLE `user_activity_logs` (`log_id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `action` VARCHAR(100) NOT NULL, `module` VARCHAR(40), `entity_type` VARCHAR(60), `entity_id` INT UNSIGNED, `performed_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `ip_address` VARCHAR(45), `browser` VARCHAR(60), `session_id` VARCHAR(60), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `data_quality_rules` (`rule_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `rule_name` VARCHAR(100) NOT NULL, `table_name` VARCHAR(80), `column_name` VARCHAR(80), `rule_type` ENUM('not_null','unique','format','range','referential','consistency') NOT NULL, `condition` TEXT, `severity` ENUM('info','warning','error','critical') DEFAULT 'warning', `is_active` TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE `data_quality_results` (`dqr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `rule_id` SMALLINT UNSIGNED NOT NULL, `run_date` DATE, `total_records` INT UNSIGNED, `passed_records` INT UNSIGNED, `failed_records` INT UNSIGNED, `failure_pct` DECIMAL(5,2), `sample_failures` JSON, FOREIGN KEY(`rule_id`) REFERENCES `data_quality_rules`(`rule_id`)) ENGINE=InnoDB;

