-- ============================================================
--  DOMAIN 17: MARKETING AUTOMATION (12 tables)
-- ============================================================
CREATE TABLE `marketing_channels` (`channel_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `channel_name` VARCHAR(80) NOT NULL, `channel_type` ENUM('digital','offline','social','email','search','display','affiliate') DEFAULT 'digital', `cost_model` ENUM('cpc','cpm','cpa','flat') DEFAULT 'flat', `is_active` TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE `ad_campaigns` (`ad_campaign_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `campaign_id` INT UNSIGNED, `channel_id` SMALLINT UNSIGNED, `ad_name` VARCHAR(150), `ad_type` ENUM('banner','video','text','carousel','sponsored') DEFAULT 'banner', `budget` DECIMAL(12,2), `spent` DECIMAL(12,2) DEFAULT 0, `impressions` INT UNSIGNED DEFAULT 0, `clicks` INT UNSIGNED DEFAULT 0, `conversions` INT UNSIGNED DEFAULT 0, `cpc` DECIMAL(8,4), `ctr` DECIMAL(6,4), `start_date` DATE, `end_date` DATE, `status` ENUM('draft','active','paused','completed') DEFAULT 'draft', FOREIGN KEY(`campaign_id`) REFERENCES `crm_campaigns`(`campaign_id`), FOREIGN KEY(`channel_id`) REFERENCES `marketing_channels`(`channel_id`)) ENGINE=InnoDB;
CREATE TABLE `landing_pages` (`lp_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `page_name` VARCHAR(150), `url` VARCHAR(300), `campaign_id` INT UNSIGNED, `views` INT UNSIGNED DEFAULT 0, `conversions` INT UNSIGNED DEFAULT 0, `bounce_rate` DECIMAL(5,2), `avg_time_sec` SMALLINT UNSIGNED, `status` ENUM('draft','live','archived') DEFAULT 'draft', FOREIGN KEY(`campaign_id`) REFERENCES `crm_campaigns`(`campaign_id`)) ENGINE=InnoDB;
CREATE TABLE `marketing_content` (`content_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `title` VARCHAR(200) NOT NULL, `content_type` ENUM('blog','whitepaper','ebook','case_study','video','webinar','infographic','social_post') NOT NULL, `body` LONGTEXT, `author_id` INT UNSIGNED, `published_at` DATETIME, `status` ENUM('draft','review','published','archived') DEFAULT 'draft', `views` INT UNSIGNED DEFAULT 0, `downloads` INT UNSIGNED DEFAULT 0, `seo_score` TINYINT UNSIGNED, FOREIGN KEY(`author_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `webinars` (`webinar_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `title` VARCHAR(200), `host_id` INT UNSIGNED, `scheduled_at` DATETIME, `duration_mins` SMALLINT UNSIGNED, `platform` VARCHAR(60), `meeting_link` VARCHAR(300), `registrations` INT UNSIGNED DEFAULT 0, `attendees` INT UNSIGNED DEFAULT 0, `recording_url` VARCHAR(300), `status` ENUM('scheduled','live','completed','cancelled') DEFAULT 'scheduled', FOREIGN KEY(`host_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `webinar_registrations` (`wr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `webinar_id` INT UNSIGNED NOT NULL, `contact_id` INT UNSIGNED, `lead_id` INT UNSIGNED, `registered_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `attended` TINYINT(1) DEFAULT 0, `attended_minutes` SMALLINT UNSIGNED, FOREIGN KEY(`webinar_id`) REFERENCES `webinars`(`webinar_id`), FOREIGN KEY(`contact_id`) REFERENCES `crm_contacts`(`contact_id`)) ENGINE=InnoDB;
CREATE TABLE `social_media_posts` (`post_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `platform` ENUM('linkedin','twitter','facebook','instagram','youtube','tiktok') NOT NULL, `content` TEXT, `media_url` VARCHAR(300), `campaign_id` INT UNSIGNED, `posted_by` INT UNSIGNED, `posted_at` DATETIME, `likes` INT UNSIGNED DEFAULT 0, `comments` INT UNSIGNED DEFAULT 0, `shares` INT UNSIGNED DEFAULT 0, `reach` INT UNSIGNED DEFAULT 0, `status` ENUM('draft','scheduled','published') DEFAULT 'draft', FOREIGN KEY(`campaign_id`) REFERENCES `crm_campaigns`(`campaign_id`)) ENGINE=InnoDB;
CREATE TABLE `utm_tracking` (`utm_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `campaign_id` INT UNSIGNED, `utm_source` VARCHAR(80), `utm_medium` VARCHAR(80), `utm_campaign` VARCHAR(80), `utm_term` VARCHAR(80), `utm_content` VARCHAR(80), `sessions` INT UNSIGNED DEFAULT 0, `leads_generated` INT UNSIGNED DEFAULT 0, `revenue` DECIMAL(14,2) DEFAULT 0, FOREIGN KEY(`campaign_id`) REFERENCES `crm_campaigns`(`campaign_id`)) ENGINE=InnoDB;
CREATE TABLE `email_templates` (`et_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `template_name` VARCHAR(100) NOT NULL, `subject` VARCHAR(200), `body_html` LONGTEXT, `body_text` TEXT, `category` ENUM('welcome','nurture','promotion','event','transactional','re_engagement') DEFAULT 'nurture', `created_by` INT UNSIGNED, `open_rate` DECIMAL(5,2), `click_rate` DECIMAL(5,2)) ENGINE=InnoDB;
CREATE TABLE `marketing_attributions` (`attr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `opportunity_id` INT UNSIGNED, `order_id` INT UNSIGNED, `channel_id` SMALLINT UNSIGNED, `campaign_id` INT UNSIGNED, `attribution_model` ENUM('first_touch','last_touch','linear','time_decay','position_based') DEFAULT 'last_touch', `attributed_revenue` DECIMAL(14,2), `attributed_pct` DECIMAL(5,2), FOREIGN KEY(`channel_id`) REFERENCES `marketing_channels`(`channel_id`)) ENGINE=InnoDB;
CREATE TABLE `brand_assets` (`asset_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `asset_name` VARCHAR(150) NOT NULL, `asset_type` ENUM('logo','banner','brochure','video','template','icon','font') NOT NULL, `file_url` VARCHAR(300), `thumbnail_url` VARCHAR(300), `version` VARCHAR(10), `uploaded_by` INT UNSIGNED, `uploaded_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `tags` JSON) ENGINE=InnoDB;
CREATE TABLE `press_releases` (`pr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `title` VARCHAR(200) NOT NULL, `body` LONGTEXT, `published_at` DATE, `contact_person` VARCHAR(100), `distribution_channels` TEXT, `status` ENUM('draft','approved','published') DEFAULT 'draft', `created_by` INT UNSIGNED) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 18: PROCUREMENT (10 tables)
-- ============================================================
CREATE TABLE `vendor_categories` (`vc_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `category_name` VARCHAR(80) NOT NULL, `description` TEXT) ENGINE=InnoDB;
CREATE TABLE `vendor_profiles` (`vp_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `account_id` INT UNSIGNED NOT NULL UNIQUE, `vendor_category_id` SMALLINT UNSIGNED, `vendor_code` VARCHAR(20) UNIQUE, `payment_terms_id` SMALLINT UNSIGNED, `credit_limit` DECIMAL(12,2), `rating` DECIMAL(3,1), `preferred` TINYINT(1) DEFAULT 0, `blacklisted` TINYINT(1) DEFAULT 0, `blacklist_reason` VARCHAR(200), `bank_details_verified` TINYINT(1) DEFAULT 0, FOREIGN KEY(`account_id`) REFERENCES `crm_accounts`(`account_id`), FOREIGN KEY(`vendor_category_id`) REFERENCES `vendor_categories`(`vc_id`), FOREIGN KEY(`payment_terms_id`) REFERENCES `payment_terms`(`term_id`)) ENGINE=InnoDB;
CREATE TABLE `rfqs` (`rfq_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `rfq_number` VARCHAR(30) UNIQUE NOT NULL, `title` VARCHAR(150), `issued_by` INT UNSIGNED, `issue_date` DATE, `deadline` DATE, `status` ENUM('draft','sent','closed','awarded','cancelled') DEFAULT 'draft', `description` TEXT, `terms` TEXT, FOREIGN KEY(`issued_by`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `rfq_items` (`ri_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `rfq_id` INT UNSIGNED NOT NULL, `product_id` INT UNSIGNED, `description` VARCHAR(200), `quantity` INT UNSIGNED, `uom_id` SMALLINT UNSIGNED, `target_price` DECIMAL(12,2), FOREIGN KEY(`rfq_id`) REFERENCES `rfqs`(`rfq_id`)) ENGINE=InnoDB;
CREATE TABLE `rfq_vendors` (`rv_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `rfq_id` INT UNSIGNED NOT NULL, `vendor_id` INT UNSIGNED NOT NULL, `sent_at` DATETIME, `responded_at` DATETIME, `status` ENUM('sent','responded','no_response','declined') DEFAULT 'sent', FOREIGN KEY(`rfq_id`) REFERENCES `rfqs`(`rfq_id`), FOREIGN KEY(`vendor_id`) REFERENCES `vendor_profiles`(`vp_id`)) ENGINE=InnoDB;
CREATE TABLE `vendor_quotations` (`vq_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `rfq_id` INT UNSIGNED NOT NULL, `vendor_id` INT UNSIGNED NOT NULL, `quote_date` DATE, `valid_until` DATE, `total_amount` DECIMAL(14,2), `currency_id` SMALLINT UNSIGNED, `delivery_days` TINYINT UNSIGNED, `status` ENUM('submitted','shortlisted','awarded','rejected') DEFAULT 'submitted', FOREIGN KEY(`rfq_id`) REFERENCES `rfqs`(`rfq_id`), FOREIGN KEY(`vendor_id`) REFERENCES `vendor_profiles`(`vp_id`)) ENGINE=InnoDB;
CREATE TABLE `vendor_evaluations` (`ve_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `vendor_id` INT UNSIGNED NOT NULL, `evaluator_id` INT UNSIGNED NOT NULL, `eval_date` DATE, `quality_score` TINYINT UNSIGNED, `delivery_score` TINYINT UNSIGNED, `price_score` TINYINT UNSIGNED, `service_score` TINYINT UNSIGNED, `overall_score` DECIMAL(4,2), `comments` TEXT, FOREIGN KEY(`vendor_id`) REFERENCES `vendor_profiles`(`vp_id`), FOREIGN KEY(`evaluator_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `procurement_requisitions` (`req_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `req_number` VARCHAR(30) UNIQUE NOT NULL, `requested_by` INT UNSIGNED NOT NULL, `department_id` SMALLINT UNSIGNED, `cost_center_id` SMALLINT UNSIGNED, `required_date` DATE, `status` ENUM('draft','submitted','approved','po_created','cancelled') DEFAULT 'draft', `approved_by` INT UNSIGNED, `total_estimate` DECIMAL(14,2), `budget_code` VARCHAR(30), FOREIGN KEY(`requested_by`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `procurement_req_items` (`pri_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `req_id` INT UNSIGNED NOT NULL, `product_id` INT UNSIGNED, `description` VARCHAR(200), `quantity` INT UNSIGNED, `estimated_price` DECIMAL(12,2), `preferred_vendor_id` INT UNSIGNED, FOREIGN KEY(`req_id`) REFERENCES `procurement_requisitions`(`req_id`)) ENGINE=InnoDB;
CREATE TABLE `vendor_contracts` (`vc_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `vendor_id` INT UNSIGNED NOT NULL, `contract_no` VARCHAR(30) UNIQUE, `contract_type` ENUM('annual','rate_contract','blanket_po','project_based') DEFAULT 'annual', `start_date` DATE, `end_date` DATE, `value` DECIMAL(16,2), `currency_id` SMALLINT UNSIGNED, `status` ENUM('draft','active','expired','terminated') DEFAULT 'draft', `file_url` VARCHAR(300), FOREIGN KEY(`vendor_id`) REFERENCES `vendor_profiles`(`vp_id`)) ENGINE=InnoDB;

