CREATE TABLE `facility_assets` (`fa_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `location_id` SMALLINT UNSIGNED NOT NULL, `asset_name` VARCHAR(120) NOT NULL, `asset_type` ENUM('hvac','elevator','generator','ups','fire_system','cctv','access_control','plumbing','electrical') NOT NULL, `manufacturer` VARCHAR(80), `model` VARCHAR(80), `installation_date` DATE, `warranty_expiry` DATE, `last_service_date` DATE, `next_service_date` DATE, `status` ENUM('operational','maintenance','faulty','decommissioned') DEFAULT 'operational', FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
