CREATE TABLE `room_bookings` (`booking_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `room_id` SMALLINT UNSIGNED NOT NULL, `booked_by` INT UNSIGNED NOT NULL, `booking_date` DATE NOT NULL, `start_time` TIME NOT NULL, `end_time` TIME NOT NULL, `purpose` VARCHAR(200), `attendees_count` TINYINT UNSIGNED, `status` ENUM('confirmed','cancelled','completed','no_show') DEFAULT 'confirmed', `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`room_id`) REFERENCES `meeting_rooms`(`room_id`), FOREIGN KEY(`booked_by`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `visitor_management` (`visitor_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `visitor_name` VARCHAR(120) NOT NULL, `company` VARCHAR(100), `phone` VARCHAR(30), `email` VARCHAR(150), `host_employee_id` INT UNSIGNED NOT NULL, `location_id` SMALLINT UNSIGNED, `purpose` VARCHAR(200), `check_in` DATETIME, `check_out` DATETIME, `badge_no` VARCHAR(20), `id_type` ENUM('passport','aadhar','driving_license','voter_id') DEFAULT 'aadhar', `id_number` VARCHAR(30), FOREIGN KEY(`host_employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `parking_slots` (`slot_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `location_id` SMALLINT UNSIGNED NOT NULL, `slot_number` VARCHAR(10) NOT NULL, `slot_type` ENUM('car','bike','ev','disabled','visitor') DEFAULT 'car', `is_assigned` TINYINT(1) DEFAULT 0, `assigned_to` INT UNSIGNED, FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `access_cards` (`card_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `card_number` VARCHAR(30) UNIQUE NOT NULL, `employee_id` INT UNSIGNED, `issued_date` DATE, `expiry_date` DATE, `access_level` TINYINT UNSIGNED DEFAULT 1, `status` ENUM('active','inactive','lost','expired') DEFAULT 'active', FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `housekeeping_schedule` (`hs_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `location_id` SMALLINT UNSIGNED NOT NULL, `area` VARCHAR(80), `task_type` ENUM('daily_cleaning','deep_clean','sanitization','waste_disposal','pest_control') NOT NULL, `frequency` ENUM('daily','weekly','monthly','quarterly') DEFAULT 'daily', `assigned_to` VARCHAR(80), `last_done` DATETIME, `next_due` DATETIME, FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `utility_bills` (`bill_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `location_id` SMALLINT UNSIGNED NOT NULL, `utility_type` ENUM('electricity','water','gas','internet','phone','waste') NOT NULL, `billing_period` VARCHAR(20), `amount` DECIMAL(10,2), `currency_id` SMALLINT UNSIGNED, `due_date` DATE, `paid_date` DATE, `status` ENUM('pending','paid','overdue') DEFAULT 'pending', FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `office_supplies_requests` (`osr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `location_id` SMALLINT UNSIGNED, `item_name` VARCHAR(100), `quantity` SMALLINT UNSIGNED, `reason` VARCHAR(200), `requested_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `status` ENUM('pending','approved','issued','rejected') DEFAULT 'pending', `approved_by` INT UNSIGNED, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;

