--  DOMAIN 20: HEALTH, SAFETY & ENVIRONMENT (10 tables)
-- ============================================================
CREATE TABLE `hse_incidents` (`hse_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `location_id` SMALLINT UNSIGNED, `incident_type` ENUM('injury','near_miss','property_damage','fire','environmental','illness','fatality') NOT NULL, `severity` ENUM('minor','moderate','serious','critical','fatal') DEFAULT 'minor', `incident_date` DATETIME, `reported_by` INT UNSIGNED, `injured_employee_id` INT UNSIGNED, `description` TEXT, `root_cause` TEXT, `corrective_action` TEXT, `status` ENUM('open','investigating','closed') DEFAULT 'open', `lost_time_days` TINYINT UNSIGNED DEFAULT 0, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `safety_inspections` (`si_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `location_id` SMALLINT UNSIGNED NOT NULL, `inspection_type` ENUM('routine','audit','pre_startup','fire_drill','ergonomic') DEFAULT 'routine', `inspector_id` INT UNSIGNED, `inspection_date` DATE, `score` DECIMAL(5,2), `observations` TEXT, `corrective_actions` TEXT, `next_inspection_date` DATE, `status` ENUM('scheduled','completed') DEFAULT 'scheduled', FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `ppe_inventory` (`ppe_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `ppe_type` ENUM('helmet','gloves','goggles','vest','shoes','mask','earplugs','harness') NOT NULL, `quantity_total` INT UNSIGNED, `quantity_available` INT UNSIGNED, `location_id` SMALLINT UNSIGNED, `last_replenished` DATE, FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `ppe_issuances` (`pis_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `ppe_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `issued_date` DATE, `quantity` TINYINT UNSIGNED DEFAULT 1, `return_date` DATE, `condition_on_return` ENUM('good','worn','damaged'), `issued_by` INT UNSIGNED, FOREIGN KEY(`ppe_id`) REFERENCES `ppe_inventory`(`ppe_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `environmental_metrics` (`em_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `location_id` SMALLINT UNSIGNED, `metric_type` ENUM('carbon_emission','energy_consumption','water_usage','waste_generated','recycling_rate') NOT NULL, `period` VARCHAR(20), `value` DECIMAL(12,4), `unit` VARCHAR(30), `target` DECIMAL(12,4), `recorded_at` DATE, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `fire_safety_equipment` (`fse_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `location_id` SMALLINT UNSIGNED NOT NULL, `equipment_type` ENUM('extinguisher','smoke_detector','sprinkler','alarm','hose_reel','emergency_exit') NOT NULL, `quantity` TINYINT UNSIGNED, `last_inspected` DATE, `next_inspection_date` DATE, `status` ENUM('ok','requires_service','faulty') DEFAULT 'ok', FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `medical_checkup_records` (`mcr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `checkup_type` ENUM('pre_employment','annual','post_illness','fitness_for_duty') DEFAULT 'annual', `checkup_date` DATE, `clinic` VARCHAR(100), `doctor_name` VARCHAR(100), `result` ENUM('fit','fit_with_restrictions','unfit') DEFAULT 'fit', `restrictions` VARCHAR(200), `next_due_date` DATE, `report_url` VARCHAR(300), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `hse_training_records` (`htr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `training_type` ENUM('fire_safety','first_aid','chemical_handling','height_safety','forklift','confined_space','electrical') NOT NULL, `trained_date` DATE, `trainer` VARCHAR(100), `valid_until` DATE, `certificate_no` VARCHAR(60), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `risk_assessments_hse` (`rah_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `location_id` SMALLINT UNSIGNED, `activity` VARCHAR(150) NOT NULL, `hazard` TEXT, `risk_level` ENUM('low','medium','high','extreme') DEFAULT 'medium', `control_measures` TEXT, `residual_risk` ENUM('low','medium','high') DEFAULT 'low', `reviewed_by` INT UNSIGNED, `review_date` DATE, FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `near_miss_reports` (`nmr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `location_id` SMALLINT UNSIGNED NOT NULL, `reported_by` INT UNSIGNED NOT NULL, `report_date` DATE, `description` TEXT, `potential_severity` ENUM('minor','moderate','serious','critical') DEFAULT 'moderate', `corrective_action` TEXT, `status` ENUM('open','resolved') DEFAULT 'open', FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`), FOREIGN KEY(`reported_by`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 21: LEARNING MANAGEMENT (10 tables)
-- ============================================================
CREATE TABLE `lms_courses` (`course_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `course_name` VARCHAR(150) NOT NULL, `category` VARCHAR(80), `level` ENUM('beginner','intermediate','advanced') DEFAULT 'beginner', `duration_hours` SMALLINT UNSIGNED, `credits` TINYINT UNSIGNED, `is_mandatory` TINYINT(1) DEFAULT 0, `passing_score` TINYINT UNSIGNED DEFAULT 70, `max_attempts` TINYINT UNSIGNED DEFAULT 3, `certificate_template_url` VARCHAR(300)) ENGINE=InnoDB;
CREATE TABLE `lms_modules` (`module_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `course_id` INT UNSIGNED NOT NULL, `module_name` VARCHAR(100) NOT NULL, `order_no` TINYINT UNSIGNED, `content_type` ENUM('video','pdf','quiz','scorm','link') DEFAULT 'video', `content_url` VARCHAR(300), `duration_mins` SMALLINT UNSIGNED, `is_mandatory` TINYINT(1) DEFAULT 1, FOREIGN KEY(`course_id`) REFERENCES `lms_courses`(`course_id`)) ENGINE=InnoDB;
CREATE TABLE `lms_enrollments` (`enrollment_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `course_id` INT UNSIGNED NOT NULL, `enrolled_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `due_date` DATE, `completed_at` DATETIME, `progress_pct` DECIMAL(5,2) DEFAULT 0, `final_score` DECIMAL(5,2), `attempts` TINYINT UNSIGNED DEFAULT 0, `status` ENUM('enrolled','in_progress','completed','failed','expired') DEFAULT 'enrolled', `certificate_url` VARCHAR(300), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`course_id`) REFERENCES `lms_courses`(`course_id`)) ENGINE=InnoDB;
CREATE TABLE `lms_module_progress` (`mp_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `enrollment_id` INT UNSIGNED NOT NULL, `module_id` INT UNSIGNED NOT NULL, `started_at` DATETIME, `completed_at` DATETIME, `time_spent_mins` SMALLINT UNSIGNED, `status` ENUM('not_started','in_progress','completed') DEFAULT 'not_started', FOREIGN KEY(`enrollment_id`) REFERENCES `lms_enrollments`(`enrollment_id`), FOREIGN KEY(`module_id`) REFERENCES `lms_modules`(`module_id`)) ENGINE=InnoDB;
CREATE TABLE `lms_quizzes` (`quiz_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `module_id` INT UNSIGNED NOT NULL, `quiz_name` VARCHAR(100), `total_questions` TINYINT UNSIGNED, `passing_score` TINYINT UNSIGNED DEFAULT 70, `time_limit_mins` TINYINT UNSIGNED, `shuffle_questions` TINYINT(1) DEFAULT 1, FOREIGN KEY(`module_id`) REFERENCES `lms_modules`(`module_id`)) ENGINE=InnoDB;
CREATE TABLE `lms_quiz_attempts` (`attempt_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `quiz_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `enrollment_id` INT UNSIGNED, `started_at` DATETIME, `completed_at` DATETIME, `score` DECIMAL(5,2), `passed` TINYINT(1), `answers` JSON, FOREIGN KEY(`quiz_id`) REFERENCES `lms_quizzes`(`quiz_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `learning_paths` (`lp_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `path_name` VARCHAR(150) NOT NULL, `description` TEXT, `target_role_id` SMALLINT UNSIGNED, `total_hours` SMALLINT UNSIGNED, `is_active` TINYINT(1) DEFAULT 1, FOREIGN KEY(`target_role_id`) REFERENCES `job_titles`(`job_title_id`)) ENGINE=InnoDB;
CREATE TABLE `learning_path_courses` (`lpc_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `lp_id` SMALLINT UNSIGNED NOT NULL, `course_id` INT UNSIGNED NOT NULL, `order_no` TINYINT UNSIGNED, `is_mandatory` TINYINT(1) DEFAULT 1, FOREIGN KEY(`lp_id`) REFERENCES `learning_paths`(`lp_id`), FOREIGN KEY(`course_id`) REFERENCES `lms_courses`(`course_id`)) ENGINE=InnoDB;
CREATE TABLE `mentoring_programs` (`mp_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `program_name` VARCHAR(100) NOT NULL, `start_date` DATE, `end_date` DATE, `duration_months` TINYINT UNSIGNED, `objectives` TEXT, `status` ENUM('active','completed','cancelled') DEFAULT 'active') ENGINE=InnoDB;
CREATE TABLE `mentor_mentee` (`mm_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `program_id` SMALLINT UNSIGNED NOT NULL, `mentor_id` INT UNSIGNED NOT NULL, `mentee_id` INT UNSIGNED NOT NULL, `start_date` DATE, `end_date` DATE, `meeting_frequency` ENUM('weekly','bi_weekly','monthly') DEFAULT 'bi_weekly', `status` ENUM('active','completed','discontinued') DEFAULT 'active', FOREIGN KEY(`program_id`) REFERENCES `mentoring_programs`(`mp_id`), FOREIGN KEY(`mentor_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`mentee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 22: CANTEEN & CATERING (8 tables)
-- ============================================================
CREATE TABLE `canteen_locations` (`cl_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `location_id` SMALLINT UNSIGNED NOT NULL, `canteen_name` VARCHAR(80) NOT NULL, `capacity` SMALLINT UNSIGNED, `vendor` VARCHAR(100), `is_active` TINYINT(1) DEFAULT 1, FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `menu_items` (`item_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `canteen_id` SMALLINT UNSIGNED NOT NULL, `item_name` VARCHAR(100) NOT NULL, `category` ENUM('breakfast','lunch','dinner','snacks','beverages','special') DEFAULT 'lunch', `is_veg` TINYINT(1) DEFAULT 1, `price` DECIMAL(6,2), `calories` SMALLINT UNSIGNED, `available_days` SET('Mon','Tue','Wed','Thu','Fri','Sat') DEFAULT 'Mon,Tue,Wed,Thu,Fri', `is_active` TINYINT(1) DEFAULT 1, FOREIGN KEY(`canteen_id`) REFERENCES `canteen_locations`(`cl_id`)) ENGINE=InnoDB;
CREATE TABLE `canteen_orders` (`order_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `canteen_id` SMALLINT UNSIGNED NOT NULL, `order_date` DATE NOT NULL, `order_type` ENUM('dine_in','takeaway','pre_order') DEFAULT 'dine_in', `total_amount` DECIMAL(8,2), `payment_mode` ENUM('cash','card','wallet','salary_deduction') DEFAULT 'cash', `status` ENUM('placed','prepared','collected','cancelled') DEFAULT 'placed', `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`), FOREIGN KEY(`canteen_id`) REFERENCES `canteen_locations`(`cl_id`)) ENGINE=InnoDB;
CREATE TABLE `canteen_order_items` (`coi_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `order_id` INT UNSIGNED NOT NULL, `item_id` INT UNSIGNED NOT NULL, `quantity` TINYINT UNSIGNED DEFAULT 1, `unit_price` DECIMAL(6,2), `line_total` DECIMAL(8,2), FOREIGN KEY(`order_id`) REFERENCES `canteen_orders`(`order_id`), FOREIGN KEY(`item_id`) REFERENCES `menu_items`(`item_id`)) ENGINE=InnoDB;
CREATE TABLE `meal_coupons` (`coupon_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `coupon_type` ENUM('breakfast','lunch','dinner','snack') DEFAULT 'lunch', `issued_date` DATE, `valid_date` DATE, `value` DECIMAL(6,2), `status` ENUM('unused','used','expired') DEFAULT 'unused', `used_at` DATETIME, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `canteen_feedback` (`feedback_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `canteen_id` SMALLINT UNSIGNED, `item_id` INT UNSIGNED, `rating` TINYINT UNSIGNED, `comment` TEXT, `submitted_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `catering_orders` (`co_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `event_name` VARCHAR(150), `event_date` DATE, `guests_count` SMALLINT UNSIGNED, `menu_type` ENUM('veg','non_veg','mixed','vegan') DEFAULT 'mixed', `vendor` VARCHAR(100), `amount` DECIMAL(10,2), `currency_id` SMALLINT UNSIGNED, `status` ENUM('requested','confirmed','delivered','cancelled') DEFAULT 'requested', FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`)) ENGINE=InnoDB;
CREATE TABLE `dietary_preferences` (`dp_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL UNIQUE, `is_vegetarian` TINYINT(1) DEFAULT 0, `is_vegan` TINYINT(1) DEFAULT 0, `allergies` TEXT, `dietary_restrictions` TEXT, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 23: EVENTS & CORPORATE ACTIVITIES (8 tables)
-- ============================================================
CREATE TABLE `corporate_events` (`event_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `company_id` SMALLINT UNSIGNED NOT NULL, `event_name` VARCHAR(200) NOT NULL, `event_type` ENUM('town_hall','training','team_outing','conference','festival','sport','award_ceremony','annual_day','launch') NOT NULL, `event_date` DATE NOT NULL, `location_id` SMALLINT UNSIGNED, `external_venue` VARCHAR(200), `organizer_id` INT UNSIGNED, `budget` DECIMAL(12,2), `actual_spend` DECIMAL(12,2), `max_attendees` SMALLINT UNSIGNED, `status` ENUM('planning','confirmed','completed','cancelled') DEFAULT 'planning', `description` TEXT, FOREIGN KEY(`company_id`) REFERENCES `companies`(`company_id`), FOREIGN KEY(`organizer_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `event_registrations` (`er_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `event_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED NOT NULL, `registered_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `attended` TINYINT(1) DEFAULT 0, `meal_preference` ENUM('veg','non_veg','vegan') DEFAULT 'veg', `t_shirt_size` ENUM('xs','s','m','l','xl','xxl'), FOREIGN KEY(`event_id`) REFERENCES `corporate_events`(`event_id`), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `event_budget_items` (`ebi_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `event_id` INT UNSIGNED NOT NULL, `item_description` VARCHAR(150), `vendor` VARCHAR(100), `estimated_cost` DECIMAL(10,2), `actual_cost` DECIMAL(10,2), `paid` TINYINT(1) DEFAULT 0, FOREIGN KEY(`event_id`) REFERENCES `corporate_events`(`event_id`)) ENGINE=InnoDB;
CREATE TABLE `event_feedback` (`ef_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `event_id` INT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED, `overall_rating` TINYINT UNSIGNED, `content_rating` TINYINT UNSIGNED, `venue_rating` TINYINT UNSIGNED, `comments` TEXT, `submitted_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`event_id`) REFERENCES `corporate_events`(`event_id`)) ENGINE=InnoDB;
CREATE TABLE `employee_surveys` (`survey_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `survey_name` VARCHAR(150) NOT NULL, `survey_type` ENUM('engagement','satisfaction','pulse','onboarding','exit','esat','360') DEFAULT 'engagement', `start_date` DATE, `end_date` DATE, `is_anonymous` TINYINT(1) DEFAULT 1, `created_by` INT UNSIGNED, `status` ENUM('draft','active','closed','archived') DEFAULT 'draft') ENGINE=InnoDB;
CREATE TABLE `survey_questions` (`sq_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `survey_id` SMALLINT UNSIGNED NOT NULL, `question_text` TEXT NOT NULL, `question_type` ENUM('rating','multiple_choice','text','yes_no','nps') DEFAULT 'rating', `options` JSON, `is_mandatory` TINYINT(1) DEFAULT 1, `order_no` TINYINT UNSIGNED, FOREIGN KEY(`survey_id`) REFERENCES `employee_surveys`(`survey_id`)) ENGINE=InnoDB;
CREATE TABLE `survey_responses` (`sr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `survey_id` SMALLINT UNSIGNED NOT NULL, `employee_id` INT UNSIGNED, `submitted_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `completion_time_secs` SMALLINT UNSIGNED, FOREIGN KEY(`survey_id`) REFERENCES `employee_surveys`(`survey_id`)) ENGINE=InnoDB;
CREATE TABLE `survey_answers` (`sa_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `sr_id` INT UNSIGNED NOT NULL, `sq_id` INT UNSIGNED NOT NULL, `answer_text` TEXT, `answer_rating` TINYINT UNSIGNED, `answer_choice` VARCHAR(100), FOREIGN KEY(`sr_id`) REFERENCES `survey_responses`(`sr_id`), FOREIGN KEY(`sq_id`) REFERENCES `survey_questions`(`sq_id`)) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 24: POINT OF SALE (8 tables)
-- ============================================================
CREATE TABLE `pos_terminals` (`terminal_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `location_id` SMALLINT UNSIGNED NOT NULL, `terminal_name` VARCHAR(60), `terminal_type` ENUM('fixed','mobile','kiosk','online') DEFAULT 'fixed', `serial_no` VARCHAR(60), `is_active` TINYINT(1) DEFAULT 1, `last_synced` DATETIME, FOREIGN KEY(`location_id`) REFERENCES `locations`(`location_id`)) ENGINE=InnoDB;
CREATE TABLE `pos_sessions` (`session_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `terminal_id` SMALLINT UNSIGNED NOT NULL, `cashier_id` INT UNSIGNED NOT NULL, `opened_at` DATETIME, `closed_at` DATETIME, `opening_cash` DECIMAL(10,2), `closing_cash` DECIMAL(10,2), `total_sales` DECIMAL(14,2), `total_transactions` INT UNSIGNED, `status` ENUM('open','closed') DEFAULT 'open', FOREIGN KEY(`terminal_id`) REFERENCES `pos_terminals`(`terminal_id`), FOREIGN KEY(`cashier_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `pos_transactions` (`txn_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `session_id` INT UNSIGNED NOT NULL, `receipt_number` VARCHAR(30) UNIQUE NOT NULL, `txn_datetime` DATETIME DEFAULT CURRENT_TIMESTAMP, `subtotal` DECIMAL(12,2), `discount` DECIMAL(10,2) DEFAULT 0, `tax` DECIMAL(10,2), `total` DECIMAL(12,2), `payment_method` ENUM('cash','card','upi','wallet','coupon','mixed') DEFAULT 'cash', `status` ENUM('completed','voided','refunded') DEFAULT 'completed', `customer_contact_id` INT UNSIGNED, FOREIGN KEY(`session_id`) REFERENCES `pos_sessions`(`session_id`)) ENGINE=InnoDB;
CREATE TABLE `pos_transaction_items` (`pti_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `txn_id` INT UNSIGNED NOT NULL, `product_id` INT UNSIGNED NOT NULL, `quantity` INT UNSIGNED NOT NULL, `unit_price` DECIMAL(12,2), `discount` DECIMAL(8,2) DEFAULT 0, `line_total` DECIMAL(12,2), FOREIGN KEY(`txn_id`) REFERENCES `pos_transactions`(`txn_id`), FOREIGN KEY(`product_id`) REFERENCES `products`(`product_id`)) ENGINE=InnoDB;
CREATE TABLE `pos_cash_movements` (`cm_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `session_id` INT UNSIGNED NOT NULL, `movement_type` ENUM('pay_in','pay_out','float') DEFAULT 'pay_in', `amount` DECIMAL(10,2) NOT NULL, `reason` VARCHAR(150), `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`session_id`) REFERENCES `pos_sessions`(`session_id`)) ENGINE=InnoDB;
CREATE TABLE `loyalty_programs` (`lp_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `program_name` VARCHAR(100) NOT NULL, `points_per_amount` DECIMAL(6,4), `redemption_value` DECIMAL(8,4), `min_points_redeem` INT UNSIGNED, `expiry_months` TINYINT UNSIGNED, `is_active` TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE `loyalty_accounts` (`la_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `program_id` SMALLINT UNSIGNED NOT NULL, `contact_id` INT UNSIGNED, `card_number` VARCHAR(30) UNIQUE, `total_points_earned` INT UNSIGNED DEFAULT 0, `total_points_redeemed` INT UNSIGNED DEFAULT 0, `balance_points` INT UNSIGNED DEFAULT 0, `tier` ENUM('bronze','silver','gold','platinum') DEFAULT 'bronze', `joined_date` DATE, FOREIGN KEY(`program_id`) REFERENCES `loyalty_programs`(`lp_id`), FOREIGN KEY(`contact_id`) REFERENCES `crm_contacts`(`contact_id`)) ENGINE=InnoDB;
CREATE TABLE `loyalty_transactions` (`lt_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `la_id` INT UNSIGNED NOT NULL, `txn_id` INT UNSIGNED, `txn_type` ENUM('earn','redeem','expire','adjustment') NOT NULL, `points` INT NOT NULL, `balance_after` INT UNSIGNED, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`la_id`) REFERENCES `loyalty_accounts`(`la_id`)) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 25: USER ACCESS & SECURITY (8 tables)
-- ============================================================
CREATE TABLE `roles` (`role_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `role_name` VARCHAR(60) NOT NULL UNIQUE, `description` TEXT, `module` VARCHAR(40), `is_system_role` TINYINT(1) DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE `permissions` (`perm_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `perm_name` VARCHAR(100) NOT NULL, `module` VARCHAR(40), `action` ENUM('view','create','edit','delete','approve','export','admin') NOT NULL, `description` VARCHAR(200)) ENGINE=InnoDB;
CREATE TABLE `role_permissions` (`rp_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `role_id` SMALLINT UNSIGNED NOT NULL, `perm_id` INT UNSIGNED NOT NULL, `granted_by` INT UNSIGNED, `granted_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`role_id`) REFERENCES `roles`(`role_id`), FOREIGN KEY(`perm_id`) REFERENCES `permissions`(`perm_id`)) ENGINE=InnoDB;
CREATE TABLE `user_accounts` (`user_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL UNIQUE, `username` VARCHAR(60) NOT NULL UNIQUE, `email` VARCHAR(150) NOT NULL UNIQUE, `password_hash` VARCHAR(255), `mfa_enabled` TINYINT(1) DEFAULT 0, `mfa_secret` VARCHAR(60), `last_login` DATETIME, `last_password_change` DATE, `failed_login_attempts` TINYINT UNSIGNED DEFAULT 0, `locked_until` DATETIME, `is_active` TINYINT(1) DEFAULT 1, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `user_roles` (`ur_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `user_id` INT UNSIGNED NOT NULL, `role_id` SMALLINT UNSIGNED NOT NULL, `assigned_by` INT UNSIGNED, `assigned_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `expires_at` DATETIME, FOREIGN KEY(`user_id`) REFERENCES `user_accounts`(`user_id`), FOREIGN KEY(`role_id`) REFERENCES `roles`(`role_id`)) ENGINE=InnoDB;
CREATE TABLE `login_sessions` (`session_id` VARCHAR(60) PRIMARY KEY, `user_id` INT UNSIGNED NOT NULL, `ip_address` VARCHAR(45), `device` VARCHAR(100), `location` VARCHAR(100), `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, `expires_at` DATETIME, `is_active` TINYINT(1) DEFAULT 1, FOREIGN KEY(`user_id`) REFERENCES `user_accounts`(`user_id`)) ENGINE=InnoDB;
CREATE TABLE `password_reset_tokens` (`token_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `user_id` INT UNSIGNED NOT NULL, `token_hash` VARCHAR(255) NOT NULL, `expires_at` DATETIME NOT NULL, `used_at` DATETIME, `ip_address` VARCHAR(45), FOREIGN KEY(`user_id`) REFERENCES `user_accounts`(`user_id`)) ENGINE=InnoDB;
CREATE TABLE `api_keys` (`key_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `user_id` INT UNSIGNED, `key_name` VARCHAR(80), `key_hash` VARCHAR(255) NOT NULL, `permissions` JSON, `last_used` DATETIME, `expires_at` DATETIME, `is_active` TINYINT(1) DEFAULT 1, `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(`user_id`) REFERENCES `user_accounts`(`user_id`)) ENGINE=InnoDB;

-- ============================================================
--  DOMAIN 26: MISCELLANEOUS OPERATIONAL (additional tables)
-- ============================================================
CREATE TABLE `postal_addresses` (`pa_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `entity_type` ENUM('company','employee','candidate','vendor','customer') NOT NULL, `entity_id` INT UNSIGNED NOT NULL, `address_type` ENUM('permanent','current','mailing','billing','shipping') DEFAULT 'current', `address_line1` VARCHAR(200), `address_line2` VARCHAR(200), `city_id` INT UNSIGNED, `state_id` SMALLINT UNSIGNED, `postal_code` VARCHAR(20), `country_id` SMALLINT UNSIGNED, `is_primary` TINYINT(1) DEFAULT 0, FOREIGN KEY(`city_id`) REFERENCES `cities`(`city_id`), FOREIGN KEY(`state_id`) REFERENCES `states`(`state_id`), FOREIGN KEY(`country_id`) REFERENCES `countries`(`country_id`)) ENGINE=InnoDB;
CREATE TABLE `communication_logs` (`comm_id` BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `direction` ENUM('inbound','outbound') DEFAULT 'outbound', `channel` ENUM('email','phone','whatsapp','sms','postal','meeting','chat') NOT NULL, `from_entity` VARCHAR(60), `to_entity` VARCHAR(60), `subject` VARCHAR(200), `summary` TEXT, `related_module` VARCHAR(40), `related_id` INT UNSIGNED, `logged_by` INT UNSIGNED, `logged_at` DATETIME DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE `subscription_billings` (`sb_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `subscription_id` INT UNSIGNED NOT NULL, `billing_date` DATE NOT NULL, `amount` DECIMAL(12,2), `currency_id` SMALLINT UNSIGNED, `invoice_id` INT UNSIGNED, `status` ENUM('pending','paid','failed','refunded') DEFAULT 'pending', FOREIGN KEY(`subscription_id`) REFERENCES `account_subscriptions`(`subscription_id`), FOREIGN KEY(`invoice_id`) REFERENCES `invoices`(`invoice_id`)) ENGINE=InnoDB;
CREATE TABLE `document_approvals` (`da_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `doc_type` VARCHAR(60), `doc_id` INT UNSIGNED NOT NULL, `approver_id` INT UNSIGNED NOT NULL, `approval_level` TINYINT UNSIGNED DEFAULT 1, `status` ENUM('pending','approved','rejected','delegated') DEFAULT 'pending', `comments` TEXT, `actioned_at` DATETIME, FOREIGN KEY(`approver_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `workflow_templates` (`wf_id` SMALLINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `workflow_name` VARCHAR(100) NOT NULL, `module` VARCHAR(40), `trigger_event` VARCHAR(80), `steps` JSON, `is_active` TINYINT(1) DEFAULT 1) ENGINE=InnoDB;
