CREATE TABLE `driver_behavior_scores` (`dbs_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `employee_id` INT UNSIGNED NOT NULL, `vehicle_id` INT UNSIGNED, `score_date` DATE, `harsh_braking_events` TINYINT UNSIGNED DEFAULT 0, `harsh_acceleration_events` TINYINT UNSIGNED DEFAULT 0, `speeding_events` TINYINT UNSIGNED DEFAULT 0, `overall_score` DECIMAL(4,2), `period` VARCHAR(20), FOREIGN KEY(`employee_id`) REFERENCES `employees`(`employee_id`)) ENGINE=InnoDB;
CREATE TABLE `traffic_violations` (`tv_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `vehicle_id` INT UNSIGNED NOT NULL, `driver_id` INT UNSIGNED, `violation_date` DATE, `violation_type` VARCHAR(80), `fine_amount` DECIMAL(8,2), `currency_id` SMALLINT UNSIGNED, `paid` TINYINT(1) DEFAULT 0, `paid_date` DATE, `remarks` VARCHAR(200), FOREIGN KEY(`vehicle_id`) REFERENCES `vehicles`(`vehicle_id`)) ENGINE=InnoDB;
