CREATE TABLE `vehicle_renewals` (`vr_id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, `vehicle_id` INT UNSIGNED NOT NULL, `renewal_type` ENUM('insurance','road_tax','puc','fitness','permit') NOT NULL, `due_date` DATE, `renewed_date` DATE, `amount` DECIMAL(8,2), `vendor` VARCHAR(80), `new_expiry_date` DATE, `status` ENUM('upcoming','completed','overdue') DEFAULT 'upcoming', FOREIGN KEY(`vehicle_id`) REFERENCES `vehicles`(`vehicle_id`)) ENGINE=InnoDB;

