USE mega_hrms_crm;
SHOW TABLES;
SELECT ap.ap_id AS ap_id, ap.due_date AS due_date, ap.status AS status FROM `accounts_payable` ap INNER JOIN `crm_accounts` crm ON ap.vendor_account_id = crm.account_id WHERE ap.status = 'overdue' AND ap.due_date < CURDATE() UNION SELECT ar.ar_id AS ap_id, ar.due_date AS due_date, ar.status AS status FROM `accounts_receivable` ar INNER JOIN `crm_accounts` crm ON ar.customer_account_id = crm.account_id WHERE ar.status = 'overdue' AND ar.due_date < CURDATE() LIMIT 100;